import React, { useState, useEffect } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import soundEffects from '../../utils/soundEffects';

// 队伍组建界面 - 支持1-3人动态组队
const TeamFormationModal = ({ isOpen, onClose, onConfirm }) => {
  const dispatch = useDispatch();
  const character = useSelector(state => state.character);
  const pets = useSelector(state => state.character.pets || []);

  const [selectedTeam, setSelectedTeam] = useState([]);
  const [formations, setFormations] = useState([]);
  const [selectedFormation, setSelectedFormation] = useState(0);

  // 可用的队伍成员类型
  const availableMembers = [
    {
      id: 'main-character',
      type: 'main',
      name: character.name || '道友', 
      level: character.level || 20,
      element: character.element || '金',
      avatar: '🧙‍♂️',
      required: true, // 主角必须上场
      stats: {
        hp: 1000 + character.level * 50,
        mp: 500 + character.level * 25,
        attack: 120 + character.level * 5,
        defense: 80 + character.level * 3
      },
      skills: ['普通攻击', '五行攻击', '金刚护体', '治疗术'],
      description: '队伍核心，拥有强大的五行法术'
    },
    ...pets.slice(0, 2).map((pet, index) => ({
      id: `pet-${index}`,
      type: 'pet',
      name: pet.name,
      level: pet.level,
      element: pet.element,
      avatar: getPetAvatar(pet.type),
      required: false,
      stats: {
        hp: 600 + pet.level * 30,
        mp: 200 + pet.level * 15,
        attack: 100 + pet.level * 4,
        defense: 60 + pet.level * 2
      },
      skills: ['撕咬', '元素吐息', '守护'],
      description: `${pet.element}系宠物，擅长辅助作战`
    })),
    // 可招募的伙伴NPC
    {
      id: 'partner-warrior',
      type: 'partner',
      name: '剑客',
      level: Math.max(1, character.level - 3),
      element: '金',
      avatar: '⚔️',
      required: false,
      recruitCost: 100,
      stats: {
        hp: 800 + character.level * 35,
        mp: 150 + character.level * 10,
        attack: 140 + character.level * 6,
        defense: 100 + character.level * 4
      },
      skills: ['剑气斩', '铁布衫', '旋风剑'],
      description: '近战专家，物理攻击力强'
    },
    {
      id: 'partner-mage',
      type: 'partner',
      name: '法师',
      level: Math.max(1, character.level - 2),
      element: '火',
      avatar: '🔥',
      required: false,
      recruitCost: 150,
      stats: {
        hp: 500 + character.level * 25,
        mp: 800 + character.level * 40,
        attack: 160 + character.level * 8,
        defense: 50 + character.level * 2
      },
      skills: ['火球术', '治疗术', '法力护盾'],
      description: '法术专家，群攻和治疗并重'
    }
  ];

  // 预设阵型配置
  const formationConfigs = [
    {
      name: '均衡阵型',
      description: '攻守平衡，适合大多数战斗',
      positions: [
        { role: 'main', position: 0, description: '主角前排输出' },
        { role: 'any', position: 1, description: '左翼支援' },
        { role: 'any', position: 2, description: '右翼防护' }
      ],
      bonuses: { attack: 1.1, defense: 1.1 }
    },
    {
      name: '攻击阵型',
      description: '全力进攻，快速解决战斗',
      positions: [
        { role: 'any', position: 0, description: '前排强攻' },
        { role: 'main', position: 1, description: '主角法术支援' },
        { role: 'any', position: 2, description: '右翼突击' }
      ],
      bonuses: { attack: 1.3, defense: 0.9 }
    },
    {
      name: '防御阵型',
      description: '稳守反击，持久作战',
      positions: [
        { role: 'any', position: 1, description: '左翼防守' },
        { role: 'main', position: 0, description: '主角居中调度' },
        { role: 'any', position: 2, description: '右翼防守' }
      ],
      bonuses: { attack: 0.9, defense: 1.3 }
    }
  ];

  // 获取宠物头像
  function getPetAvatar(petType) {
    const avatars = {
      dragon: '🐲',
      phoenix: '🦅', 
      tiger: '🐅',
      turtle: '🐢',
      snake: '🐍'
    };
    return avatars[petType] || '🐲';
  }

  // 初始化选择主角
  useEffect(() => {
    if (isOpen) {
      const mainChar = availableMembers.find(m => m.type === 'main');
      setSelectedTeam([mainChar]);
      setFormations(formationConfigs);
    }
  }, [isOpen]);

  // 处理成员选择
  const handleMemberSelect = (member) => {
    soundEffects.playButtonClick();
    
    if (member.required) return; // 主角不能取消选择

    const isSelected = selectedTeam.some(m => m.id === member.id);
    
    if (isSelected) {
      // 移除成员
      setSelectedTeam(prev => prev.filter(m => m.id !== member.id));
    } else if (selectedTeam.length < 3) {
      // 添加成员
      setSelectedTeam(prev => [...prev, member]);
    } else {
      soundEffects.playError();
    }
  };

  // 确认队伍配置
  const handleConfirm = () => {
    if (selectedTeam.length === 0) {
      soundEffects.playError();
      return;
    }

    soundEffects.playButtonClick();
    
    // 应用阵型加成
    const formation = formations[selectedFormation];
    const enhancedTeam = selectedTeam.map((member, index) => ({
      ...member,
      position: index,
      formationBonus: formation.bonuses,
      stats: {
        ...member.stats,
        attack: Math.floor(member.stats.attack * formation.bonuses.attack),
        defense: Math.floor(member.stats.defense * formation.bonuses.defense)
      }
    }));

    onConfirm(enhancedTeam, formation);
  };

  // 渲染成员卡片
  const renderMemberCard = (member) => {
    const isSelected = selectedTeam.some(m => m.id === member.id);
    const isRecruitable = member.recruitCost && character.gold >= member.recruitCost;
    const canSelect = member.required || isSelected || selectedTeam.length < 3;

    return (
      <div
        key={member.id}
        onClick={() => canSelect && handleMemberSelect(member)}
        style={{
          border: isSelected 
            ? '3px solid #FFD700'
            : member.required
              ? '2px solid #32CD32'
              : canSelect
                ? '1px solid rgba(186, 85, 211, 0.4)'
                : '1px solid #666',
          borderRadius: '12px',
          padding: '12px',
          background: isSelected
            ? 'linear-gradient(135deg, rgba(255,215,0,0.2), rgba(255,165,0,0.1))'
            : 'linear-gradient(135deg, #2d1b4a, #3d2759)',
          cursor: canSelect ? 'pointer' : 'not-allowed',
          transition: 'all 0.3s ease',
          opacity: canSelect ? 1 : 0.5,
          transform: isSelected ? 'scale(1.02)' : 'scale(1)',
          position: 'relative'
        }}
      >
        {/* 必选标识 */}
        {member.required && (
          <div style={{
            position: 'absolute',
            top: '-8px',
            right: '-8px',
            background: '#32CD32',
            borderRadius: '50%',
            width: '20px',
            height: '20px',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontSize: '10px',
            fontWeight: 'bold'
          }}>
            ✓
          </div>
        )}

        {/* 招募费用 */}
        {member.recruitCost && (
          <div style={{
            position: 'absolute',
            top: '8px',
            right: '8px',
            background: isRecruitable ? '#FFD700' : '#666',
            borderRadius: '10px',
            padding: '2px 6px',
            fontSize: '8px',
            fontWeight: 'bold',
            color: '#000'
          }}>
            💰{member.recruitCost}
          </div>
        )}

        {/* 头像和基础信息 */}
        <div style={{ display: 'flex', alignItems: 'center', marginBottom: '8px' }}>
          <div style={{
            width: '50px',
            height: '50px',
            borderRadius: '50%',
            background: `linear-gradient(135deg, ${getElementColor(member.element)}, ${getElementColor(member.element)}88)`,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontSize: '24px',
            marginRight: '12px'
          }}>
            {member.avatar}
          </div>
          
          <div style={{ flex: 1 }}>
            <div style={{ 
              color: '#FFD700', 
              fontSize: '14px', 
              fontWeight: 'bold',
              marginBottom: '2px' 
            }}>
              {member.name}
            </div>
            <div style={{ 
              color: '#DDA0DD', 
              fontSize: '10px',
              marginBottom: '4px'
            }}>
              Lv.{member.level} • {member.element}系 • {member.type === 'main' ? '主角' : member.type === 'pet' ? '宠物' : '伙伴'}
            </div>
          </div>
        </div>

        {/* 属性预览 */}
        <div style={{
          display: 'grid',
          gridTemplateColumns: '1fr 1fr',
          gap: '4px',
          fontSize: '9px',
          color: '#DDA0DD',
          marginBottom: '8px'
        }}>
          <div>❤️ {member.stats.hp}</div>
          <div>💙 {member.stats.mp}</div>
          <div>⚔️ {member.stats.attack}</div>
          <div>🛡️ {member.stats.defense}</div>
        </div>

        {/* 技能预览 */}
        <div style={{ fontSize: '8px', color: '#BA55D3', marginBottom: '8px' }}>
          💫 {member.skills.slice(0, 3).join(' • ')}
        </div>

        {/* 描述 */}
        <div style={{ 
          fontSize: '8px', 
          color: '#DDA0DD', 
          fontStyle: 'italic',
          lineHeight: '1.2'
        }}>
          {member.description}
        </div>
      </div>
    );
  };

  // 获取元素颜色
  const getElementColor = (element) => {
    const colors = {
      '金': '#FFD700',
      '木': '#32CD32', 
      '水': '#4169E1',
      '火': '#FF6B6B',
      '土': '#DEB887',
      '雷': '#9370DB',
      '风': '#87CEEB'
    };
    return colors[element] || '#BA55D3';
  };

  if (!isOpen) return null;

  return (
    <div style={{
      position: 'fixed',
      top: 0,
      left: 0,
      width: '100vw',
      height: '100vh',
      background: 'rgba(0, 0, 0, 0.8)',
      zIndex: 2000,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center'
    }}>
      <div style={{
        width: '90vw',
        maxWidth: '400px',
        maxHeight: '90vh',
        background: 'linear-gradient(135deg, #1a0f2e, #2d1b4a)',
        borderRadius: '20px',
        border: '2px solid rgba(186, 85, 211, 0.6)',
        boxShadow: '0 10px 50px rgba(186, 85, 211, 0.3)',
        overflow: 'hidden'
      }}>
        
        {/* 标题栏 */}
        <div style={{
          background: 'linear-gradient(135deg, #4a2c5a, #5d3a6b)',
          padding: '15px 20px',
          borderBottom: '1px solid rgba(186, 85, 211, 0.3)',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center'
        }}>
          <div style={{ color: '#FFD700', fontSize: '16px', fontWeight: 'bold' }}>
            🏆 组建战队 (最多3人)
          </div>
          <button
            onClick={onClose}
            style={{
              background: 'none',
              border: 'none',
              color: '#DDA0DD',
              fontSize: '18px',
              cursor: 'pointer'
            }}
          >
            ✕
          </button>
        </div>

        {/* 内容区域 */}
        <div style={{
          padding: '20px',
          maxHeight: 'calc(90vh - 140px)',
          overflowY: 'auto'
        }}>
          
          {/* 当前队伍概览 */}
          <div style={{ marginBottom: '20px' }}>
            <div style={{ 
              color: '#BA55D3', 
              fontSize: '14px', 
              fontWeight: 'bold', 
              marginBottom: '10px' 
            }}>
              当前队伍 ({selectedTeam.length}/3)
            </div>
            <div style={{
              display: 'flex',
              gap: '8px',
              flexWrap: 'wrap'
            }}>
              {selectedTeam.map((member, index) => (
                <div key={member.id} style={{
                  background: 'rgba(255, 215, 0, 0.2)',
                  border: '1px solid #FFD700',
                  borderRadius: '8px',
                  padding: '6px 10px',
                  fontSize: '10px',
                  color: '#FFD700',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '4px'
                }}>
                  {member.avatar} {member.name}
                  <span style={{ color: '#DDA0DD' }}>
                    (位置{index + 1})
                  </span>
                </div>
              ))}
            </div>
          </div>

          {/* 阵型选择 */}
          <div style={{ marginBottom: '20px' }}>
            <div style={{ 
              color: '#BA55D3', 
              fontSize: '14px', 
              fontWeight: 'bold', 
              marginBottom: '10px' 
            }}>
              选择阵型
            </div>
            <div style={{
              display: 'grid',
              gridTemplateColumns: '1fr',
              gap: '8px'
            }}>
              {formations.map((formation, index) => (
                <div
                  key={index}
                  onClick={() => {
                    setSelectedFormation(index);
                    soundEffects.playButtonClick();
                  }}
                  style={{
                    border: selectedFormation === index 
                      ? '2px solid #FFD700' 
                      : '1px solid rgba(186, 85, 211, 0.4)',
                    borderRadius: '8px',
                    padding: '10px',
                    background: selectedFormation === index
                      ? 'rgba(255, 215, 0, 0.1)'
                      : 'rgba(61, 39, 89, 0.5)',
                    cursor: 'pointer',
                    transition: 'all 0.3s ease'
                  }}
                >
                  <div style={{ 
                    color: '#FFD700', 
                    fontSize: '12px', 
                    fontWeight: 'bold',
                    marginBottom: '4px'
                  }}>
                    {formation.name}
                  </div>
                  <div style={{ 
                    color: '#DDA0DD', 
                    fontSize: '10px',
                    marginBottom: '6px'
                  }}>
                    {formation.description}
                  </div>
                  <div style={{ 
                    color: '#BA55D3', 
                    fontSize: '9px',
                    display: 'flex',
                    justifyContent: 'space-between'
                  }}>
                    <span>⚔️ 攻击: {Math.round((formation.bonuses.attack - 1) * 100)}%</span>
                    <span>🛡️ 防御: {Math.round((formation.bonuses.defense - 1) * 100)}%</span>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* 可选成员列表 */}
          <div style={{ marginBottom: '20px' }}>
            <div style={{ 
              color: '#BA55D3', 
              fontSize: '14px', 
              fontWeight: 'bold', 
              marginBottom: '10px' 
            }}>
              可选成员
            </div>
            <div style={{
              display: 'grid',
              gridTemplateColumns: '1fr',
              gap: '12px'
            }}>
              {availableMembers.map(renderMemberCard)}
            </div>
          </div>
        </div>

        {/* 底部按钮 */}
        <div style={{
          background: 'rgba(45, 27, 74, 0.8)',
          padding: '15px 20px',
          borderTop: '1px solid rgba(186, 85, 211, 0.3)',
          display: 'flex',
          justifyContent: 'space-between',
          gap: '10px'
        }}>
          <button
            onClick={onClose}
            style={{
              flex: 1,
              padding: '12px',
              border: '1px solid #666',
              borderRadius: '8px',
              background: 'linear-gradient(135deg, #666, #555)',
              color: '#fff',
              fontSize: '12px',
              fontWeight: 'bold',
              cursor: 'pointer'
            }}
          >
            取消
          </button>
          
          <button
            onClick={handleConfirm}
            disabled={selectedTeam.length === 0}
            style={{
              flex: 2,
              padding: '12px',
              border: selectedTeam.length > 0 ? '1px solid #FFD700' : '1px solid #666',
              borderRadius: '8px',
              background: selectedTeam.length > 0
                ? 'linear-gradient(135deg, #FFD700, #FFA500)'
                : 'linear-gradient(135deg, #666, #555)',
              color: selectedTeam.length > 0 ? '#000' : '#999',
              fontSize: '12px',
              fontWeight: 'bold',
              cursor: selectedTeam.length > 0 ? 'pointer' : 'not-allowed'
            }}
          >
            开始战斗 ({selectedTeam.length}人)
          </button>
        </div>
      </div>
    </div>
  );
};

export default TeamFormationModal;