import React from 'react';
import { useLongPress } from '../../hooks/useMobile';
import JewelryIcon from './JewelryIcon';

function JewelryItem({ jewelry, index, onClick, onLongPress, showCount = false }) {
  const longPressEvents = useLongPress(() => {
    onLongPress && onLongPress(jewelry, index);
  });

  const handleClick = (e) => {
    e.preventDefault();
    onClick && onClick(jewelry, index);
  };

  // 使用SVG图标组件替换emoji
  const borderColor = getBorderColor(jewelry.level);

  return (
    <div
      className="jewelry-item"
      onClick={handleClick}
      {...longPressEvents}
      style={{
        background: `linear-gradient(135deg, ${getBackgroundColor(jewelry.level)})`,
        border: `2px solid ${borderColor}`,
        borderRadius: '6px',
        padding: '6px',
        textAlign: 'center',
        cursor: 'pointer',
        fontSize: '9px',
        color: '#fff',
        transition: 'all 0.3s ease',
        aspectRatio: '1 / 1',
        width: '100%',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        position: 'relative'
      }}
      onMouseEnter={(e) => {
        e.target.style.transform = 'translateY(-2px)';
        e.target.style.boxShadow = '0 4px 12px rgba(107, 91, 71, 0.4)';
      }}
      onMouseLeave={(e) => {
        e.target.style.transform = 'translateY(0)';
        e.target.style.boxShadow = 'none';
      }}
    >
      <div style={{ marginBottom: '2px' }}>
        <JewelryIcon type={jewelry.type} level={jewelry.level} />
      </div>
      <div style={{ fontSize: '8px', lineHeight: '1.2' }}>
        Lv.{jewelry.level}
      </div>
      
      {/* 显示数量（70级首饰） */}
      {showCount && jewelry.count > 1 && (
        <div style={{
          position: 'absolute',
          top: '2px',
          right: '2px',
          background: '#FF6B6B',
          color: '#fff',
          borderRadius: '50%',
          width: '16px',
          height: '16px',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          fontSize: '8px',
          fontWeight: 'bold'
        }}>
          {jewelry.count}
        </div>
      )}

      {/* 特殊属性标识 */}
      {jewelry.additionalStats && jewelry.additionalStats.some(stat => stat.quality === 'special') && (
        <div style={{
          position: 'absolute',
          top: '2px',
          left: '2px',
          color: '#FFD700',
          fontSize: '8px'
        }}>
          ✨
        </div>
      )}
    </div>
  );
}

function getBorderColor(level) {
  // 使用柔和的灰褐色边框，减少视觉刺激
  return '#6B5B47';  // 柔和的灰褐色边框
}

function getBackgroundColor(level) {
  if (level >= 150) return 'rgba(30, 30, 30, 0.95), rgba(60, 20, 20, 0.9)';    // 鸿蒙 - 深黑红渐变
  if (level >= 140) return 'rgba(35, 25, 35, 0.95), rgba(50, 25, 30, 0.9)';    // 万法 - 深紫黑渐变  
  if (level >= 130) return 'rgba(40, 25, 40, 0.9), rgba(60, 30, 45, 0.85)';    // 轮回 - 紫黑渐变
  if (level >= 120) return 'rgba(30, 30, 45, 0.9), rgba(45, 35, 60, 0.85)';    // 九天 - 深蓝紫渐变
  if (level >= 110) return 'rgba(45, 35, 25, 0.9), rgba(65, 45, 25, 0.85)';    // 碎梦 - 深褐金渐变
  if (level >= 100) return 'rgba(40, 35, 15, 0.85), rgba(60, 50, 20, 0.8)';    // 天星 - 深金渐变
  if (level >= 90) return 'rgba(35, 25, 45, 0.8), rgba(50, 35, 60, 0.75)';     // 三清 - 深紫渐变
  if (level >= 80) return 'rgba(25, 35, 50, 0.8), rgba(35, 45, 65, 0.75)';     // 闭月 - 深蓝渐变
  if (level >= 70) return 'rgba(45, 30, 25, 0.75), rgba(60, 40, 30, 0.7)';     // 法文 - 深棕渐变
  if (level >= 60) return 'rgba(25, 40, 25, 0.75), rgba(35, 55, 35, 0.7)';     // 龙鳞 - 深绿渐变
  if (level >= 50) return 'rgba(20, 45, 40, 0.7), rgba(30, 60, 50, 0.65)';     // 凤舞 - 深青渐变
  if (level >= 35) return 'rgba(20, 35, 50, 0.7), rgba(30, 45, 65, 0.65)';     // 七星 - 深蓝渐变
  return 'rgba(30, 40, 50, 0.65), rgba(40, 50, 60, 0.6)';                      // 金刚 - 深灰蓝渐变
}

export default JewelryItem;