import React, { useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { startBattle as startWendaoBattle } from '../../store/wendaoBattleSlice';
import { addSystemLog } from '../../store/uiSlice';
import { BOSS_CONFIG } from '../../utils/constants';
import { soundEffects } from '../../utils/soundEffects';
import Modal from '../UI/Modal';
import TeamFormationModal from '../Battle/TeamFormationModal';
// import BossChallengePreview from './BossChallengePreview'; // 已简化，直接开始挑战

function BossModal({ isOpen, onClose }) {
  const dispatch = useDispatch();
  const character = useSelector(state => state.character);
  const wendaoBattle = useSelector(state => state.wendaoBattle);
  const [selectedBoss, setSelectedBoss] = useState(null);
  const [showTeamFormation, setShowTeamFormation] = useState(false);
  const [battleMode, setBattleMode] = useState('1v1'); // '1v1' | '3v3'
  // const [showPreview, setShowPreview] = useState(false); // 已移除预览界面
  
  console.log('[妖王模态框] 渲染，当前战斗状态', {
    showBattleUI: wendaoBattle.showBattleUI,
    phase: wendaoBattle.phase,
    isActive: wendaoBattle.isActive
  });

  const handleBossSelect = (boss) => {
    soundEffects.playBossSelect();
    setSelectedBoss(boss);
  };

  // 开始1v1战斗
  const handleStart1v1Battle = (boss) => {
    setBattleMode('1v1');
    handleConfirmChallenge(boss);
  };

  // 开始3v3战斗
  const handleStart3v3Battle = (boss) => {
    setBattleMode('3v3');
    setShowTeamFormation(true);
  };

  // 队伍组建完成
  const handleTeamFormationConfirm = (team, formation) => {
    setShowTeamFormation(false);
    // 启动3v3战斗
    start3v3Battle(selectedBoss, team, formation);
  };

  // 将中文数字格式转换为实际数字
  const parseChineseNumber = (str) => {
    if (!str) return 1000;
    const num = parseFloat(str);
    if (str.includes('万')) {
      return Math.floor(num * 10000);
    }
    return Math.floor(num);
  };

  const handleConfirmChallenge = (boss = selectedBoss) => {
    if (!boss) return;
    
    // 播放战斗准备音效
    soundEffects.playBattleReady();
    
    console.log(`[妖王挑战] 开始挑战：${boss.name} (${boss.level}级)`);
    
    // 准备玩家数据 - 修复数据格式
    const playerData = {
      name: character.name || '玩家',
      level: character.level || 1,
      element: character.element || '金',
      hp: character.maxHp || 1000,
      maxHp: character.maxHp || 1000,
      mp: character.maxMana || 500,
      maxMp: character.maxMana || 500,
      attack: character.baseAttack || 100,
      defense: character.baseDefense || 50,
      speed: character.baseSpeed || 100,
      daoXing: character.level * 2
    };
    
    // 转换Boss的HP为实际数字
    const bossHp = parseChineseNumber(boss.hp);
    console.log(`[妖王挑战] Boss HP转换: ${boss.hp} -> ${bossHp}`);
    
    // 启动问道战斗系统 - 修复数据格式
    const enemyData = {
      name: boss.name,
      level: boss.level,
      element: ['金', '木', '水', '火', '土'][Math.floor(Math.random() * 5)],
      hp: bossHp,
      maxHp: bossHp,
      mp: Math.floor(boss.level * 10),
      maxMp: Math.floor(boss.level * 10),
      attack: parseChineseNumber(boss.power),
      defense: Math.floor(parseChineseNumber(boss.power) * 0.3),
      speed: Math.floor(boss.level * 2),
      daoXing: boss.level * 1.5
    };

    console.log('[妖王挑战] 准备启动战斗系统', {
      playerData,
      enemyData,
      petData: null
    });

    // 启动问道战斗系统
    dispatch(startWendaoBattle({
      playerData: playerData,
      enemyData: enemyData,
      petData: null // 暂时不使用宠物
    }));
    
    // 记录挑战日志
    dispatch(addSystemLog({ 
      message: `⚔️ 向 ${boss.name} 发起挑战！` 
    }));
    
    console.log(`[妖王挑战] startBattle action 已调用`);
    
    // 延迟关闭，给Redux时间更新状态
    setTimeout(() => {
      console.log(`[妖王挑战] 延迟关闭妖王选择界面`);
      // setShowPreview(false); // 已移除预览界面
      setSelectedBoss(null);
      onClose();
    }, 200);
  };

  // 启动3v3战斗
  const start3v3Battle = (boss, team, formation) => {
    if (!boss || !team) return;

    soundEffects.playBattleReady();
    console.log(`[3v3战斗] 开始团战：${boss.name} vs ${team.length}人队伍`, team);

    // 准备队伍数据
    const playerTeamData = team.map((member, index) => ({
      ...member,
      position: index,
      formation: formation.name,
      isLeader: member.type === 'main'
    }));
    
    console.log('[3v3战斗] 玩家队伍数据:', playerTeamData);

    // 生成敌方团队（Boss + 小弟们）
    const enemyTeamData = [
      {
        id: 'boss-1',
        name: boss.name,
        level: boss.level,
        element: boss.element || '雷',
        position: 0,
        role: 'boss',
        hp: parseChineseNumber(boss.hp),
        maxHp: parseChineseNumber(boss.hp),
        attack: boss.level * 15 + 200,
        defense: boss.level * 8 + 100,
        isLeader: true
      },
      // 根据boss等级生成小弟
      ...generateBossMinions(boss)
    ];

    console.log('[3v3战斗] 派发Redux action前的数据:', {
      playerTeamData,
      enemyTeamData,
      playerCount: playerTeamData.length,
      enemyCount: enemyTeamData.length
    });
    
    // 启动3v3战斗系统
    dispatch(startWendaoBattle({
      battleType: '3v3',
      playerData: playerTeamData,
      enemyData: enemyTeamData,
      battleMode: 'team',
      formation: formation
    }));

    // 关闭界面
    setTimeout(() => {
      setSelectedBoss(null);
      onClose();
    }, 200);
  };

  // 生成Boss小弟
  const generateBossMinions = (boss) => {
    const minions = [];
    const bossLevel = boss.level;
    
    // 根据Boss等级决定小弟数量和类型
    if (bossLevel >= 80) {
      // 高级Boss有2个小弟
      minions.push({
        id: 'minion-1',
        name: '左护法',
        level: Math.max(1, bossLevel - 5),
        element: boss.element || '雷',
        position: 1,
        role: 'elite',
        hp: (bossLevel - 5) * 40 + 600,
        maxHp: (bossLevel - 5) * 40 + 600,
        attack: (bossLevel - 5) * 8 + 120,
        defense: (bossLevel - 5) * 5 + 80
      });
      
      minions.push({
        id: 'minion-2', 
        name: '天雷战将',
        level: Math.max(1, bossLevel - 8),
        element: getRandomElement(),
        position: 2,
        role: 'minion',
        hp: (bossLevel - 8) * 30 + 400,
        maxHp: (bossLevel - 8) * 30 + 400,
        attack: (bossLevel - 8) * 6 + 100,
        defense: (bossLevel - 8) * 4 + 60
      });
    } else {
      // 中低级Boss有1个小弟
      minions.push({
        id: 'minion-1',
        name: '护法金刚',
        level: Math.max(1, bossLevel - 3),
        element: boss.element || '雷',
        position: 1,
        role: 'minion',
        hp: (bossLevel - 3) * 35 + 500,
        maxHp: (bossLevel - 3) * 35 + 500,
        attack: (bossLevel - 3) * 7 + 100,
        defense: (bossLevel - 3) * 4 + 70
      });
    }

    return minions;
  };

  // 获取随机元素
  const getRandomElement = () => {
    const elements = ['金', '木', '水', '火', '土'];
    return elements[Math.floor(Math.random() * elements.length)];
  };

  // const handleCancelChallenge = () => { // 已移除预览界面
  //   setShowPreview(false);
  //   setSelectedBoss(null);
  // };

  const getBossIcon = (level) => {
    if (level >= 110) return '🐲'; // 混沌妖尊 - 龙族
    if (level >= 100) return '👹'; // 上古妖王 - 妖王
    if (level >= 90) return '🌳'; // 千年树妖 - 植物系
    if (level >= 80) return '🦊'; // 九尾妖狐 - 狐族
    if (level >= 70) return '🔥'; // 赤炎魔君 - 火属性
    if (level >= 60) return '🐂'; // 牛魔王 - 牛族
    if (level >= 50) return '💀'; // 白骨精 - 鬼族
    if (level >= 35) return '⛰️'; // 黑山老妖 - 山魈
    return '⚡'; // 雷震子 - 雷属性
  };

  const getBossGradient = (level) => {
    if (level >= 110) return 'linear-gradient(135deg, #4B0082 0%, #8B00FF 50%, #FF00FF 100%)'; // 紫金色 - 传说
    if (level >= 100) return 'linear-gradient(135deg, #B8860B 0%, #FFD700 50%, #FFA500 100%)'; // 金色 - 史诗
    if (level >= 90) return 'linear-gradient(135deg, #228B22 0%, #32CD32 50%, #90EE90 100%)'; // 绿色 - 精良
    if (level >= 80) return 'linear-gradient(135deg, #FF4500 0%, #FF6347 50%, #FF7F50 100%)'; // 橙色 - 稀有
    if (level >= 70) return 'linear-gradient(135deg, #DC143C 0%, #B22222 50%, #8B0000 100%)'; // 红色 - 优秀
    if (level >= 60) return 'linear-gradient(135deg, #4169E1 0%, #6495ED 50%, #87CEEB 100%)'; // 蓝色 - 精良
    if (level >= 50) return 'linear-gradient(135deg, #9370DB 0%, #8A2BE2 50%, #9932CC 100%)'; // 紫色 - 稀有
    if (level >= 35) return 'linear-gradient(135deg, #2F4F4F 0%, #708090 50%, #A9A9A9 100%)'; // 灰色 - 普通
    return 'linear-gradient(135deg, #556B2F 0%, #6B8E23 50%, #9ACD32 100%)'; // 绿褐色 - 基础
  };

  const getBossTitle = (boss) => {
    const titles = {
      '雷震子': '天庭战神',
      '黑山老妖': '幽冥鬼王',
      '白骨精': '白骨夫人',
      '牛魔王': '平天大圣',
      '赤炎魔君': '火焰魔神',
      '九尾妖狐': '妖狐圣君',
      '千年树妖': '姥姥仙人',
      '上古妖王': '远古霸主',
      '混沌妖尊': '洪荒至尊'
    };
    return titles[boss.name] || '神秘妖王';
  };

  const getBossElement = (boss) => {
    const elements = {
      '雷震子': '金',
      '黑山老妖': '土',
      '白骨精': '水',
      '牛魔王': '土',
      '赤炎魔君': '火',
      '九尾妖狐': '火',
      '千年树妖': '木',
      '上古妖王': '金',
      '混沌妖尊': '土'
    };
    return elements[boss.name] || '金';
  };

  const getElementColor = (element) => {
    const colors = {
      金: '#FFD700',
      木: '#90EE90',
      水: '#87CEEB',
      火: '#FF6347',
      土: '#DEB887'
    };
    return colors[element] || '#FFD700';
  };

  // 重置状态当模态框关闭时
  React.useEffect(() => {
    if (!isOpen) {
      // setShowPreview(false); // 已移除预览界面
      setSelectedBoss(null);
    }
  }, [isOpen]);

  // 获取难度颜色和文本
  const getDifficultyInfo = (level) => {
    if (level >= 110) return { text: '终极', color: '#8B00FF', glow: '#8B00FF' };
    if (level >= 100) return { text: '噩梦', color: '#FF0000', glow: '#FF4500' };
    if (level >= 90) return { text: '地狱', color: '#DC143C', glow: '#FF6347' };
    if (level >= 80) return { text: '极难', color: '#FF4500', glow: '#FFA500' };
    if (level >= 70) return { text: '很难', color: '#FF6B6B', glow: '#FF8C00' };
    if (level >= 60) return { text: '困难', color: '#FFD700', glow: '#FFF700' };
    if (level >= 50) return { text: '一般', color: '#90EE90', glow: '#98FB98' };
    if (level >= 35) return { text: '容易', color: '#87CEEB', glow: '#B0E0E6' };
    return { text: '简单', color: '#98FB98', glow: '#90EE90' };
  };

  // 获取推荐等级
  const getRecommendedLevel = (bossLevel) => {
    return Math.floor(bossLevel * 0.8);
  };

  if (!isOpen) return null;

  return (
    <Modal
      isOpen={isOpen}
      onClose={onClose}
      title="妖王挑战"
      size="default"
    >
      <div style={{
        display: 'grid',
        gap: '10px',
        maxHeight: '500px',
        overflowY: 'auto',
        '@media (max-width: 768px)': {
          gap: '8px',
          maxHeight: '400px'
        }
      }}>
        {BOSS_CONFIG.map((boss, index) => {
          const element = getBossElement(boss);
          const elementColor = getElementColor(element);
          const difficulty = getDifficultyInfo(boss.level);
          const recommendedLevel = getRecommendedLevel(boss.level);
          const playerLevel = character.level || 1;
          const canChallenge = playerLevel >= Math.max(1, boss.level - 30);
          
          return (
            <div
              key={index}
              onClick={() => {
                if (canChallenge) {
                  soundEffects.playButtonClick();
                  handleBossSelect(boss);
                }
              }}
              onTouchStart={(e) => {
                if (canChallenge) {
                  e.currentTarget.style.transform = 'scale(0.98)';
                }
              }}
              onTouchEnd={(e) => {
                if (canChallenge) {
                  e.currentTarget.style.transform = 'scale(1)';
                }
              }}
              style={{
                background: canChallenge ? getBossGradient(boss.level) : 'linear-gradient(135deg, #2F2F2F, #1C1C1C)',
                border: `2px solid ${canChallenge ? elementColor : '#666'}`,
                borderRadius: '12px',
                padding: window.innerWidth <= 768 ? '12px' : '15px',
                cursor: canChallenge ? 'pointer' : 'not-allowed',
                transition: 'all 0.3s ease',
                position: 'relative',
                overflow: 'hidden',
                boxShadow: canChallenge 
                  ? `0 4px 15px rgba(0,0,0,0.3), 0 0 20px ${elementColor}30`
                  : '0 2px 8px rgba(0,0,0,0.5)',
                filter: canChallenge ? 'none' : 'grayscale(0.7) brightness(0.6)',
                opacity: canChallenge ? 1 : 0.7
              }}
              onMouseEnter={e => {
                if (canChallenge) {
                  soundEffects.playButtonHover();
                  soundEffects.playElementSound(element);
                  e.currentTarget.style.transform = 'translateY(-3px) scale(1.02)';
                  e.currentTarget.style.boxShadow = `0 8px 25px rgba(0,0,0,0.4), 0 0 30px ${elementColor}50`;
                }
              }}
              onMouseLeave={e => {
                if (canChallenge) {
                  e.currentTarget.style.transform = 'translateY(0) scale(1)';
                  e.currentTarget.style.boxShadow = `0 4px 15px rgba(0,0,0,0.3), 0 0 20px ${elementColor}30`;
                }
              }}
            >
              {/* 背景装饰 */}
              <div style={{
                position: 'absolute',
                top: '-10px',
                right: '-10px',
                fontSize: '40px',
                opacity: 0.2,
                transform: 'rotate(15deg)',
                color: 'white'
              }}>
                {getBossIcon(boss.level)}
              </div>

              {/* 妖王信息 */}
              <div style={{
                display: 'flex',
                alignItems: 'flex-start',
                gap: '12px',
                position: 'relative',
                zIndex: 1
              }}>
                {/* 妖王图标和等级 */}
                <div style={{
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  minWidth: '60px'
                }}>
                  <div style={{
                    fontSize: '28px',
                    marginBottom: '5px',
                    filter: 'drop-shadow(2px 2px 4px rgba(0,0,0,0.5))'
                  }}>
                    {getBossIcon(boss.level)}
                  </div>
                  <div style={{
                    background: 'rgba(0,0,0,0.7)',
                    borderRadius: '12px',
                    padding: '3px 8px',
                    fontSize: '10px',
                    color: '#FFD700',
                    fontWeight: 'bold',
                    textAlign: 'center'
                  }}>
                    {boss.level}级
                  </div>
                </div>

                {/* 妖王详细信息 */}
                <div style={{ flex: 1 }}>
                  {/* 名称和称号 */}
                  <div style={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    marginBottom: '8px'
                  }}>
                    <div>
                      <div style={{
                        color: canChallenge ? 'white' : '#888',
                        fontSize: '16px',
                        fontWeight: 'bold',
                        textShadow: '2px 2px 4px rgba(0,0,0,0.8)',
                        marginBottom: '2px'
                      }}>
                        {boss.name}
                      </div>
                      <div style={{
                        color: canChallenge ? elementColor : '#666',
                        fontSize: '11px',
                        fontWeight: 'bold',
                        opacity: 0.9
                      }}>
                        {getBossTitle(boss)} · {element}系
                      </div>
                    </div>
                    
                    {/* 难度标签 */}
                    <div style={{
                      background: `linear-gradient(135deg, ${difficulty.color}, ${difficulty.glow})`,
                      borderRadius: '15px',
                      padding: '3px 8px',
                      fontSize: '10px',
                      fontWeight: 'bold',
                      color: 'white',
                      textShadow: '1px 1px 2px rgba(0,0,0,0.8)',
                      boxShadow: `0 2px 8px ${difficulty.color}40`
                    }}>
                      {difficulty.text}
                    </div>
                  </div>

                  {/* 推荐等级提示 */}
                  {!canChallenge && (
                    <div 
                      style={{
                        background: 'rgba(220, 20, 60, 0.2)',
                        border: '1px solid #DC143C',
                        borderRadius: '6px',
                        padding: '6px 8px',
                        marginBottom: '8px',
                        fontSize: '10px',
                        color: '#FFB6C1',
                        textAlign: 'center',
                        cursor: 'pointer'
                      }}
                      onClick={(e) => {
                        e.stopPropagation();
                        soundEffects.playWarning();
                      }}
                    >
                      🚫 等级不足 - 推荐{recommendedLevel}级以上挑战
                    </div>
                  )}

                  {playerLevel >= recommendedLevel && playerLevel < boss.level && canChallenge && (
                    <div style={{
                      background: 'rgba(255, 165, 0, 0.2)',
                      border: '1px solid #FFA500',
                      borderRadius: '6px',
                      padding: '6px 8px',
                      marginBottom: '8px',
                      fontSize: '10px',
                      color: '#FFD700',
                      textAlign: 'center'
                    }}>
                      ⚠️ 挑战有风险 - 推荐{boss.level}级以上
                    </div>
                  )}

                  {/* 属性信息 */}
                  <div style={{
                    display: 'grid',
                    gridTemplateColumns: '1fr 1fr',
                    gap: '8px',
                    marginBottom: '8px'
                  }}>
                    <div style={{
                      background: 'rgba(0,0,0,0.4)',
                      borderRadius: '8px',
                      padding: '6px 8px',
                      textAlign: 'center'
                    }}>
                      <div style={{ color: '#FF6B6B', fontSize: '10px', opacity: 0.8 }}>气血</div>
                      <div style={{ color: 'white', fontSize: '12px', fontWeight: 'bold' }}>{boss.hp}</div>
                    </div>
                    <div style={{
                      background: 'rgba(0,0,0,0.4)',
                      borderRadius: '8px',
                      padding: '6px 8px',
                      textAlign: 'center'
                    }}>
                      <div style={{ color: '#FFA500', fontSize: '10px', opacity: 0.8 }}>攻击</div>
                      <div style={{ color: 'white', fontSize: '12px', fontWeight: 'bold' }}>{boss.power}</div>
                    </div>
                  </div>

                  {/* 掉落信息 */}
                  <div style={{
                    background: 'rgba(0,0,0,0.4)',
                    borderRadius: '8px',
                    padding: '6px 8px'
                  }}>
                    <div style={{
                      color: '#90EE90',
                      fontSize: '10px',
                      opacity: 0.9,
                      marginBottom: '3px'
                    }}>
                      掉落奖励：
                    </div>
                    <div style={{
                      display: 'flex',
                      gap: '8px',
                      fontSize: '9px'
                    }}>
                      {boss.drops.normalStone && (
                        <span style={{ color: '#87CEEB' }}>💎女娲石 {Math.round(boss.drops.normalStone * 100)}%</span>
                      )}
                      {boss.drops.superStone && (
                        <span style={{ color: '#DA70D6' }}>💠超级女娲石 {Math.round(boss.drops.superStone * 100)}%</span>
                      )}
                      <span style={{ color: '#FFD700' }}>⚜️首饰 {Math.round(boss.drops.jewelry * 100)}%</span>
                    </div>
                  </div>
                </div>
              </div>

              {/* 战斗模式选择按钮 */}
              {canChallenge && selectedBoss?.name === boss.name && (
                <div style={{
                  position: 'absolute',
                  bottom: '8px',
                  left: '8px',
                  right: '8px',
                  display: 'flex',
                  gap: '4px',
                  zIndex: 10
                }}>
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      handleStart1v1Battle(boss);
                    }}
                    style={{
                      flex: 1,
                      background: 'linear-gradient(135deg, #4169E1, #32CD32)',
                      border: '1px solid rgba(255,255,255,0.3)',
                      borderRadius: '8px',
                      padding: '6px 4px',
                      fontSize: '9px',
                      color: 'white',
                      fontWeight: 'bold',
                      cursor: 'pointer'
                    }}
                  >
                    ⚔️ 单挑
                  </button>
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      handleStart3v3Battle(boss);
                    }}
                    style={{
                      flex: 1,
                      background: 'linear-gradient(135deg, #8B0000, #DC143C)',
                      border: '1px solid rgba(255,255,255,0.3)',
                      borderRadius: '8px',
                      padding: '6px 4px',
                      fontSize: '9px',
                      color: 'white',
                      fontWeight: 'bold',
                      cursor: 'pointer'
                    }}
                  >
                    👥 团战
                  </button>
                </div>
              )}

              {/* 默认提示 */}
              {(!selectedBoss || selectedBoss?.name !== boss.name) && (
                <div style={{
                  position: 'absolute',
                  bottom: '8px',
                  right: '8px',
                  background: canChallenge ? 'rgba(255,255,255,0.2)' : 'rgba(128,128,128,0.3)',
                  borderRadius: '15px',
                  padding: '4px 10px',
                  fontSize: '10px',
                  color: canChallenge ? 'white' : '#888',
                  fontWeight: 'bold',
                  opacity: 0.8,
                  border: canChallenge ? '1px solid rgba(255,255,255,0.3)' : '1px solid rgba(128,128,128,0.5)'
                }}>
                  {canChallenge ? '点击选择' : '等级不足'}
                </div>
              )}
              
              {/* 等级不足遮罩 */}
              {!canChallenge && (
                <div style={{
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  right: 0,
                  bottom: 0,
                  background: 'rgba(0,0,0,0.4)',
                  borderRadius: '12px',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  zIndex: 10
                }}>
                  <div style={{
                    background: 'rgba(0,0,0,0.8)',
                    borderRadius: '8px',
                    padding: '8px 12px',
                    color: '#FF6B6B',
                    fontSize: '12px',
                    fontWeight: 'bold',
                    textAlign: 'center'
                  }}>
                    🔒<br/>需要{Math.max(1, boss.level - 30)}级
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>
      
      {/* 队伍组建弹窗 */}
      <TeamFormationModal
        isOpen={showTeamFormation}
        onClose={() => setShowTeamFormation(false)}
        onConfirm={handleTeamFormationConfirm}
      />
    </Modal>
  );
}

export default BossModal;