import React, { useState } from 'react';
import { useSelector } from 'react-redux';
import { soundEffects } from '../../utils/soundEffects';
import BossModal from './BossModal';

function BossList() {
  const normalStone = useSelector(state => state.jewelry.normalStone);
  const superStone = useSelector(state => state.jewelry.superStone);
  const totalBossKills = useSelector(state => state.jewelry.totalBossKills);
  const [showBossModal, setShowBossModal] = useState(false);

  const handleBossChallenge = () => {
    soundEffects.playButtonClick();
    setShowBossModal(true);
  };

  const handleCloseBossModal = () => {
    setShowBossModal(false);
  };


  return (
    <>
      <div className="boss-section" style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
        <div style={{ display: 'flex', gap: '8px', fontSize: '9px', color: '#87CEEB' }}>
          <span>击杀: <span style={{ color: '#FFD700' }}>{totalBossKills}</span></span>
          <span>💎 {normalStone}</span>
          <span>💠 {superStone}</span>
        </div>
        <button
          className="boss-challenge-btn"
          onClick={handleBossChallenge}
          style={{
            background: 'linear-gradient(135deg, #8B0000 0%, #DC143C 50%, #FF6B6B 100%)',
            color: 'white',
            border: '2px solid #FFD700',
            padding: '6px 12px',
            borderRadius: '15px',
            cursor: 'pointer',
            fontSize: '10px',
            fontWeight: 'bold',
            transition: 'all 0.3s ease',
            boxShadow: '0 4px 8px rgba(139, 0, 0, 0.4), 0 0 12px rgba(220, 20, 60, 0.3)',
            whiteSpace: 'nowrap',
            textShadow: '1px 1px 2px rgba(0,0,0,0.8)',
            position: 'relative',
            overflow: 'hidden'
          }}
          onMouseEnter={e => {
            soundEffects.playButtonHover();
            e.target.style.transform = 'translateY(-2px) scale(1.05)';
            e.target.style.boxShadow = '0 6px 15px rgba(139, 0, 0, 0.6), 0 0 20px rgba(220, 20, 60, 0.5)';
            e.target.style.background = 'linear-gradient(135deg, #B22222 0%, #FF4500 50%, #FF8C00 100%)';
          }}
          onMouseLeave={e => {
            e.target.style.transform = 'translateY(0) scale(1)';
            e.target.style.boxShadow = '0 4px 8px rgba(139, 0, 0, 0.4), 0 0 12px rgba(220, 20, 60, 0.3)';
            e.target.style.background = 'linear-gradient(135deg, #8B0000 0%, #DC143C 50%, #FF6B6B 100%)';
          }}
        >
          ⚔️ 妖王挑战
        </button>
      </div>
      
      {/* 妖王选择模态框 */}
      <BossModal 
        isOpen={showBossModal} 
        onClose={handleCloseBossModal} 
      />
    </>
  );
}

export default BossList;