/**
 * 问道手游回合制战斗系统
 * 基于现有妖王配置的战斗逻辑
 */

import { BOSS_CONFIG } from './constants';

// 战斗状态枚举
export const BATTLE_STATES = {
  IDLE: 'idle',
  PLAYER_TURN: 'player_turn',
  ENEMY_TURN: 'enemy_turn',
  VICTORY: 'victory',
  DEFEAT: 'defeat',
  FLED: 'fled'
};

// 战斗动作类型
export const BATTLE_ACTIONS = {
  ATTACK: 'attack',
  MAGIC: 'magic',
  DEFEND: 'defend',
  ITEM: 'item',
  FLEE: 'flee'
};

// 技能效果类型
export const SKILL_EFFECTS = {
  DAMAGE: 'damage',
  HEAL: 'heal',
  BUFF: 'buff',
  DEBUFF: 'debuff',
  STUN: 'stun',
  BURN: 'burn',
  FREEZE: 'freeze',
  POISON: 'poison'
};

// 解析HP字符串为数值
function parseHPString(hpString) {
  const str = hpString.toString();
  if (str.includes('万')) {
    return parseFloat(str.replace('万', '')) * 10000;
  }
  return parseInt(str);
}

// 根据现有BOSS配置创建完整的妖王数据
export function createBossFromConfig(bossConfig) {
  const maxHp = parseHPString(bossConfig.hp);
  const attack = parseInt(bossConfig.power);
  
  return {
    id: `boss_${bossConfig.level}`,
    name: bossConfig.name,
    level: bossConfig.level,
    stats: {
      hp: maxHp,
      maxHp: maxHp,
      attack: attack,
      defense: Math.floor(attack * 0.3), // 防御 = 攻击力的30%
      speed: Math.floor(bossConfig.level * 2 + 10), // 速度基于等级
      magic: Math.floor(attack * 0.8) // 法力 = 攻击力的80%
    },
    element: getBossElement(bossConfig.name),
    type: getBossType(bossConfig.name),
    skills: getBossSkills(bossConfig.name, bossConfig.level),
    drops: bossConfig.drops,
    statusEffects: [], // 当前状态效果
    colors: getBossColors(bossConfig.name)
  };
}

// 根据妖王名称获取元素属性
function getBossElement(name) {
  const elementMap = {
    '雷震子': 'metal',
    '黑山老妖': 'earth', 
    '白骨精': 'water',
    '牛魔王': 'fire',
    '赤炎魔君': 'fire',
    '九尾妖狐': 'wood',
    '千年树妖': 'wood',
    '上古妖王': 'chaos',
    '混沌妖尊': 'chaos'
  };
  return elementMap[name] || 'neutral';
}

// 根据妖王名称获取类型
function getBossType(name) {
  const typeMap = {
    '雷震子': 'immortal',
    '黑山老妖': 'demon',
    '白骨精': 'undead',
    '牛魔王': 'demon',
    '赤炎魔君': 'demon',
    '九尾妖狐': 'beast',
    '千年树妖': 'plant',
    '上古妖王': 'ancient',
    '混沌妖尊': 'chaos'
  };
  return typeMap[name] || 'monster';
}

