// 获取妖王配色
function getBossColors(name) {
  const colorMap = {
    '雷震子': ['#FFD700', '#4169E1', '#FFFFFF'],
    '黑山老妖': ['#2F4F4F', '#000000', '#8B0000'],
    '白骨精': ['#F5F5F5', '#C0C0C0', '#4682B4'],
    '牛魔王': ['#8B4513', '#A0522D', '#FF4500'],
    '赤炎魔君': ['#DC143C', '#FF4500', '#FFD700'],
    '九尾妖狐': ['#FF69B4', '#FF1493', '#FFD700'],
    '千年树妖': ['#228B22', '#006400', '#8B4513'],
    '上古妖王': ['#4B0082', '#8B008B', '#FFD700'],
    '混沌妖尊': ['#000000', '#4B0082', '#8B0000']
  };
  return colorMap[name] || ['#696969', '#2F4F4F', '#708090'];
}

// 战斗状态管理类
export class BattleManager {
  constructor() {
    this.state = BATTLE_STATES.IDLE;
    this.player = null;
    this.enemy = null;
    this.turnCount = 0;
    this.battleLog = [];
    this.playerActions = [];
    this.enemyActions = [];
  }

  // 初始化战斗
  initializeBattle(playerData, enemyBossName) {
    const bossConfig = BOSS_CONFIG.find(boss => boss.name === enemyBossName);
    if (!bossConfig) {
      throw new Error(`未找到妖王: ${enemyBossName}`);
    }

    this.player = {
      ...playerData,
      statusEffects: [],
      currentHp: playerData.stats?.hp || 1000
    };
    
    this.enemy = createBossFromConfig(bossConfig);
    this.state = BATTLE_STATES.PLAYER_TURN;
    this.turnCount = 1;
    this.battleLog = [];
    
    this.addToLog(`战斗开始！挑战 ${this.enemy.name} (${this.enemy.level}级)`);
    
    return {
      player: this.player,
      enemy: this.enemy,
      state: this.state,
      turnCount: this.turnCount
    };
  }

  // 玩家行动
  playerAction(action) {
    if (this.state !== BATTLE_STATES.PLAYER_TURN) {
      return { success: false, message: '不是玩家回合' };
    }

    let result;
    switch (action.type) {
      case BATTLE_ACTIONS.ATTACK:
        result = this.performAttack(this.player, this.enemy, action.skill);
        break;
      case BATTLE_ACTIONS.MAGIC:
        result = this.performMagic(this.player, this.enemy, action.skill);
        break;
      case BATTLE_ACTIONS.DEFEND:
        result = this.performDefend(this.player);
        break;
      case BATTLE_ACTIONS.ITEM:
        result = this.useItem(this.player, action.item);
        break;
      case BATTLE_ACTIONS.FLEE:
        result = this.attemptFlee();
        break;
      default:
        return { success: false, message: '未知行动' };
    }

    if (result.success) {
      this.addToLog(result.message);
      
      // 检查敌人是否死亡
      if (this.enemy.stats.hp <= 0) {
        this.state = BATTLE_STATES.VICTORY;
        this.addToLog(`${this.enemy.name} 被击败了！`);
        return { success: true, state: this.state, battleEnd: true };
      }
      
      // 转到敌人回合
      this.state = BATTLE_STATES.ENEMY_TURN;
      setTimeout(() => this.enemyTurn(), 1500); // 1.5秒延迟
    }

    return {
      success: result.success,
      message: result.message,
      player: this.player,
      enemy: this.enemy,
      state: this.state
    };
  }

  // 敌人回合
  enemyTurn() {
    if (this.state !== BATTLE_STATES.ENEMY_TURN) return;

    // 选择敌人技能（简单AI）
    const availableSkills = this.enemy.skills.filter(skill => 
      !skill.cooldown || !skill.currentCooldown
    );
    
    const selectedSkill = this.selectEnemySkill(availableSkills);
    const result = this.performEnemyAction(selectedSkill);
    
    this.addToLog(result.message);
    
    // 检查玩家是否死亡
    if (this.player.currentHp <= 0) {
      this.state = BATTLE_STATES.DEFEAT;
      this.addToLog('战斗失败...');
      return { battleEnd: true, state: this.state };
    }
    
    // 回合结束处理
    this.endTurn();
    
    return {
      player: this.player,
      enemy: this.enemy,
      state: this.state,
      turnCount: this.turnCount
    };
  }

  // 执行攻击
  performAttack(attacker, defender, skill = null) {
    const baseSkill = skill || { name: '普通攻击', power: 100, accuracy: 95 };
    
    // 命中检测
    const hitChance = Math.random() * 100;
    if (hitChance > baseSkill.accuracy) {
      return { success: true, message: `${attacker.name} 的${baseSkill.name}没有命中！` };
    }

    // 计算伤害
    const baseDamage = Math.floor(attacker.stats?.attack || attacker.attack || 100);
    const skillMultiplier = baseSkill.power / 100;
    const defense = defender.stats?.defense || defender.defense || 0;
    
    let damage = Math.floor((baseDamage * skillMultiplier - defense) * (0.8 + Math.random() * 0.4));
    damage = Math.max(1, damage); // 最小伤害1
    
    // 应用伤害
    if (defender === this.player) {
      this.player.currentHp = Math.max(0, this.player.currentHp - damage);
    } else {
      defender.stats.hp = Math.max(0, defender.stats.hp - damage);
    }
    
    // 应用技能效果
    if (baseSkill.effect) {
      this.applySkillEffect(defender, baseSkill.effect);
    }
    
    return {
      success: true,
      message: `${attacker.name} 对 ${defender.name} 造成了 ${damage} 点伤害！`,
      damage: damage
    };
  }

  // 执行魔法
  performMagic(attacker, defender, skill) {
    // 检查法力值
    const manaCost = skill.manaCost || Math.floor(skill.power / 5);
    const currentMana = attacker.currentMana || attacker.stats?.magic || 100;
    
    if (currentMana < manaCost) {
      return { success: false, message: '法力不足！' };
    }
    
    // 消耗法力
    if (attacker === this.player) {
      attacker.currentMana = Math.max(0, currentMana - manaCost);
    }
    
    return this.performAttack(attacker, defender, skill);
  }

  // 执行防御
  performDefend(defender) {
    // 提升防御，降低受到的伤害
    defender.defending = true;
    return {
      success: true,
      message: `${defender.name} 进入了防御状态！`
    };
  }

  // 使用道具
  useItem(user, item) {
    // 简单的道具系统
    switch (item.type) {
      case 'heal':
        const healAmount = item.power || 500;
        const oldHp = user.currentHp;
        user.currentHp = Math.min(user.stats?.hp || 1000, user.currentHp + healAmount);
        const actualHeal = user.currentHp - oldHp;
        return {
          success: true,
          message: `${user.name} 恢复了 ${actualHeal} 点生命值！`
        };
      default:
        return { success: false, message: '无法使用该道具' };
    }
  }

  // 逃跑
  attemptFlee() {
    const escapeChance = 30 + (this.player.stats?.speed || 50) - (this.enemy.stats.speed || 30);
    const roll = Math.random() * 100;
    
    if (roll < escapeChance) {
      this.state = BATTLE_STATES.FLED;
      return {
        success: true,
        message: '成功逃脱了战斗！',
        battleEnd: true,
        state: this.state
      };
    } else {
      return {
        success: true,
        message: '逃跑失败！'
      };
    }
  }

  // 敌人技能选择AI
  selectEnemySkill(availableSkills) {
    if (availableSkills.length === 0) {
      return { name: '普通攻击', power: 100, accuracy: 90 };
    }
    
    // 简单AI：随机选择技能，但倾向于选择高威力技能
    const weights = availableSkills.map(skill => skill.power || 100);
    const totalWeight = weights.reduce((sum, weight) => sum + weight, 0);
    
    let random = Math.random() * totalWeight;
    for (let i = 0; i < availableSkills.length; i++) {
      random -= weights[i];
      if (random <= 0) {
        return availableSkills[i];
      }
    }
    
    return availableSkills[0];
  }

  // 执行敌人动作
  performEnemyAction(skill) {
    return this.performAttack(this.enemy, this.player, skill);
  }

  // 应用技能效果
  applySkillEffect(target, effect) {
    if (!target.statusEffects) target.statusEffects = [];
    
    const effectData = {
      type: effect,
      duration: 3,
      power: 1
    };
    
    target.statusEffects.push(effectData);
  }

  // 回合结束
  endTurn() {
    this.turnCount++;
    
    // 处理状态效果
    this.processStatusEffects(this.player);
    this.processStatusEffects(this.enemy);
    
    // 技能冷却
    this.processCooldowns(this.enemy.skills);
    
    // 重置防御状态
    this.player.defending = false;
    this.enemy.defending = false;
    
    // 转到玩家回合
    this.state = BATTLE_STATES.PLAYER_TURN;
  }

  // 处理状态效果
  processStatusEffects(character) {
    if (!character.statusEffects) return;
    
    character.statusEffects = character.statusEffects.filter(effect => {
      // 处理效果逻辑
      switch (effect.type) {
        case 'burn':
          const burnDamage = Math.floor(character.stats?.maxHp * 0.05);
          if (character === this.player) {
            character.currentHp = Math.max(0, character.currentHp - burnDamage);
          } else {
            character.stats.hp = Math.max(0, character.stats.hp - burnDamage);
          }
          this.addToLog(`${character.name} 受到燃烧伤害 ${burnDamage}！`);
          break;
      }
      
      effect.duration--;
      return effect.duration > 0;
    });
  }

  // 处理冷却
  processCooldowns(skills) {
    skills.forEach(skill => {
      if (skill.currentCooldown > 0) {
        skill.currentCooldown--;
      }
    });
  }

  // 添加战斗日志
  addToLog(message) {
    this.battleLog.push({
      message,
      timestamp: Date.now(),
      turn: this.turnCount
    });
  }

  // 获取战斗状态
  getBattleState() {
    return {
      state: this.state,
      player: this.player,
      enemy: this.enemy,
      turnCount: this.turnCount,
      battleLog: this.battleLog
    };
  }
}

// 导出战斗管理器实例
export const battleManager = new BattleManager();