import React, { useState } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { practiceDaoXing, addDaoXingExp, updateDaoXing } from '../../store/characterSlice';
import { addSystemLog, showToast } from '../../store/uiSlice';

function DaoXingPanel() {
  const dispatch = useDispatch();
  const character = useSelector(state => state.character);
  const [isPracticing, setIsPracticing] = useState(false);
  const [practiceType, setPracticeType] = useState('meditation'); // meditation, combat, enlightenment

  // 道行等级名称
  const getDaoXingLevelName = (level) => {
    const names = [
      '凡人', '练气', '筑基', '结丹', '元婴',
      '化神', '炼虚', '合体', '大乘', '渡劫',
      '地仙', '天仙', '金仙', '太乙', '大罗',
      '混元', '圣人', '天道', '无极', '太极'
    ];
    return names[Math.min(level - 1, names.length - 1)] || '未知';
  };

  // 获取道行进度百分比
  const getDaoXingProgress = () => {
    if (character.daoXingLevel >= character.maxDaoXingLevel) return 100;
    return (character.daoXingExp / character.daoXingExpNeeded) * 100;
  };

  // 修炼成功率计算
  const getPracticeSuccessRate = (type) => {
    let baseRate = 50;
    
    switch (type) {
      case 'meditation':
        baseRate = 70 + (character.elementAttributes.水 * 2); // 水属性影响冥想
        break;
      case 'combat':
        baseRate = 60 + (character.elementAttributes.火 * 2); // 火属性影响实战
        break;
      case 'enlightenment':
        baseRate = 40 + (character.elementAttributes.金 * 2); // 金属性影响领悟
        break;
      default:
        break;
    }
    
    // 道行等级越高，成功率越低
    baseRate = Math.max(10, baseRate - (character.daoXingLevel * 2));
    
    return Math.min(95, baseRate);
  };

  // 获得经验值计算
  const getPracticeExpReward = (type, success) => {
    let baseExp = 10;
    
    if (success) {
      switch (type) {
        case 'meditation':
          baseExp = 15 + Math.floor(character.daoXingLevel * 1.5);
          break;
        case 'combat':
          baseExp = 20 + Math.floor(character.daoXingLevel * 2);
          break;
        case 'enlightenment':
          baseExp = 25 + Math.floor(character.daoXingLevel * 2.5);
          break;
        default:
          break;
      }
    } else {
      baseExp = 5; // 失败也有少量经验
    }
    
    return baseExp;
  };

  // 开始修炼
  const handlePractice = async () => {
    if (isPracticing || character.daoXingLevel >= character.maxDaoXingLevel) return;
    
    setIsPracticing(true);
    
    // 模拟修炼过程
    const practiceTime = 2000 + Math.random() * 3000; // 2-5秒随机时间
    
    setTimeout(() => {
      const successRate = getPracticeSuccessRate(practiceType);
      const success = Math.random() * 100 < successRate;
      const expReward = getPracticeExpReward(practiceType, success);
      
      if (success) {
        dispatch(addDaoXingExp(expReward));
        dispatch(updateDaoXing());
        
        const messages = {
          meditation: ['心境澄明，道行有所精进', '冥想中悟出玄机', '静心凝神，境界提升'],
          combat: ['实战中磨练道心', '战斗中领悟武道真谛', '血战中突破境界'],
          enlightenment: ['天人合一，道行大进', '顿悟天机，境界飞升', '参悟玄理，道行圆满']
        };
        
        const message = messages[practiceType][Math.floor(Math.random() * messages[practiceType].length)];
        dispatch(addSystemLog({ message: `${message}，道行经验+${expReward}` }));
        dispatch(showToast({ message: `修炼成功！道行经验+${expReward}`, type: 'success' }));
      } else {
        dispatch(practiceDaoXing({ success: false }));
        
        const failMessages = {
          meditation: ['心境不宁，冥想失败', '杂念丛生，修炼受阻', '心神不定，未有所得'],
          combat: ['实战失利，略有损失', '战斗中分心，修炼受挫', '对手太强，未能领悟'],
          enlightenment: ['天机难测，参悟失败', '玄理深奥，暂未顿悟', '道心未坚，领悟受阻']
        };
        
        const message = failMessages[practiceType][Math.floor(Math.random() * failMessages[practiceType].length)];
        dispatch(addSystemLog({ message: `${message}，道行经验-5` }));
        dispatch(showToast({ message: '修炼失败，道行经验-5', type: 'normal' }));
      }
      
      setIsPracticing(false);
    }, practiceTime);
  };

  // 修炼类型配置
  const practiceTypes = {
    meditation: {
      name: '冥想修炼',
      icon: '🧘',
      description: '静心凝神，稳步提升道行',
      color: '#87CEEB',
      time: '2-4秒',
      requirement: '需要宁静的心境'
    },
    combat: {
      name: '实战修炼', 
      icon: '⚔️',
      description: '在战斗中磨练道心',
      color: '#DC143C',
      time: '3-5秒',
      requirement: '需要勇敢的意志'
    },
    enlightenment: {
      name: '顿悟修炼',
      icon: '✨',
      description: '参悟天机，可能获得巨大突破',
      color: '#FFD700',
      time: '4-6秒',
      requirement: '需要深厚的底蕴'
    }
  };

  return (
    <div className="daoxing-panel" style={{
      background: 'rgba(0,0,0,0.3)',
      border: '1px solid #D4AF37',
      borderRadius: '8px',
      padding: '15px',
      margin: '10px 0'
    }}>
      <h4 style={{
        color: '#D4AF37',
        margin: '0 0 15px 0',
        fontSize: '16px',
        fontWeight: 'bold',
        textAlign: 'center'
      }}>
        ✨ 道行修炼 ✨
      </h4>

      {/* 道行状态显示 */}
      <div style={{
        background: 'linear-gradient(135deg, rgba(212, 175, 55, 0.2), rgba(184, 134, 11, 0.2))',
        border: '1px solid #D4AF37',
        borderRadius: '8px',
        padding: '15px',
        marginBottom: '20px'
      }}>
        <div style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          marginBottom: '10px'
        }}>
          <div style={{ color: '#D4AF37', fontSize: '14px', fontWeight: 'bold' }}>
            {getDaoXingLevelName(character.daoXingLevel)} ({character.daoXingLevel}重)
          </div>
          <div style={{ color: '#F4E4BC', fontSize: '12px' }}>
            道行值: {character.daoXing}
          </div>
        </div>

        {/* 道行进度条 */}
        <div style={{
          background: 'rgba(0, 0, 0, 0.3)',
          borderRadius: '10px',
          height: '20px',
          position: 'relative',
          overflow: 'hidden'
        }}>
          <div style={{
            background: 'linear-gradient(90deg, #D4AF37, #FFD700)',
            height: '100%',
            width: `${getDaoXingProgress()}%`,
            transition: 'width 0.3s ease',
            borderRadius: '10px'
          }} />
          <div style={{
            position: 'absolute',
            top: '50%',
            left: '50%',
            transform: 'translate(-50%, -50%)',
            color: '#000',
            fontSize: '11px',
            fontWeight: 'bold',
            textShadow: '1px 1px 2px rgba(255,255,255,0.8)'
          }}>
            {character.daoXingLevel >= character.maxDaoXingLevel 
              ? '道行圆满' 
              : `${character.daoXingExp}/${character.daoXingExpNeeded}`
            }
          </div>
        </div>
      </div>

      {/* 修炼方式选择 */}
      <div style={{ marginBottom: '20px' }}>
        <div style={{ color: '#F4E4BC', fontSize: '12px', marginBottom: '10px' }}>
          选择修炼方式：
        </div>
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(3, 1fr)',
          gap: '8px'
        }}>
          {Object.entries(practiceTypes).map(([type, config]) => (
            <button
              key={type}
              onClick={() => setPracticeType(type)}
              disabled={isPracticing}
              style={{
                background: practiceType === type 
                  ? `linear-gradient(135deg, ${config.color}40, ${config.color}20)`
                  : 'rgba(60, 60, 60, 0.3)',
                border: practiceType === type 
                  ? `2px solid ${config.color}` 
                  : '1px solid #666',
                borderRadius: '8px',
                padding: '10px',
                cursor: isPracticing ? 'not-allowed' : 'pointer',
                textAlign: 'center',
                color: practiceType === type ? config.color : '#F4E4BC',
                fontSize: '10px'
              }}
            >
              <div style={{ fontSize: '16px', marginBottom: '4px' }}>
                {config.icon}
              </div>
              <div style={{ fontWeight: 'bold', marginBottom: '2px' }}>
                {config.name}
              </div>
              <div style={{ opacity: 0.8 }}>
                成功率: {getPracticeSuccessRate(type)}%
              </div>
            </button>
          ))}
        </div>
      </div>

      {/* 选中修炼方式的详细信息 */}
      <div style={{
        background: 'rgba(60, 60, 60, 0.2)',
        border: '1px solid #666',
        borderRadius: '6px',
        padding: '10px',
        marginBottom: '20px'
      }}>
        <div style={{ color: practiceTypes[practiceType].color, fontSize: '12px', fontWeight: 'bold', marginBottom: '5px' }}>
          {practiceTypes[practiceType].name}
        </div>
        <div style={{ color: '#F4E4BC', fontSize: '10px', marginBottom: '3px' }}>
          {practiceTypes[practiceType].description}
        </div>
        <div style={{ color: '#87CEEB', fontSize: '9px' }}>
          耗时: {practiceTypes[practiceType].time} • {practiceTypes[practiceType].requirement}
        </div>
        <div style={{ color: '#90EE90', fontSize: '9px', marginTop: '3px' }}>
          成功时可获得 {getPracticeExpReward(practiceType, true)} 道行经验
        </div>
      </div>

      {/* 修炼按钮 */}
      <button
        onClick={handlePractice}
        disabled={isPracticing || character.daoXingLevel >= character.maxDaoXingLevel}
        style={{
          width: '100%',
          background: isPracticing
            ? 'rgba(60, 60, 60, 0.5)'
            : character.daoXingLevel >= character.maxDaoXingLevel
              ? 'rgba(144, 238, 144, 0.3)'
              : 'linear-gradient(135deg, #D4AF37, #B8860B)',
          border: 'none',
          borderRadius: '8px',
          padding: '15px',
          color: isPracticing || character.daoXingLevel >= character.maxDaoXingLevel
            ? '#888'
            : '#2C1810',
          fontSize: '14px',
          fontWeight: 'bold',
          cursor: isPracticing || character.daoXingLevel >= character.maxDaoXingLevel
            ? 'not-allowed'
            : 'pointer',
          textAlign: 'center'
        }}
      >
        {isPracticing 
          ? `${practiceTypes[practiceType].icon} 修炼中...` 
          : character.daoXingLevel >= character.maxDaoXingLevel
            ? '✨ 道行已臻圆满 ✨'
            : `${practiceTypes[practiceType].icon} 开始${practiceTypes[practiceType].name}`
        }
      </button>

      {/* 道行说明 */}
      <div style={{
        marginTop: '15px',
        fontSize: '9px',
        color: '#F4E4BC',
        opacity: 0.7,
        textAlign: 'center',
        borderTop: '1px solid #666',
        paddingTop: '10px'
      }}>
        💡 道行影响法术成功率和战斗表现，五行属性会影响不同修炼方式的成功率
      </div>
    </div>
  );
}

export default DaoXingPanel;