import React from 'react';

/**
 * 女娲石图标组件 - 立体水晶宝石效果
 * @param {string} size - 尺寸 (small/normal/large)
 * @param {string} className - 额外CSS类名
 * @param {object} style - 内联样式
 */
const SuperStoneIcon = ({ size = 'normal', className = '', style = {} }) => {
  const dimensions = {
    small: { width: 16, height: 16 },
    normal: { width: 24, height: 24 },
    large: { width: 32, height: 32 }
  };

  const { width, height } = dimensions[size] || dimensions.normal;

  return (
    <svg
      width={width}
      height={height}
      viewBox="0 0 32 32"
      className={`super-stone-icon ${className}`}
      style={{
        transform: 'rotate(-15deg)',
        ...style
      }}
    >
      <defs>
        {/* 深紫色透白渐变 */}
        <linearGradient id="purpleGradient" x1="0%" y1="0%" x2="100%" y2="100%">
          <stop offset="0%" stopColor="#E6D9FF" stopOpacity="0.95"/>
          <stop offset="25%" stopColor="#C4A1FF" stopOpacity="0.9"/>
          <stop offset="60%" stopColor="#7B2CBF" stopOpacity="0.95"/>
          <stop offset="100%" stopColor="#3C0A5C" stopOpacity="1"/>
        </linearGradient>
        
        {/* 金属光泽渐变 */}
        <linearGradient id="metalGradient" x1="0%" y1="0%" x2="100%" y2="100%">
          <stop offset="0%" stopColor="#FFFFFF" stopOpacity="0.8"/>
          <stop offset="20%" stopColor="#FFD700" stopOpacity="0.6"/>
          <stop offset="50%" stopColor="#C0C0C0" stopOpacity="0.4"/>
          <stop offset="80%" stopColor="#FFD700" stopOpacity="0.3"/>
          <stop offset="100%" stopColor="#FFFFFF" stopOpacity="0.2"/>
        </linearGradient>

        {/* 高光效果 */}
        <radialGradient id="highlight" cx="30%" cy="20%">
          <stop offset="0%" stopColor="#FFFFFF" stopOpacity="0.9"/>
          <stop offset="50%" stopColor="#FFFFFF" stopOpacity="0.3"/>
          <stop offset="100%" stopColor="#FFFFFF" stopOpacity="0"/>
        </radialGradient>

        {/* 紫色光晕 */}
        <filter id="purpleGlow" x="-50%" y="-50%" width="200%" height="200%">
          <feGaussianBlur stdDeviation="2" result="coloredBlur"/>
          <feMerge>
            <feMergeNode in="coloredBlur"/>
            <feMergeNode in="SourceGraphic"/>
          </feMerge>
        </filter>

        {/* 阴影 */}
        <filter id="dropShadow" x="-20%" y="-20%" width="140%" height="140%">
          <feDropShadow dx="1" dy="2" stdDeviation="1" floodColor="#2E003E" floodOpacity="0.5"/>
        </filter>
      </defs>

      {/* 主体宝石 - 八角形 */}
      <polygon
        points="16,4 22,8 26,16 22,24 16,28 10,24 6,16 10,8"
        fill="url(#purpleGradient)"
        filter="url(#purpleGlow)"
        opacity="0.9"
      />

      {/* 立体切面效果 */}
      <polygon
        points="16,4 22,8 16,16 10,8"
        fill="url(#metalGradient)"
        opacity="0.3"
      />
      <polygon
        points="22,8 26,16 16,16"
        fill="#7B2CBF"
        opacity="0.4"
      />
      <polygon
        points="16,16 26,16 22,24 16,28"
        fill="#3C0A5C"
        opacity="0.5"
      />

      {/* 高光反射 */}
      <ellipse
        cx="18" cy="10"
        rx="4" ry="3"
        fill="url(#highlight)"
        opacity="0.6"
      />
      
      {/* 小的闪光点 */}
      <circle cx="20" cy="8" r="1" fill="#FFFFFF" opacity="0.8"/>
      <circle cx="14" cy="12" r="0.5" fill="#C4A1FF" opacity="0.9"/>
      <circle cx="18" cy="20" r="0.5" fill="#FFFFFF" opacity="0.6"/>

      {/* 外围光晕 */}
      <circle
        cx="16" cy="16" r="15"
        fill="none"
        stroke="#4A148C"
        strokeWidth="0.5"
        opacity="0.3"
        filter="url(#dropShadow)"
      />
    </svg>
  );
};

export default SuperStoneIcon;