import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  name: '玩家',
  level: 1,
  experience: 0,
  experienceNeeded: 1000,
  gold: 1000,
  element: null, // '金', '木', '水', '火', '土'
  attributes: {
    strength: 0,      // 力量
    constitution: 0,  // 体质
    spirit: 0,        // 灵力
    agility: 0,       // 敏捷
  },
  availablePoints: 4,
  elementPoints: 1,
  elementAttributes: {
    金: 0,
    木: 0,
    水: 0,
    火: 0,
    土: 0,
  },
  powerRating: 100,
  items: [],
  maxHp: 1000,
  currentHp: 1000,
  maxMana: 500,
  currentMana: 500,
  baseAttack: 100,
  baseDefense: 50,
  baseSpeed: 100,
  equipment: {},
  skills: [],
  // 道行系统
  daoXing: 0,           // 当前道行值
  daoXingLevel: 1,      // 道行等级
  daoXingExp: 0,        // 道行经验
  daoXingExpNeeded: 100, // 升级所需道行经验
  maxDaoXingLevel: 20,  // 最大道行等级
};

const characterSlice = createSlice({
  name: 'character',
  initialState,
  reducers: {
    selectElement: (state, action) => {
      state.element = action.payload;
    },
    increaseAttribute: (state, action) => {
      const { attribute } = action.payload;
      if (state.availablePoints > 0) {
        state.attributes[attribute]++;
        state.availablePoints--;
      }
    },
    decreaseAttribute: (state, action) => {
      const { attribute } = action.payload;
      if (state.attributes[attribute] > 0) {
        state.attributes[attribute]--;
        state.availablePoints++;
      }
    },
    increaseElementAttribute: (state, action) => {
      const { element } = action.payload;
      if (state.elementPoints > 0) {
        state.elementAttributes[element]++;
        state.elementPoints--;
      }
    },
    decreaseElementAttribute: (state, action) => {
      const { element } = action.payload;
      if (state.elementAttributes[element] > 0) {
        state.elementAttributes[element]--;
        state.elementPoints++;
      }
    },
    levelUp: (state) => {
      if (state.level < 150) {
        state.level++;
        state.availablePoints += 4;
        state.elementPoints += 1;
      }
    },
    resetCharacter: (state) => {
      return initialState;
    },
    updatePowerRating: (state) => {
      let power = 0;
      // 基础属性战力
      power += state.attributes.strength * 10;
      power += state.attributes.constitution * 8;
      power += state.attributes.spirit * 12;
      power += state.attributes.agility * 6;
      
      // 五行战力
      if (state.element) {
        const elementRelations = {
          generate: { 金: '水', 木: '火', 水: '木', 火: '土', 土: '金' },
          overcome: { 金: '木', 木: '土', 水: '火', 火: '金', 土: '水' }
        };
        
        power += state.elementAttributes[state.element] * 50;
        const generate = elementRelations.generate[state.element];
        const overcome = elementRelations.overcome[state.element];
        power += state.elementAttributes[generate] * 30;
        power += state.elementAttributes[overcome] * 40;
      }
      
      // 等级战力
      power += state.level * 100;
      
      state.powerRating = Math.floor(power);
    },
    // 添加经验
    addExperience: (state, action) => {
      const exp = action.payload;
      state.experience += exp;
      
      // 检查升级
      while (state.experience >= state.experienceNeeded && state.level < 150) {
        state.experience -= state.experienceNeeded;
        state.level++;
        state.availablePoints += 4;
        state.elementPoints += 1;
        state.experienceNeeded = Math.floor(state.experienceNeeded * 1.2);
        
        // 升级时恢复生命值和法力值
        state.maxHp += 50;
        state.maxMana += 25;
        state.currentHp = state.maxHp;
        state.currentMana = state.maxMana;
      }
    },
    
    // 添加金币
    addGold: (state, action) => {
      state.gold += action.payload;
    },
    
    // 添加物品
    addItem: (state, action) => {
      const item = action.payload;
      const existingItem = state.items.find(i => i.name === item.name && i.type === item.type);
      
      if (existingItem) {
        existingItem.quantity = (existingItem.quantity || 1) + (item.quantity || 1);
      } else {
        state.items.push({ ...item, quantity: item.quantity || 1 });
      }
    },
    
    // 恢复生命值
    restoreHp: (state, action) => {
      const amount = action.payload;
      state.currentHp = Math.min(state.currentHp + amount, state.maxHp);
    },
    
    // 恢复法力值
    restoreMana: (state, action) => {
      const amount = action.payload;
      state.currentMana = Math.min(state.currentMana + amount, state.maxMana);
    },
    
    // 增加道行经验
    addDaoXingExp: (state, action) => {
      const exp = action.payload;
      state.daoXingExp += exp;
      
      // 检查道行升级
      while (state.daoXingExp >= state.daoXingExpNeeded && state.daoXingLevel < state.maxDaoXingLevel) {
        state.daoXingExp -= state.daoXingExpNeeded;
        state.daoXingLevel++;
        
        // 道行值增加（影响战斗成功率）
        state.daoXing += state.daoXingLevel * 10;
        
        // 升级所需经验递增
        state.daoXingExpNeeded = Math.floor(state.daoXingExpNeeded * 1.3);
        
        console.log(`[道行进步] 道行等级提升至 ${state.daoXingLevel} 级，道行值：${state.daoXing}`);
      }
    },
    
    // 直接设置道行值（用于战斗计算）
    updateDaoXing: (state) => {
      // 基础道行计算：等级 * 2 + 道行等级 * 10 + 五行等级奖励
      let baseDaoXing = state.level * 2 + state.daoXingLevel * 10;
      
      // 五行专精奖励
      if (state.element) {
        baseDaoXing += state.elementAttributes[state.element] * 5;
      }
      
      state.daoXing = baseDaoXing;
    },
    
    // 道行修炼（手动增加道行经验的方法）
    practiceDaoXing: (state, action) => {
      const { success } = action.payload;
      if (success) {
        // 成功修炼获得经验
        const baseExp = 10 + Math.floor(state.daoXingLevel * 2);
        state.daoXingExp += baseExp;
        
        // 检查升级
        if (state.daoXingExp >= state.daoXingExpNeeded && state.daoXingLevel < state.maxDaoXingLevel) {
          const oldLevel = state.daoXingLevel;
          state.daoXingExp -= state.daoXingExpNeeded;
          state.daoXingLevel++;
          state.daoXing += state.daoXingLevel * 10;
          state.daoXingExpNeeded = Math.floor(state.daoXingExpNeeded * 1.3);
          
          return {
            ...state,
            levelUpMessage: `道行突破！达到${state.daoXingLevel}重境界！`
          };
        }
      } else {
        // 失败时损失少量道行经验（但不会降级）
        state.daoXingExp = Math.max(0, state.daoXingExp - 5);
      }
    },

    // 加载存档数据
    loadCharacterData: (state, action) => {
      const { character } = action.payload;
      if (character) {
        Object.keys(initialState).forEach(key => {
          if (character[key] !== undefined) {
            state[key] = character[key];
          }
        });
        console.log(`[实时存档] 角色数据已恢复：${state.level}级，五行：${state.element}`);
      }
    },
  },
});

export const {
  selectElement,
  increaseAttribute,
  decreaseAttribute,
  increaseElementAttribute,
  decreaseElementAttribute,
  levelUp,
  resetCharacter,
  updatePowerRating,
  addExperience,
  addGold,
  addItem,
  restoreHp,
  restoreMana,
  addDaoXingExp,
  updateDaoXing,
  practiceDaoXing,
  loadCharacterData,
} = characterSlice.actions;

export default characterSlice.reducer;