import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  // 拥有的宠物列表
  pets: [],
  
  // 出战宠物ID（目前只支持一只）
  activePetId: null,
  
  // 宠物属性配置
  petTypes: [
    {
      id: 'thunder_bird',
      name: '雷鸟',
      element: '金',
      baseStats: { attack: 80, defense: 40, speed: 140, hp: 600, mp: 300 },
      skills: ['thunder_strike', 'speed_boost'],
      rarity: 'common'
    },
    {
      id: 'earth_bear',
      name: '土熊',
      element: '土',
      baseStats: { attack: 120, defense: 80, speed: 60, hp: 900, mp: 200 },
      skills: ['earth_slam', 'defense_boost'],
      rarity: 'common'
    },
    {
      id: 'fire_fox',
      name: '火狐',
      element: '火',
      baseStats: { attack: 100, defense: 50, speed: 120, hp: 700, mp: 400 },
      skills: ['fire_ball', 'burn_attack'],
      rarity: 'uncommon'
    },
    {
      id: 'water_turtle',
      name: '水龟',
      element: '水',
      baseStats: { attack: 60, defense: 100, speed: 40, hp: 1000, mp: 500 },
      skills: ['water_shield', 'heal_wave'],
      rarity: 'uncommon'
    },
    {
      id: 'wood_deer',
      name: '木鹿',
      element: '木',
      baseStats: { attack: 70, defense: 60, speed: 100, hp: 800, mp: 600 },
      skills: ['nature_heal', 'poison_spore'],
      rarity: 'uncommon'
    }
  ],
  
  // 宠物技能配置
  petSkills: {
    thunder_strike: { name: '雷击', type: 'attack', element: '金', power: 120, manaCost: 30 },
    speed_boost: { name: '疾风术', type: 'buff', target: 'self', effect: 'speed_up', duration: 3, manaCost: 20 },
    earth_slam: { name: '大地猛击', type: 'attack', element: '土', power: 140, manaCost: 25 },
    defense_boost: { name: '铁壁术', type: 'buff', target: 'self', effect: 'defense_up', duration: 4, manaCost: 25 },
    fire_ball: { name: '火球术', type: 'attack', element: '火', power: 110, manaCost: 35 },
    burn_attack: { name: '灼烧爪', type: 'attack', element: '火', power: 90, effect: 'burn', manaCost: 20 },
    water_shield: { name: '水盾', type: 'buff', target: 'ally', effect: 'shield', value: 200, manaCost: 40 },
    heal_wave: { name: '治疗波', type: 'heal', target: 'ally', power: 150, manaCost: 30 },
    nature_heal: { name: '自然恢复', type: 'heal', target: 'ally', power: 120, manaCost: 25 },
    poison_spore: { name: '毒孢子', type: 'attack', element: '木', power: 80, effect: 'poison', manaCost: 30 }
  }
};

const petSlice = createSlice({
  name: 'pets',
  initialState,
  reducers: {
    // 添加宠物
    addPet: (state, action) => {
      const petData = action.payload;
      const newPet = {
        id: Date.now() + Math.random(),
        ...petData,
        level: petData.level || 1,
        experience: 0,
        loyalty: 50, // 忠诚度
        currentStats: { ...petData.baseStats }, // 当前属性值（可能有装备或状态影响）
        statusEffects: [],
        isActive: false
      };
      
      state.pets.push(newPet);
    },

    // 移除宠物
    removePet: (state, action) => {
      const petId = action.payload;
      state.pets = state.pets.filter(pet => pet.id !== petId);
      
      // 如果移除的是出战宠物，清除出战状态
      if (state.activePetId === petId) {
        state.activePetId = null;
      }
    },

    // 设置出战宠物
    setActivePet: (state, action) => {
      const petId = action.payload;
      
      // 清除之前的出战宠物
      state.pets.forEach(pet => {
        pet.isActive = false;
      });
      
      // 设置新的出战宠物
      const pet = state.pets.find(p => p.id === petId);
      if (pet) {
        pet.isActive = true;
        state.activePetId = petId;
      }
    },

    // 取消出战
    clearActivePet: (state) => {
      state.pets.forEach(pet => {
        pet.isActive = false;
      });
      state.activePetId = null;
    },

    // 更新宠物属性
    updatePet: (state, action) => {
      const { petId, updates } = action.payload;
      const pet = state.pets.find(p => p.id === petId);
      
      if (pet) {
        Object.assign(pet, updates);
      }
    },

    // 宠物升级
    levelUpPet: (state, action) => {
      const petId = action.payload;
      const pet = state.pets.find(p => p.id === petId);
      
      if (pet && pet.level < 150) {
        pet.level++;
        pet.experience = 0;
        
        // 属性成长
        const growthRate = 1.1;
        pet.baseStats.attack = Math.floor(pet.baseStats.attack * growthRate);
        pet.baseStats.defense = Math.floor(pet.baseStats.defense * growthRate);
        pet.baseStats.hp = Math.floor(pet.baseStats.hp * growthRate);
        pet.baseStats.mp = Math.floor(pet.baseStats.mp * growthRate);
        pet.baseStats.speed += Math.floor(Math.random() * 3) + 1;
        
        // 更新当前属性
        pet.currentStats = { ...pet.baseStats };
      }
    },

    // 增加宠物经验
    addPetExperience: (state, action) => {
      const { petId, exp } = action.payload;
      const pet = state.pets.find(p => p.id === petId);
      
      if (pet) {
        pet.experience += exp;
        
        // 检查是否可以升级
        const expNeeded = pet.level * 100;
        if (pet.experience >= expNeeded) {
          petSlice.caseReducers.levelUpPet(state, { payload: petId });
        }
      }
    },

    // 更新忠诚度
    updateLoyalty: (state, action) => {
      const { petId, change } = action.payload;
      const pet = state.pets.find(p => p.id === petId);
      
      if (pet) {
        pet.loyalty = Math.max(0, Math.min(100, pet.loyalty + change));
      }
    },

    // 喂食宠物（增加忠诚度和经验）
    feedPet: (state, action) => {
      const petId = action.payload;
      const pet = state.pets.find(p => p.id === petId);
      
      if (pet) {
        pet.loyalty = Math.min(100, pet.loyalty + 5);
        pet.experience += 20;
        
        // 检查升级
        const expNeeded = pet.level * 100;
        if (pet.experience >= expNeeded) {
          petSlice.caseReducers.levelUpPet(state, { payload: petId });
        }
      }
    },

    // 初始化默认宠物
    initializeDefaultPets: (state) => {
      if (state.pets.length === 0) {
        // 给玩家一只初始宠物
        const defaultPet = {
          ...state.petTypes[0], // 雷鸟
          id: Date.now(),
          level: 5,
          experience: 0,
          loyalty: 80,
          currentStats: { ...state.petTypes[0].baseStats },
          statusEffects: [],
          isActive: false
        };
        
        state.pets.push(defaultPet);
      }
    },

    // 重置宠物系统
    resetPets: () => initialState
  }
});

export const {
  addPet,
  removePet,
  setActivePet,
  clearActivePet,
  updatePet,
  levelUpPet,
  addPetExperience,
  updateLoyalty,
  feedPet,
  initializeDefaultPets,
  resetPets
} = petSlice.actions;

export default petSlice.reducer;