import React from 'react';
import './JewelryIcon.css';

/**
 * 首饰图标组件 - 使用SVG雪碧图替换emoji
 * @param {string} type - 首饰类型 (necklace/pendant/bracelet)
 * @param {number} level - 首饰等级
 * @param {string} className - 额外CSS类名
 * @param {object} style - 内联样式
 * @param {string} size - 尺寸 (normal/large)
 */
const JewelryIcon = ({ type, level, className = '', style = {}, size = 'normal' }) => {
  // 生成CSS类名
  const spriteClass = `wendao-jewelry-${type}_${level}`;
  const levelClass = `level-${level}`;
  const sizeClass = size === 'large' ? 'large' : '';
  
  return (
    <div 
      className={`wendao-jewelry-svg ${spriteClass} jewelry-icon ${levelClass} ${sizeClass} ${className}`}
      style={style}
      title={`${level}级${type === 'necklace' ? '项链' : type === 'pendant' ? '玉佩' : '手镯'}`}
    />
  );
};

export default JewelryIcon;