/**
 * 问道风格战斗管理器
 */
class WendaoBattleManager {
  constructor() {
    this.reset();
  }

  reset() {
    // 战斗状态
    this.phase = BATTLE_PHASES.PREPARATION;
    this.turnCount = 1;
    this.maxTurns = 30;
    
    // 战斗单位
    this.playerTeam = [];    // 玩家方：[玩家, 宠物]
    this.enemyTeam = [];     // 敌方：[敌人1, 敌人2, ...]
    this.allUnits = [];      // 所有单位
    
    // 指令系统
    this.playerCommands = new Map();  // 玩家指令
    this.petCommands = new Map();     // 宠物指令
    this.actionQueue = [];            // 执行队列
    
    // 战斗数据
    this.battleLog = [];
    this.currentExecutingUnit = null;
    this.battleResult = null;
  }

  /**
   * 初始化战斗
   */
  initBattle(playerData, enemyData, petData = null) {
    this.reset();
    
    // 创建玩家单位
    const playerUnit = this.createBattleUnit(playerData, 'player', 'player');
    this.playerTeam.push(playerUnit);
    
    // 创建宠物单位（如果有）
    if (petData) {
      const petUnit = this.createBattleUnit(petData, 'pet', 'player');
      this.playerTeam.push(petUnit);
    }
    
    // 创建敌方单位
    if (Array.isArray(enemyData)) {
      enemyData.forEach((enemy, index) => {
        const enemyUnit = this.createBattleUnit(enemy, `enemy_${index}`, 'enemy');
        this.enemyTeam.push(enemyUnit);
      });
    } else {
      const enemyUnit = this.createBattleUnit(enemyData, 'enemy_0', 'enemy');
      this.enemyTeam.push(enemyUnit);
    }
    
    // 合并所有单位
    this.allUnits = [...this.playerTeam, ...this.enemyTeam];
    
    // 进入玩家指令阶段
    this.phase = BATTLE_PHASES.PLAYER_COMMAND;
    
    this.addLog('⚔️ 战斗开始！', 'system');
    
    return {
      playerTeam: this.playerTeam,
      enemyTeam: this.enemyTeam,
      phase: this.phase,
      turnCount: this.turnCount,
      needPlayerCommand: true
    };
  }

  /**
   * 创建战斗单位
   */
  createBattleUnit(data, unitId, side) {
    return {
      id: unitId,
      name: data.name || '未知',
      level: data.level || 1,
      element: data.element || null,
      side: side, // 'player' 或 'enemy'
      type: unitId.includes('pet') ? 'pet' : (unitId.includes('player') ? 'player' : 'enemy'),
      
      // 战斗属性
      stats: {
        maxHp: data.maxHp || data.hp || 1000,
        hp: data.hp || data.maxHp || 1000,
        maxMp: data.maxMp || data.mp || 500,
        mp: data.mp || data.maxMp || 500,
        attack: data.attack || 100,
        defense: data.defense || 50,
        speed: data.speed || 100,
        daoXing: data.daoXing || 0  // 道行
      },
      
      // 状态效果
      statusEffects: [],
      
      // 可用技能
      skills: this.getUnitSkills(data.element, unitId.includes('pet')),
      
      // 战斗状态
      isAlive: true,
      defending: false,
      
      // 装备加成
      equipment: data.equipment || {},
      jewelry: data.jewelry || [],
      
      // 原始数据引用
      originalData: data
    };
  }

  /**
   * 获取单位技能列表
   */
  getUnitSkills(element, isPet = false) {
    const skills = [
      {
        id: 'normal_attack',
        name: '普通攻击',
        type: ACTION_TYPES.PHYSICAL,
        power: 100,
        manaCost: 0,
        description: '普通物理攻击'
      }
    ];
    
    // 添加五行技能
    if (element && ELEMENT_SKILLS[element]) {
      Object.values(ELEMENT_SKILLS[element]).forEach(skill => {
        skills.push(skill);
      });
    }
    
    // 宠物额外技能
    if (isPet) {
      skills.push({
        id: 'pet_special',
        name: '宠物技',
        type: ACTION_TYPES.PHYSICAL,
        power: 120,
        manaCost: 10,
        description: '宠物特殊攻击'
      });
    }
    
    return skills;
  }

  /**
   * 设置玩家指令
   */
  setPlayerCommand(unitId, command) {
    if (this.phase !== BATTLE_PHASES.PLAYER_COMMAND) {
      return { success: false, message: '当前不是玩家指令阶段' };
    }
    
    const unit = this.playerTeam.find(u => u.id === unitId);
    if (!unit || !unit.isAlive) {
      return { success: false, message: '无效的单位' };
    }
    
    // 验证指令
    if (!this.validateCommand(unit, command)) {
      return { success: false, message: '无效的指令' };
    }
    
    this.playerCommands.set(unitId, command);
    
    // 检查是否所有玩家单位都已下达指令
    const playerUnits = this.playerTeam.filter(u => u.isAlive);
    const allPlayerCommandsSet = playerUnits.every(u => this.playerCommands.has(u.id));
    
    if (allPlayerCommandsSet) {
      // 检查是否有宠物需要下令
      const hasPet = this.playerTeam.some(u => u.type === 'pet' && u.isAlive);
      if (hasPet) {
        this.phase = BATTLE_PHASES.PET_COMMAND;
        return { success: true, message: '请为宠物下达指令', nextPhase: 'pet_command' };
      } else {
        // 直接进入执行阶段
        return this.startExecution();
      }
    }
    
    return { success: true, message: '指令已设置' };
  }

  /**
   * 设置宠物指令
   */
  setPetCommand(unitId, command) {
    if (this.phase !== BATTLE_PHASES.PET_COMMAND) {
      return { success: false, message: '当前不是宠物指令阶段' };
    }
    
    const unit = this.playerTeam.find(u => u.id === unitId && u.type === 'pet');
    if (!unit || !unit.isAlive) {
      return { success: false, message: '无效的宠物单位' };
    }
    
    if (!this.validateCommand(unit, command)) {
      return { success: false, message: '无效的指令' };
    }
    
    this.petCommands.set(unitId, command);
    
    // 检查是否所有宠物都已下达指令
    const petUnits = this.playerTeam.filter(u => u.type === 'pet' && u.isAlive);
    const allPetCommandsSet = petUnits.every(u => this.petCommands.has(u.id));
    
    if (allPetCommandsSet) {
      return this.startExecution();
    }
    
    return { success: true, message: '宠物指令已设置' };
  }

  /**
   * 开始执行阶段
   */
  startExecution() {
    this.phase = BATTLE_PHASES.EXECUTION;
    
    // 生成AI指令
    this.generateAICommands();
    
    // 构建行动队列（按速度排序）
    this.buildActionQueue();
    
    return {
      success: true,
      message: '开始执行回合',
      nextPhase: 'execution',
      actionQueue: this.actionQueue.map(item => ({
        unitName: item.unit.name,
        actionName: this.getActionName(item.command)
      }))
    };
  }

  /**
   * 构建行动队列
   */
  buildActionQueue() {
    const activeUnits = this.allUnits.filter(u => u.isAlive);
    
    // 按速度排序（考虑状态效果）
    activeUnits.sort((a, b) => {
      const speedA = this.getEffectiveSpeed(a);
      const speedB = this.getEffectiveSpeed(b);
      return speedB - speedA; // 从高到低
    });
    
    this.actionQueue = activeUnits.map(unit => {
      let command;
      
      if (unit.side === 'player') {
        command = this.playerCommands.get(unit.id) || this.petCommands.get(unit.id);
      } else {
        command = this.enemyCommands.get(unit.id);
      }
      
      return {
        unit,
        command: command || { type: ACTION_TYPES.WAIT }
      };
    }).filter(item => item.command);
  }

  /**
   * 执行下一个行动
   */
  executeNextAction() {
    if (this.phase !== BATTLE_PHASES.EXECUTION) {
      return { success: false, message: '当前不是执行阶段' };
    }
    
    if (this.actionQueue.length === 0) {
      return this.endRound();
    }
    
    const actionItem = this.actionQueue.shift();
    const { unit, command } = actionItem;
    
    if (!unit.isAlive) {
      return this.executeNextAction(); // 跳过已死亡单位
    }
    
    this.currentExecutingUnit = unit;
    const result = this.executeAction(unit, command);
    
    // 检查战斗是否结束
    if (this.checkBattleEnd()) {
      this.phase = BATTLE_PHASES.BATTLE_END;
      this.battleResult = this.generateBattleResult();
      return {
        success: true,
        actionResult: result,
        battleEnd: true,
        battleResult: this.battleResult
      };
    }
    
    return {
      success: true,
      actionResult: result,
      canContinue: this.actionQueue.length > 0,
      nextUnit: this.actionQueue.length > 0 ? this.actionQueue[0].unit.name : null
    };
  }

  /**
   * 执行单个行动
   */
  executeAction(unit, command) {
    const result = {
      unit: unit.name,
      action: command.type,
      success: false,
      message: '',
      effects: []
    };
    
    // 检查状态效果限制
    const restrictions = this.checkStatusRestrictions(unit);
    if (restrictions.restricted) {
      result.message = restrictions.message;
      return result;
    }
    
    // 根据行动类型执行
    switch (command.type) {
      case ACTION_TYPES.PHYSICAL:
        return this.executePhysicalAttack(unit, command);
      case ACTION_TYPES.MAGIC:
        return this.executeMagicAttack(unit, command);
      case ACTION_TYPES.OBSTACLE:
        return this.executeObstacleSkill(unit, command);
      case ACTION_TYPES.HEAL:
        return this.executeHeal(unit, command);
      case ACTION_TYPES.DEFEND:
        return this.executeDefend(unit);
      default:
        result.message = `${unit.name} 待机`;
        result.success = true;
        this.addLog(`${unit.name} 待机`, 'action');
        return result;
    }
  }

  /**
   * 执行法术攻击
   */
  executeMagicAttack(attacker, command) {
    const targetId = command.target;
    const skill = command.skill;
    const target = this.allUnits.find(u => u.id === targetId);
    
    if (!target || !target.isAlive) {
      this.addLog(`${attacker.name} 施法失败，目标无效`, 'action');
      return { success: false, message: '目标无效' };
    }

    // 扣除法力
    if (attacker.stats.mp < skill.manaCost) {
      this.addLog(`${attacker.name} 法力不足`, 'action');
      return { success: false, message: '法力不足' };
    }

    attacker.stats.mp -= skill.manaCost;

    // 混乱状态：随机目标
    if (attacker.statusEffects.some(e => e.type === STATUS_TYPES.CHAOS)) {
      const allAlive = this.allUnits.filter(u => u.isAlive && u.id !== attacker.id);
      if (allAlive.length > 0) {
        const randomTarget = allAlive[Math.floor(Math.random() * allAlive.length)];
        this.addLog(`😵 ${attacker.name} 混乱中，法术目标改为 ${randomTarget.name}`, 'status');
        command.target = randomTarget.id;
        return this.executeMagicAttack(attacker, command);
      }
    }

    let damage = skill.power || 100;

    // 五行相克加成
    if (skill.element && target.element) {
      const multiplier = this.getElementMultiplier(skill.element, target.element);
      damage *= multiplier;
      
      if (multiplier > 1) {
        this.addLog(`🔥 五行相克！${skill.element}克${target.element}，法术威力提升`, 'element');
      }
    }

    // 防御减伤（法术减伤较少）
    damage -= target.stats.defense * 0.3;
    damage = Math.max(1, Math.floor(damage));

    // 防御状态减伤
    if (target.defending) {
      damage = Math.floor(damage * 0.7);
      this.addLog(`🛡️ ${target.name} 处于防御状态，法术伤害减少`, 'defend');
    }

    // 造成伤害（不可变更新）
    target.stats = {
      ...target.stats,
      hp: Math.max(0, target.stats.hp - damage)
    };

    this.addLog(`🔮 ${attacker.name} 对 ${target.name} 施展 ${skill.name}，造成 ${damage} 点伤害`, 'action');

    // 检查击败
    if (target.stats.hp <= 0) {
      // 不可变更新 isAlive 状态
      Object.assign(target, { isAlive: false });
      this.addLog(`💀 ${target.name} 被击败！`, 'defeat');
    }

    // 唤醒昏睡目标
    if (target.statusEffects.some(e => e.type === STATUS_TYPES.SLEEP)) {
      target.statusEffects = target.statusEffects.filter(e => e.type !== STATUS_TYPES.SLEEP);
      this.addLog(`${target.name} 被法术攻击唤醒`, 'status');
    }

    return {
      success: true,
      damage,
      target: target.name,
      message: `${skill.name} 造成 ${damage} 点伤害`
    };
  }

  /**
   * 执行治疗
   */
  executeHeal(caster, command) {
    const targetId = command.target || caster.id; // 默认治疗自己
    const skill = command.skill;
    const target = this.allUnits.find(u => u.id === targetId);
    
    if (!target || !target.isAlive) {
      this.addLog(`${caster.name} 治疗失败，目标无效`, 'action');
      return { success: false, message: '目标无效' };
    }

    // 扣除法力
    if (caster.stats.mp < skill.manaCost) {
      this.addLog(`${caster.name} 法力不足`, 'action');
      return { success: false, message: '法力不足' };
    }

    caster.stats.mp -= skill.manaCost;

    let healAmount = skill.power || 200;

    // 治疗量计算
    const missingHp = target.stats.maxHp - target.stats.hp;
    healAmount = Math.min(healAmount, missingHp);

    // 治疗（不可变更新）
    target.stats = {
      ...target.stats,
      hp: Math.min(target.stats.maxHp, target.stats.hp + healAmount)
    };

    this.addLog(`💚 ${caster.name} 对 ${target.name} 使用 ${skill.name}，恢复 ${healAmount} 气血`, 'heal');

    return {
      success: true,
      heal: healAmount,
      target: target.name,
      message: `恢复 ${healAmount} 气血`
    };
  }

  /**
   * 执行防御
   */
  executeDefend(unit) {
    unit.defending = true;
    this.addLog(`🛡️ ${unit.name} 进入防御状态`, 'defend');
    
    return {
      success: true,
      message: '进入防御状态',
      unit: unit.name
    };
  }

  /**
   * 检查状态限制
   */
  checkStatusRestrictions(unit) {
    // 冰冻：无法行动
    if (unit.statusEffects.some(e => e.type === STATUS_TYPES.FREEZE)) {
      this.addLog(`❄️ ${unit.name} 被冰冻，无法行动`, 'status');
      return { restricted: true, message: '被冰冻无法行动' };
    }
    
    // 昏睡：只能使用道具
    const sleepEffect = unit.statusEffects.find(e => e.type === STATUS_TYPES.SLEEP);
    if (sleepEffect) {
      this.addLog(`😴 ${unit.name} 昏睡中，行动受限`, 'status');
      return { restricted: false }; // 允许行动但有限制
    }
    
    return { restricted: false };
  }

  /**
   * 获取有效速度
   */
  getEffectiveSpeed(unit) {
    let speed = unit.stats.speed;
    
    // 状态效果影响
    const speedUp = unit.statusEffects.find(e => e.type === STATUS_TYPES.SPEED_UP);
    if (speedUp) speed *= 1.3;
    
    const speedDown = unit.statusEffects.find(e => e.type === STATUS_TYPES.SPEED_DOWN);
    if (speedDown) speed *= 0.7;
    
    const sleep = unit.statusEffects.find(e => e.type === STATUS_TYPES.SLEEP);
    if (sleep) speed *= 0.5;
    
    return Math.floor(speed);
  }

  /**
   * 生成AI指令
   */
  generateAICommands() {
    this.enemyCommands = new Map();
    
    this.enemyTeam.forEach(enemy => {
      if (!enemy.isAlive) return;
      
      // 简单AI逻辑
      const possibleTargets = this.playerTeam.filter(u => u.isAlive);
      if (possibleTargets.length === 0) return;
      
      const randomTarget = possibleTargets[Math.floor(Math.random() * possibleTargets.length)];
      
      let command;
      const rand = Math.random();
      
      if (rand < 0.3 && enemy.element && enemy.stats.mp >= 30) {
        // 30% 概率使用障碍技能
        const obstacleSkill = ELEMENT_SKILLS[enemy.element]?.obstacle;
        if (obstacleSkill) {
          command = {
            type: ACTION_TYPES.OBSTACLE,
            skill: obstacleSkill,
            target: randomTarget.id
          };
        }
      } else if (rand < 0.6 && enemy.element && enemy.stats.mp >= 25) {
        // 30% 概率使用法术攻击
        const magicSkill = ELEMENT_SKILLS[enemy.element]?.attack;
        if (magicSkill) {
          command = {
            type: ACTION_TYPES.MAGIC,
            skill: magicSkill,
            target: randomTarget.id
          };
        }
      }
      
      // 默认普通攻击
      if (!command) {
        command = {
          type: ACTION_TYPES.PHYSICAL,
          skill: { id: 'normal_attack', name: '普通攻击', power: 100, manaCost: 0 },
          target: randomTarget.id
        };
      }
      
      this.enemyCommands.set(enemy.id, command);
    });
  }

  /**
   * 执行物理攻击
   */
  executePhysicalAttack(attacker, command) {
    const targetId = command.target;
    const target = this.allUnits.find(u => u.id === targetId);
    
    if (!target || !target.isAlive) {
      this.addLog(`${attacker.name} 攻击失败，目标无效`, 'action');
      return { success: false, message: '目标无效' };
    }
    
    // 混乱状态：随机目标
    if (attacker.statusEffects.some(e => e.type === STATUS_TYPES.CHAOS)) {
      const allAlive = this.allUnits.filter(u => u.isAlive && u.id !== attacker.id);
      if (allAlive.length > 0) {
        const randomTarget = allAlive[Math.floor(Math.random() * allAlive.length)];
        this.addLog(`😵 ${attacker.name} 混乱中，攻击目标改为 ${randomTarget.name}`, 'status');
        command.target = randomTarget.id;
        return this.executePhysicalAttack(attacker, command);
      }
    }
    
    let damage = attacker.stats.attack + (command.skill?.power || 100);
    
    // 五行相克加成
    if (attacker.element && target.element) {
      const multiplier = this.getElementMultiplier(attacker.element, target.element);
      damage *= multiplier;
      
      if (multiplier > 1) {
        this.addLog(`🔥 五行相克！${attacker.element}克${target.element}，伤害提升`, 'element');
      }
    }
    
    // 防御减伤
    damage -= target.stats.defense;
    damage = Math.max(1, Math.floor(damage));
    
    // 防御状态减半
    if (target.defending) {
      damage = Math.floor(damage * 0.5);
      this.addLog(`🛡️ ${target.name} 处于防御状态，伤害减半`, 'defend');
    }
    
    // 造成伤害（不可变更新）
    target.stats = {
      ...target.stats,
      hp: Math.max(0, target.stats.hp - damage)
    };
    
    this.addLog(`⚔️ ${attacker.name} 攻击 ${target.name}，造成 ${damage} 点伤害`, 'action');
    
    // 检查击败
    if (target.stats.hp <= 0) {
      // 不可变更新 isAlive 状态
      Object.assign(target, { isAlive: false });
      this.addLog(`💀 ${target.name} 被击败！`, 'defeat');
    }
    
    // 唤醒昏睡目标
    if (target.statusEffects.some(e => e.type === STATUS_TYPES.SLEEP)) {
      target.statusEffects = target.statusEffects.filter(e => e.type !== STATUS_TYPES.SLEEP);
      this.addLog(`${target.name} 被攻击唤醒`, 'status');
    }
    
    return {
      success: true,
      damage,
      target: target.name,
      message: `造成 ${damage} 点伤害`
    };
  }

  /**
   * 执行障碍技能
   */
  executeObstacleSkill(caster, command) {
    const { skill, target: targetId } = command;
    const target = this.allUnits.find(u => u.id === targetId);
    
    if (!target || !target.isAlive) {
      return { success: false, message: '目标无效' };
    }
    
    // 扣除法力
    if (caster.stats.mp < skill.manaCost) {
      this.addLog(`${caster.name} 法力不足`, 'action');
      return { success: false, message: '法力不足' };
    }
    
    caster.stats.mp -= skill.manaCost;
    
    // 计算成功率（基于道行差异）
    const successRate = this.calculateObstacleSuccessRate(caster, target, skill);
    const success = Math.random() < successRate;
    
    if (success) {
      // 应用状态效果
      const duration = this.calculateEffectDuration(caster, target);
      this.applyStatusEffect(target, skill.statusEffect, duration);
      
      this.addLog(`✨ ${caster.name} 对 ${target.name} 施展 ${skill.name}，成功！`, 'obstacle');
      return {
        success: true,
        message: `${skill.name} 成功`,
        effect: skill.statusEffect,
        duration
      };
    } else {
      this.addLog(`💫 ${caster.name} 对 ${target.name} 施展 ${skill.name}，失败`, 'obstacle');
      return {
        success: true,
        message: `${skill.name} 失败`
      };
    }
  }

  /**
   * 计算障碍成功率
   */
  calculateObstacleSuccessRate(caster, target, skill) {
    const casterDaoXing = caster.stats.daoXing || 0;
    const targetDaoXing = target.stats.daoXing || 0;
    
    // 基础成功率50%
    let successRate = 0.5;
    
    // 道行差异影响（每点道行差异影响2%）
    const daoXingDiff = casterDaoXing - targetDaoXing;
    successRate += daoXingDiff * 0.02;
    
    // 等级差异影响
    const levelDiff = caster.level - target.level;
    successRate += levelDiff * 0.01;
    
    // 限制在5%-95%之间
    return Math.max(0.05, Math.min(0.95, successRate));
  }

  /**
   * 计算效果持续时间
   */
  calculateEffectDuration(caster, target) {
    const baseDuration = 3;
    const daoXingDiff = (caster.stats.daoXing || 0) - (target.stats.daoXing || 0);
    
    let duration = baseDuration + Math.floor(daoXingDiff / 20);
    return Math.max(1, Math.min(7, duration));
  }

  /**
   * 应用状态效果
   */
  applyStatusEffect(target, statusType, duration) {
    // 移除同类状态
    target.statusEffects = target.statusEffects.filter(e => e.type !== statusType);
    
    // 添加新状态
    target.statusEffects.push({
      type: statusType,
      duration: duration,
      remainingTurns: duration,
      ...STATUS_EFFECTS[statusType]
    });
  }

  /**
   * 获取五行克制倍率
   */
  getElementMultiplier(attackerElement, defenderElement) {
    if (!attackerElement || !defenderElement) return 1;
    
    // 相克关系：增加15%伤害
    if (ELEMENT_RELATIONS.overcome[attackerElement] === defenderElement) {
      return 1.15;
    }
    
    // 被克关系：减少15%伤害
    if (ELEMENT_RELATIONS.overcome[defenderElement] === attackerElement) {
      return 0.85;
    }
    
    return 1;
  }

  /**
   * 检查战斗是否结束
   */
  checkBattleEnd() {
    const playerAlive = this.playerTeam.some(u => u.isAlive);
    const enemyAlive = this.enemyTeam.some(u => u.isAlive);
    
    return !playerAlive || !enemyAlive;
  }

  /**
   * 验证指令有效性
   */
  validateCommand(unit, command) {
    if (!unit.isAlive) return false;
    
    // 检查法力消耗
    if (command.skill && command.skill.manaCost > unit.stats.mp) {
      return false;
    }
    
    // 检查遗忘状态
    if (unit.statusEffects.some(e => e.type === STATUS_TYPES.FORGET)) {
      return command.type === ACTION_TYPES.PHYSICAL;
    }
    
    return true;
  }

  /**
   * 获取行动名称
   */
  getActionName(command) {
    return command.skill?.name || command.type;
  }

  /**
   * 添加战斗日志
   */
  addLog(message, type = 'info') {
    this.battleLog.push({
      message,
      type,
      turn: this.turnCount,
      timestamp: Date.now()
    });
  }

  /**
   * 结束回合
   */
  endRound() {
    this.phase = BATTLE_PHASES.ROUND_END;
    
    // 处理状态效果
    this.processStatusEffects();
    
    // 清理指令
    this.playerCommands.clear();
    this.petCommands.clear();
    this.enemyCommands?.clear();
    
    // 重置防御状态
    this.allUnits.forEach(unit => {
      unit.defending = false;
    });
    
    this.turnCount++;
    
    // 检查回合限制
    if (this.turnCount > this.maxTurns) {
      this.phase = BATTLE_PHASES.BATTLE_END;
      this.battleResult = {
        victory: false,
        timeout: true,
        message: '战斗超时'
      };
      return { success: true, battleEnd: true, battleResult: this.battleResult };
    }
    
    // 进入下一回合
    this.phase = BATTLE_PHASES.PLAYER_COMMAND;
    
    return {
      success: true,
      nextRound: true,
      turnCount: this.turnCount,
      nextPhase: 'player_command'
    };
  }

  /**
   * 处理状态效果
   */
  processStatusEffects() {
    this.allUnits.forEach(unit => {
      if (!unit.isAlive) return;
      
      // 处理持续伤害
      const poison = unit.statusEffects.find(e => e.type === STATUS_TYPES.POISON);
      if (poison) {
        const damage = Math.floor(unit.stats.maxHp * 0.1);
        // 中毒伤害（不可变更新）
        unit.stats = {
          ...unit.stats,
          hp: Math.max(0, unit.stats.hp - damage)
        };
        this.addLog(`☠️ ${unit.name} 受到中毒伤害 ${damage}`, 'status');
        
        if (unit.stats.hp <= 0) {
          Object.assign(unit, { isAlive: false });
          this.addLog(`💀 ${unit.name} 中毒身亡！`, 'defeat');
        }
      }
      
      // 减少状态持续时间
      unit.statusEffects = unit.statusEffects.filter(effect => {
        effect.remainingTurns--;
        if (effect.remainingTurns <= 0) {
          this.addLog(`${unit.name} 的 ${effect.name} 效果消失`, 'status');
          return false;
        }
        return true;
      });
    });
  }

  /**
   * 生成战斗结果
   */
  generateBattleResult() {
    const playerAlive = this.playerTeam.some(u => u.isAlive);
    const enemyAlive = this.enemyTeam.some(u => u.isAlive);
    
    if (playerAlive && !enemyAlive) {
      return {
        victory: true,
        message: '胜利！',
        rewards: this.calculateRewards()
      };
    } else if (!playerAlive && enemyAlive) {
      return {
        victory: false,
        message: '败北...'
      };
    }
    
    return {
      victory: false,
      draw: true,
      message: '平局'
    };
  }

  /**
   * 计算奖励
   */
  calculateRewards() {
    const totalEnemyLevel = this.enemyTeam.reduce((sum, enemy) => sum + enemy.level, 0);
    const avgEnemyLevel = totalEnemyLevel / this.enemyTeam.length;
    const battleTurns = this.turnCount;
    
    // 基础奖励
    const baseExperience = totalEnemyLevel * 50;
    const baseGold = totalEnemyLevel * 20;
    
    // 道行经验计算：根据敌人等级、战斗回合数和胜利方式
    let daoXingExp = 0;
    
    // 基础道行经验
    daoXingExp += Math.floor(avgEnemyLevel * 2);
    
    // 战斗回合数影响（回合越少，道行经验越高）
    const turnsBonus = Math.max(1, Math.floor((30 - battleTurns) / 5));
    daoXingExp += turnsBonus;
    
    // 宠物参与奖励
    const hasPet = this.playerTeam.some(u => u.type === 'pet' && u.isAlive);
    if (hasPet) {
      daoXingExp += Math.floor(daoXingExp * 0.3); // 宠物参与增加30%道行经验
    }
    
    // 确保最小道行经验
    daoXingExp = Math.max(5, daoXingExp);
    
    return {
      experience: baseExperience,
      gold: baseGold,
      daoXingExp: daoXingExp,
      items: [], // TODO: 根据敌人配置添加掉落
      battleStats: {
        turns: battleTurns,
        hasPet: hasPet,
        enemyLevel: avgEnemyLevel
      }
    };
  }
}

// 导出单例
export const wendaoBattleManager = new WendaoBattleManager();