import React from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { closeModal, openModal, showToast } from '../../store/uiSlice';
import { equipItem, removeFromInventory } from '../../store/equipmentSlice';
import { 
  EQUIPMENT_QUALITY_NAMES,
  EQUIPMENT_SLOT_NAMES,
  ELEMENT_NAMES,
  ELEMENT_COLORS 
} from '../../utils/equipmentConstants';
import { calculateEquipmentPower } from '../../utils/equipmentLogic';
import Modal from '../UI/Modal';

function EquipmentDetailModal() {
  const dispatch = useDispatch();
  const { open, data } = useSelector(state => state.ui.modals.equipmentDetail);
  
  if (!open || !data?.equipment) return null;
  
  const equipment = data.equipment;
  const power = calculateEquipmentPower(equipment);

  const handleClose = () => {
    dispatch(closeModal({ modalName: 'equipmentDetail' }));
  };

  const handleEquip = () => {
    dispatch(equipItem({ slot: equipment.slot, equipment }));
    dispatch(showToast({ 
      message: `已装备 ${equipment.name}`, 
      type: 'success' 
    }));
    handleClose();
  };

  const handleUpgrade = () => {
    dispatch(openModal({
      modalName: 'equipmentUpgrade',
      data: { equipment }
    }));
    handleClose();
  };

  const handleDelete = () => {
    if (window.confirm('确定要删除这件装备吗？')) {
      dispatch(removeFromInventory({ id: equipment.id }));
      dispatch(showToast({ 
        message: `已删除 ${equipment.name}`, 
        type: 'info' 
      }));
      handleClose();
    }
  };

  return (
    <Modal
      isOpen={open}
      onClose={handleClose}
      title={`${equipment.name}`}
      size="small"
    >
      {/* 装备标题 */}
      <div style={{ textAlign: 'center', marginBottom: '0.75rem' }}>
        <div style={{ 
          fontSize: '1.5rem', 
          marginBottom: '0.25rem'
        }}>
          {equipment.icon}
        </div>
        <div style={{ 
          color: '#87CEEB', 
          fontSize: '0.6875rem',
          marginBottom: '0.125rem'
        }}>
          Lv.{equipment.level} {EQUIPMENT_QUALITY_NAMES[equipment.quality]}{EQUIPMENT_SLOT_NAMES[equipment.slot]}
        </div>
        <div style={{ 
          color: ELEMENT_COLORS[equipment.element], 
          fontSize: '0.625rem'
        }}>
          {ELEMENT_NAMES[equipment.element]}系 | 战力: {power}
        </div>
      </div>

      {/* 基础属性 */}
      <div style={{
        background: 'rgba(212, 175, 55, 0.1)',
        padding: '0.5rem',
        borderRadius: '0.25rem',
        marginBottom: '0.5rem',
        border: '1px solid rgba(212, 175, 55, 0.3)'
      }}>
        <div style={{ 
          color: '#FFD700', 
          fontSize: '0.6875rem',
          fontWeight: 'bold',
          marginBottom: '0.25rem'
        }}>
          基础属性
        </div>
        <div style={{ 
          color: '#87CEEB', 
          fontSize: '0.625rem',
          marginBottom: '0.125rem'
        }}>
          {equipment.baseStats.primary.name}: +{equipment.baseStats.primary.value}
        </div>
        <div style={{ 
          color: '#87CEEB', 
          fontSize: '0.625rem'
        }}>
          {equipment.baseStats.secondary.name}: +{equipment.baseStats.secondary.value}
        </div>
      </div>

      {/* 附加属性 */}
      {equipment.additionalStats && equipment.additionalStats.length > 0 && (
        <div style={{
          background: 'rgba(144, 238, 144, 0.1)',
          padding: '0.5rem',
          borderRadius: '0.25rem',
          marginBottom: '0.5rem',
          border: '1px solid rgba(144, 238, 144, 0.3)'
        }}>
          <div style={{ 
            color: '#90EE90', 
            fontSize: '0.6875rem',
            fontWeight: 'bold',
            marginBottom: '0.25rem'
          }}>
            附加属性
          </div>
          {equipment.additionalStats.map((stat, idx) => {
            const color = stat.quality === 'special' ? '#FFD700' : '#90EE90';
            return (
              <div key={idx} style={{ 
                color, 
                fontSize: '0.625rem',
                fontWeight: 'bold',
                marginBottom: '0.125rem'
              }}>
                {stat.quality === 'special' && '✨ '}{stat.name}: +{stat.value}
              </div>
            );
          })}
        </div>
      )}

      {/* 操作按钮 */}
      <div style={{ 
        display: 'flex', 
        flexWrap: 'wrap',
        gap: '0.375rem', 
        marginTop: '0.75rem' 
      }}>
        <button
          onClick={handleEquip}
          style={{
            flex: '1 1 auto',
            minWidth: '3.5rem',
            background: 'linear-gradient(135deg, #D4AF37 0%, #B8860B 100%)',
            color: '#000',
            border: 'none',
            padding: '0.375rem 0.75rem',
            borderRadius: '0.25rem',
            cursor: 'pointer',
            fontWeight: 'bold',
            fontSize: '0.6875rem'
          }}
        >
          装备
        </button>

        {equipment.quality !== 'green' && (
          <button
            onClick={handleUpgrade}
            style={{
              flex: '1 1 auto',
              minWidth: '3.5rem',
              background: 'linear-gradient(135deg, #28a745 0%, #155724 100%)',
              color: '#fff',
              border: 'none',
              padding: '0.375rem 0.75rem',
              borderRadius: '0.25rem',
              cursor: 'pointer',
              fontWeight: 'bold',
              fontSize: '0.6875rem'
            }}
          >
            升级
          </button>
        )}

        <button
          onClick={handleDelete}
          style={{
            flex: '0 1 auto',
            minWidth: '2.5rem',
            background: 'linear-gradient(135deg, #dc3545 0%, #721c24 100%)',
            color: '#fff',
            border: 'none',
            padding: '0.375rem 0.75rem',
            borderRadius: '0.25rem',
            cursor: 'pointer',
            fontWeight: 'bold',
            fontSize: '0.6875rem'
          }}
        >
          删除
        </button>
      </div>
    </Modal>
  );
}

export default EquipmentDetailModal;