import { createSlice } from '@reduxjs/toolkit';
import { battleManager, BATTLE_STATES, BATTLE_ACTIONS } from '../utils/battleLogic';

const initialState = {
  // 战斗状态
  isInBattle: false,
  battleState: BATTLE_STATES.IDLE,
  turnCount: 0,
  maxTurns: 20, // 最大回合数
  currentTurn: 'player', // 'player' | 'enemy'
  autoBattle: false, // 自动战斗模式
  
  // 战斗双方
  player: null,
  enemy: null,
  
  // 战斗日志
  battleLog: [],
  
  // UI状态
  showBattleUI: false,
  selectedAction: null,
  selectedSkill: null,
  animationPlaying: false,
  
  // 战斗结果
  battleResult: null, // { victory: boolean, rewards: {}, experience: number }
  showRewardModal: false,
  defeatedBoss: null
};

const battleSlice = createSlice({
  name: 'battle',
  initialState,
  reducers: {
    // 开始战斗
    startBattle: (state, action) => {
      const { playerData, enemyName } = action.payload;
      
      try {
        const battleData = battleManager.initializeBattle(playerData, enemyName);
        
        state.isInBattle = true;
        state.battleState = BATTLE_STATES.PLAYER_TURN;
        state.showBattleUI = true;
        state.turnCount = battleData.turnCount;
        state.currentTurn = 'player';
        state.player = battleData.player;
        state.enemy = battleData.enemy;
        state.battleLog = battleManager.battleLog;
        state.battleResult = null;
        state.selectedAction = null;
        state.selectedSkill = null;
        
        console.log(`[战斗] 开始挑战 ${enemyName}`);
      } catch (error) {
        console.error('[战斗] 初始化失败:', error);
      }
    },

    // 玩家执行动作
    playerAction: (state, action) => {
      if (state.battleState !== BATTLE_STATES.PLAYER_TURN) return;
      
      const result = battleManager.playerAction(action.payload);
      
      if (result.success) {
        // 更新战斗状态
        state.player = result.player;
        state.enemy = result.enemy;
        state.battleState = result.state;
        state.battleLog = [...battleManager.battleLog];
        
        // 检查回合数上限
        if (state.turnCount >= state.maxTurns && !result.battleEnd) {
          state.isInBattle = false;
          state.currentTurn = null;
          state.battleResult = {
            victory: false,
            timeout: true,
            rewards: {},
            experience: 0
          };
          battleManager.addLog(`⏰ 论剑已达${state.maxTurns}回合上限，平局收场`, 'system');
          state.battleLog = [...battleManager.battleLog];
          return;
        }
        
        if (result.battleEnd) {
          state.isInBattle = false;
          state.currentTurn = null;
          
          if (result.state === BATTLE_STATES.VICTORY) {
            state.battleResult = {
              victory: true,
              rewards: calculateRewards(state.enemy),
              experience: calculateExperience(state.enemy)
            };
          } else if (result.state === BATTLE_STATES.DEFEAT) {
            state.battleResult = {
              victory: false,
              rewards: {},
              experience: 0
            };
          } else if (result.state === BATTLE_STATES.FLED) {
            state.battleResult = {
              victory: false,
              fled: true,
              rewards: {},
              experience: 0
            };
          }
        } else {
          state.currentTurn = 'enemy';
        }
      }
    },

    // 敌人回合结果
    enemyTurnResult: (state, action) => {
      const result = action.payload;
      
      state.player = result.player;
      state.enemy = result.enemy;
      state.battleState = result.state;
      state.turnCount = result.turnCount;
      state.battleLog = [...battleManager.battleLog];
      
      if (result.battleEnd) {
        state.isInBattle = false;
        state.currentTurn = null;
        state.battleResult = {
          victory: false,
          rewards: {},
          experience: 0
        };
      } else {
        state.currentTurn = 'player';
      }
    },

    // 选择动作
    selectAction: (state, action) => {
      state.selectedAction = action.payload;
      state.selectedSkill = null; // 重置技能选择
    },

    // 选择技能
    selectSkill: (state, action) => {
      state.selectedSkill = action.payload;
    },

    // 设置动画状态
    setAnimation: (state, action) => {
      state.animationPlaying = action.payload;
    },

    // 设置奖励模态框
    setRewardModal: (state, action) => {
      state.showRewardModal = action.payload.show;
      if (action.payload.boss) {
        state.defeatedBoss = action.payload.boss;
      }
      if (action.payload.result) {
        state.battleResult = action.payload.result;
      }
    },

    // 结束战斗
    endBattle: (state) => {
      state.isInBattle = false;
      state.battleState = BATTLE_STATES.IDLE;
      state.showBattleUI = false;
      state.player = null;
      state.enemy = null;
      state.battleLog = [];
      state.battleResult = null;
      state.selectedAction = null;
      state.selectedSkill = null;
      state.currentTurn = null;
      state.turnCount = 0;
      state.showRewardModal = false;
      state.defeatedBoss = null;
      
      // 重置战斗管理器
      battleManager.state = BATTLE_STATES.IDLE;
      battleManager.player = null;
      battleManager.enemy = null;
      battleManager.turnCount = 0;
      battleManager.battleLog = [];
    },

    // 清理战斗结果
    clearBattleResult: (state) => {
      state.battleResult = null;
    },

    // 添加战斗日志
    addBattleLog: (state, action) => {
      state.battleLog.push({
        message: action.payload,
        timestamp: Date.now(),
        turn: state.turnCount
      });
    },

    // 切换自动战斗
    toggleAutoBattle: (state) => {
      state.autoBattle = !state.autoBattle;
    },

    // 设置自动战斗状态
    setAutoBattle: (state, action) => {
      state.autoBattle = action.payload;
    },

    // 自动玩家行动
    autoPlayerAction: (state) => {
      if (state.battleState !== BATTLE_STATES.PLAYER_TURN || !state.autoBattle) return;
      
      // 简单的AI逻辑：随机选择攻击或技能
      const actions = [
        { type: BATTLE_ACTIONS.ATTACK, skill: { name: '平斩', type: BATTLE_ACTIONS.ATTACK, power: 100, manaCost: 0 } },
        { type: BATTLE_ACTIONS.ATTACK, skill: { name: '重击', type: BATTLE_ACTIONS.ATTACK, power: 150, manaCost: 20 } },
        { type: BATTLE_ACTIONS.MAGIC, skill: { name: '雷符', type: BATTLE_ACTIONS.MAGIC, power: 130, manaCost: 30, element: 'metal' } }
      ];
      
      // 如果血量低于30%，有30%几率使用治疗
      if (state.player.currentHp < (state.player.stats?.hp || 1000) * 0.3 && Math.random() < 0.3) {
        actions.push({ type: BATTLE_ACTIONS.MAGIC, skill: { name: '回春术', type: BATTLE_ACTIONS.MAGIC, power: 120, manaCost: 25, heal: true } });
      }
      
      const randomAction = actions[Math.floor(Math.random() * actions.length)];
      const result = battleManager.playerAction(randomAction);
      
      if (result.success) {
        state.player = result.player;
        state.enemy = result.enemy;
        state.battleState = result.state;
        state.battleLog = [...battleManager.battleLog];
        
        // 检查回合数上限
        if (state.turnCount >= state.maxTurns && !result.battleEnd) {
          state.isInBattle = false;
          state.currentTurn = null;
          state.battleResult = {
            victory: false,
            timeout: true,
            rewards: {},
            experience: 0
          };
          battleManager.addLog(`⏰ 论剑已达${state.maxTurns}回合上限，平局收场`, 'system');
          state.battleLog = [...battleManager.battleLog];
          return;
        }
        
        if (result.battleEnd) {
          state.isInBattle = false;
          state.currentTurn = null;
          state.autoBattle = false; // 战斗结束时关闭自动模式
          
          if (result.state === BATTLE_STATES.VICTORY) {
            state.battleResult = {
              victory: true,
              rewards: calculateRewards(state.enemy),
              experience: calculateExperience(state.enemy)
            };
          } else if (result.state === BATTLE_STATES.DEFEAT) {
            state.battleResult = {
              victory: false,
              rewards: {},
              experience: 0
            };
          }
        } else {
          state.currentTurn = 'enemy';
        }
      }
    }
  }
});

// 计算战斗奖励
function calculateRewards(enemy) {
  const rewards = {
    experience: 0,
    gold: 0,
    items: []
  };
  
  // 基础奖励
  rewards.experience = enemy.level * 50;
  rewards.gold = enemy.level * 100;
  
  // 根据掉落配置计算奖励
  if (enemy.drops) {
    // 女娲石掉落
    if (enemy.drops.superStone) {
      const dropChance = enemy.drops.superStone * 100;
      if (Math.random() * 100 < dropChance) {
        rewards.items.push({
          name: '女娲石',
          quantity: Math.random() > 0.7 ? 2 : 1,
          type: 'material'
        });
      }
    }
    
    if (enemy.drops.normalStone) {
      const dropChance = enemy.drops.normalStone * 100;
      if (Math.random() * 100 < dropChance) {
        rewards.items.push({
          name: '普通石',
          quantity: Math.random() > 0.5 ? 2 : 1,
          type: 'material'
        });
      }
    }
    
    // 首饰掉落
    if (enemy.drops.jewelry) {
      const dropChance = enemy.drops.jewelry * 100;
      if (Math.random() * 100 < dropChance) {
        rewards.items.push({
          name: '首饰',
          level: enemy.level,
          type: 'jewelry'
        });
      }
    }
  }
  
  return rewards;
}

// 计算经验奖励
function calculateExperience(enemy) {
  return Math.floor(enemy.level * 25 + enemy.stats.maxHp / 100);
}

export const {
  startBattle,
  playerAction,
  enemyTurnResult,
  selectAction,
  selectSkill,
  setAnimation,
  setRewardModal,
  endBattle,
  clearBattleResult,
  addBattleLog,
  toggleAutoBattle,
  setAutoBattle,
  autoPlayerAction
} = battleSlice.actions;

export default battleSlice.reducer;