import React from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { removeFromRecast } from '../../store/jewelrySlice';
import JewelryIcon from './JewelryIcon';

function RecastSlots() {
  const dispatch = useDispatch();
  const recastSlots = useSelector(state => state.jewelry.recastSlots);
  const jewelry = useSelector(state => state.jewelry.items);

  const handleRemoveFromSlot = (slotIndex) => {
    dispatch(removeFromRecast({ slotIndex }));
  };

  return (
    <div className="recast-slots" style={{
      display: 'grid',
      gridTemplateColumns: 'repeat(3, 1fr)',
      gap: '12px',
      marginBottom: '20px',
      padding: '15px',
      background: 'rgba(0, 0, 0, 0.3)',
      border: '1px solid #D4AF37',
      borderRadius: '8px'
    }}>
      {recastSlots.map((jewelryIndex, index) => (
        <div
          key={index}
          className="recast-slot"
          style={{
            aspectRatio: '1 / 1',
            width: '100%',
            minHeight: '80px',
            background: jewelryIndex !== null ? 
              'linear-gradient(135deg, #4a4a4a 0%, #2a2a2a 100%)' : 
              'linear-gradient(135deg, #333 0%, #222 100%)',
            border: jewelryIndex !== null ? '2px solid #6B5B47' : '2px dashed #666',
            borderRadius: '8px',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            cursor: jewelryIndex !== null ? 'pointer' : 'default',
            transition: 'all 0.3s ease',
            padding: '8px',
            textAlign: 'center'
          }}
        >
          {jewelryIndex !== null ? (
            <RecastSlotContent 
              jewelryIndex={jewelryIndex} 
              jewelry={jewelry} 
              onRemove={() => handleRemoveFromSlot(index)}
            />
          ) : (
            <div style={{ color: '#999', fontSize: '9px' }}>
              {index === 0 ? '80-100级首饰' : '同类型同等级'}
            </div>
          )}
        </div>
      ))}
    </div>
  );
}

function RecastSlotContent({ jewelryIndex, jewelry, onRemove }) {
  const jewelryItem = jewelry[jewelryIndex];
  if (!jewelryItem) return <div style={{ color: '#ff0000' }}>错误</div>;
  
  const handleClick = (e) => {
    e.preventDefault();
    onRemove && onRemove();
  };
  
  return (
    <div 
      onClick={handleClick}
      style={{ 
        width: '100%', 
        height: '100%', 
        display: 'flex', 
        flexDirection: 'column', 
        alignItems: 'center', 
        justifyContent: 'center',
        transition: 'transform 0.3s ease',
        cursor: 'pointer'
      }}
      onMouseEnter={(e) => {
        e.currentTarget.style.transform = 'translateY(-2px)';
        e.currentTarget.style.boxShadow = '0 4px 12px rgba(107, 91, 71, 0.4)';
      }}
      onMouseLeave={(e) => {
        e.currentTarget.style.transform = 'translateY(0)';
        e.currentTarget.style.boxShadow = 'none';
      }}
      title={`${jewelryItem.name} Lv.${jewelryItem.level}`}
    >
      <div style={{ marginBottom: '4px' }}>
        <JewelryIcon type={jewelryItem.type} level={jewelryItem.level} />
      </div>
      <div style={{ color: '#FFD700', fontSize: '10px', fontWeight: 'bold' }}>
        {jewelryItem.name}
      </div>
      <div style={{ color: '#87CEEB', fontSize: '9px' }}>
        Lv.{jewelryItem.level}
      </div>
    </div>
  );
}

export default RecastSlots;