import { createSlice } from '@reduxjs/toolkit';
import { wendaoBattleManager, BATTLE_PHASES } from '../utils/wendaoBattleSystem';

const initialState = {
  // 战斗状态
  isActive: false,
  battleType: '1v1', // '1v1' | '3v3'
  phase: BATTLE_PHASES.PREPARATION,
  turnCount: 1,
  maxTurns: 30,
  
  // 战斗双方
  playerTeam: [],
  enemyTeam: [],
  
  // 当前执行状态
  currentExecutingUnit: null,
  actionQueue: [],
  
  // 战斗日志
  battleLog: [],
  
  // 用户交互状态
  selectedAction: null,
  selectedSkill: null,
  selectedTarget: null,
  awaitingPlayerCommand: false,
  awaitingPetCommand: false,
  
  // 战斗结果
  battleResult: null,
  
  // UI状态
  showBattleUI: false,
  animationPlaying: false,
};

const wendaoBattleSlice = createSlice({
  name: 'wendaoBattle',
  initialState,
  reducers: {
    // 开始战斗
    startBattle: (state, action) => {
      const { playerData, enemyData, petData, battleType = '1v1', battleMode = 'classic' } = action.payload;
      
      console.log('[战斗系统] startBattle reducer 被调用', { 
        playerData, 
        enemyData, 
        petData,
        battleType,
        battleMode 
      });
      
      try {
        // 设置战斗类型
        state.battleType = battleType;
        
        if (battleType === '3v3') {
          // 3v3战斗直接使用传入的队伍数据
          console.log('[战斗系统] 3v3战斗模式，直接使用队伍数据');
          
          state.isActive = true;
          state.showBattleUI = true;
          state.phase = 'player_command';
          state.playerTeam = Array.isArray(playerData) ? playerData : [playerData];
          state.enemyTeam = Array.isArray(enemyData) ? enemyData : [enemyData];
          state.turnCount = 1;
          state.battleLog = [`🏆 3v3团战开始！${state.playerTeam.length} vs ${state.enemyTeam.length}`];
          state.awaitingPlayerCommand = true;
          state.battleResult = null;
          
          console.log('[战斗系统] 3v3战斗初始化完成', {
            playerTeamCount: state.playerTeam.length,
            enemyTeamCount: state.enemyTeam.length,
            playerTeam: state.playerTeam,
            enemyTeam: state.enemyTeam
          });
        } else {
          // 1v1战斗使用原有逻辑
          console.log('[战斗系统] 1v1战斗模式，使用战斗管理器');
          const initResult = wendaoBattleManager.initBattle(playerData, enemyData, petData);
          
          console.log('[战斗系统] 初始化结果:', initResult);
          
          state.isActive = true;
          state.showBattleUI = true;
          state.phase = initResult.phase; // 应该是 'player_command'
          state.playerTeam = initResult.playerTeam;
          state.enemyTeam = initResult.enemyTeam;
          state.turnCount = initResult.turnCount;
          state.battleLog = [...wendaoBattleManager.battleLog];
          state.awaitingPlayerCommand = true; // 确保等待玩家指令
          state.battleResult = null;
        }
        
        // 同步战斗管理器阶段
        console.log('[战斗系统] 初始化完成', {
          reduxPhase: state.phase,
          managerPhase: wendaoBattleManager.phase,
          awaitingPlayerCommand: state.awaitingPlayerCommand
        });
        
        // 重置用户状态
        state.selectedAction = null;
        state.selectedSkill = null;
        state.selectedTarget = null;
        
        console.log('[战斗系统] 状态更新完成', {
          isActive: state.isActive,
          showBattleUI: state.showBattleUI,
          phase: state.phase,
          playerTeam: state.playerTeam,
          enemyTeam: state.enemyTeam
        });
      } catch (error) {
        console.error('[Battle System] 战斗初始化失败:', error);
      }
    },

    // 设置玩家指令
    setPlayerCommand: (state, action) => {
      const { unitId, command } = action.payload;
      
      console.log('[战斗系统] setPlayerCommand reducer 被调用', { unitId, command });
      
      const result = wendaoBattleManager.setPlayerCommand(unitId, command);
      
      console.log('[战斗系统] wendaoBattleManager.setPlayerCommand 结果', result);
      
      if (result.success) {
        // 同步战斗管理器的阶段
        state.phase = result.nextPhase || wendaoBattleManager.phase;
        state.awaitingPlayerCommand = false;
        state.awaitingPetCommand = result.nextPhase === 'pet_command';
        
        // 如果直接进入执行阶段
        if (result.nextPhase === 'execution') {
          state.actionQueue = result.actionQueue || [];
          console.log('[战斗系统] 进入执行阶段，行动队列:', state.actionQueue);
        }
        
        // 重置选择状态
        state.selectedAction = null;
        state.selectedSkill = null;
        state.selectedTarget = null;
        
        console.log('[战斗系统] 更新后的状态', {
          phase: state.phase,
          awaitingPlayerCommand: state.awaitingPlayerCommand,
          actionQueueLength: state.actionQueue?.length
        });
      } else {
        console.log('[战斗系统] setPlayerCommand 失败:', result.message);
      }
    },

    // 设置宠物指令
    setPetCommand: (state, action) => {
      const { unitId, command } = action.payload;
      
      const result = wendaoBattleManager.setPetCommand(unitId, command);
      
      if (result.success) {
        state.phase = result.nextPhase || state.phase;
        state.awaitingPetCommand = false;
        
        if (result.nextPhase === 'execution') {
          state.actionQueue = result.actionQueue || [];
        }
      }
    },

    // 开始执行阶段
    startExecution: (state) => {
      const result = wendaoBattleManager.startExecution();
      
      if (result.success) {
        state.phase = BATTLE_PHASES.EXECUTION;
        state.actionQueue = result.actionQueue;
        state.animationPlaying = true;
      }
    },

    // 执行下一个行动（安全的状态更新）
    executeNextAction: (state) => {
      try {
        const result = wendaoBattleManager.executeNextAction();
        
        if (result.success) {
          // 安全更新队伍状态
          if (wendaoBattleManager.playerTeam) {
            state.playerTeam = wendaoBattleManager.playerTeam.map(unit => ({
              ...unit,
              stats: { ...unit.stats },
              statusEffects: [...(unit.statusEffects || [])],
              isAlive: unit.isAlive
            }));
          }
          
          if (wendaoBattleManager.enemyTeam) {
            state.enemyTeam = wendaoBattleManager.enemyTeam.map(unit => ({
              ...unit,
              stats: { ...unit.stats },
              statusEffects: [...(unit.statusEffects || [])],
              isAlive: unit.isAlive
            }));
          }
          
          state.battleLog = [...wendaoBattleManager.battleLog];
          state.phase = wendaoBattleManager.phase;
          
          if (result.battleEnd) {
            // 战斗结束
            state.battleResult = result.battleResult;
            state.phase = BATTLE_PHASES.BATTLE_END;
            state.animationPlaying = false;
          } else if (!result.canContinue) {
            // 回合结束
            state.animationPlaying = false;
          }
        }
      } catch (error) {
        console.error('Execute action failed:', error);
        // 出错时重置状态
        state.animationPlaying = false;
      }
    },

    // 结束回合
    endRound: (state) => {
      const result = wendaoBattleManager.endRound();
      
      if (result.success) {
        state.playerTeam = [...wendaoBattleManager.playerTeam];
        state.enemyTeam = [...wendaoBattleManager.enemyTeam];
        state.battleLog = [...wendaoBattleManager.battleLog];
        
        if (result.battleEnd) {
          state.battleResult = result.battleResult;
          state.phase = BATTLE_PHASES.BATTLE_END;
        } else {
          state.phase = result.nextPhase || BATTLE_PHASES.PLAYER_COMMAND;
          state.turnCount = result.turnCount || state.turnCount;
          state.awaitingPlayerCommand = result.nextPhase === BATTLE_PHASES.PLAYER_COMMAND;
        }
      }
    },

    // UI 交互相关
    selectAction: (state, action) => {
      state.selectedAction = action.payload.actionType;
      state.selectedSkill = action.payload.skill;
    },

    selectTarget: (state, action) => {
      state.selectedTarget = action.payload;
    },

    clearSelection: (state) => {
      state.selectedAction = null;
      state.selectedSkill = null;
      state.selectedTarget = null;
    },

    // 设置动画状态
    setAnimation: (state, action) => {
      state.animationPlaying = action.payload;
    },

    // 结束战斗
    endBattle: (state) => {
      wendaoBattleManager.reset();
      
      return {
        ...initialState,
        showBattleUI: false
      };
    },

    // 清除战斗结果
    clearBattleResult: (state) => {
      state.battleResult = null;
    },

    // 更新战斗状态（用于手动同步）
    updateBattleState: (state) => {
      state.playerTeam = [...wendaoBattleManager.playerTeam];
      state.enemyTeam = [...wendaoBattleManager.enemyTeam];
      state.battleLog = [...wendaoBattleManager.battleLog];
      state.phase = wendaoBattleManager.phase;
      state.turnCount = wendaoBattleManager.turnCount;
    },

    // 显示/隐藏战斗UI
    showBattleUI: (state) => {
      state.showBattleUI = true;
    },

    hideBattleUI: (state) => {
      state.showBattleUI = false;
    }
  }
});

export const {
  startBattle,
  setPlayerCommand,
  setPetCommand,
  startExecution,
  executeNextAction,
  endRound,
  selectAction,
  selectTarget,
  clearSelection,
  setAnimation,
  endBattle,
  clearBattleResult,
  updateBattleState,
  showBattleUI,
  hideBattleUI
} = wendaoBattleSlice.actions;

export default wendaoBattleSlice.reducer;