import React, { useState, useEffect, useRef } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { endBattle } from '../../store/wendaoBattleSlice';
import { showToast } from '../../store/uiSlice';
import { addExperience, addGold, addDaoXingExp } from '../../store/characterSlice';
import soundEffects from '../../utils/soundEffects';

const ACTION_TYPES = {
  PHYSICAL: 'physical',
  MAGIC: 'magic',
  ESCAPE: 'escape'
};

function WendaoClassicBattleUI() {
  const dispatch = useDispatch();
  const wendaoBattle = useSelector(state => state.wendaoBattle);
  const character = useSelector(state => state.character);

  const [selectedSkill, setSelectedSkill] = useState(null);
  const [battleHP, setBattleHP] = useState({
    player: 1000,
    enemy: 1200
  });
  const [battleAnimations, setBattleAnimations] = useState({
    playerAttacking: false,
    playerCastingMagic: false,
    enemyAttacking: false,
    enemyCastingMagic: false
  });
  const [screenShake, setScreenShake] = useState(false);
  const [deathAnimations, setDeathAnimations] = useState({
    player: false,
    enemy: false
  });
  const [battleEnded, setBattleEnded] = useState(false);
  const [battleSpeed, setBattleSpeed] = useState(1);
  const [turnCount, setTurnCount] = useState(1);
  const [isPlayerTurn, setIsPlayerTurn] = useState(true); // 轮流攻击状态
  const battleEndedRef = useRef(false);
  const battleSpeedRef = useRef(1);

  const player = wendaoBattle.playerTeam?.[0];
  const enemy = wendaoBattle.enemyTeam?.[0];

  // 法术名称库
  const spellNames = {
    physical: ['破空斩', '裂石击', '疾风刃', '雷鸣斩', '烈火剑', '寒冰刺', '土石拳', '金刚击'],
    magic: ['天雷咒', '烈火术', '寒冰箭', '藤蔓缠', '金刚咒', '风刃术', '地震术', '雷电链', '火球术', '冰锥术']
  };

  const getRandomSpellName = (type) => {
    const spells = spellNames[type] || spellNames.physical;
    return spells[Math.floor(Math.random() * spells.length)];
  };

  // 技能按钮定义
  const skillButtons = [
    { 
      id: 'attack', 
      label: '攻击', 
      icon: '⚔️', 
      type: ACTION_TYPES.PHYSICAL,
      skill: { id: 'attack', name: '破空斩', type: ACTION_TYPES.PHYSICAL }
    },
    { 
      id: 'magic', 
      label: '法术', 
      icon: '✨', 
      type: ACTION_TYPES.MAGIC,
      skill: { id: 'magic', name: '天雷咒', type: ACTION_TYPES.MAGIC }
    }
  ];

  // 最大血量
  const maxHP = {
    player: player?.stats?.maxHp || player?.maxHp || 1000,
    enemy: enemy?.stats?.maxHp || enemy?.maxHp || 1200
  };

  // 初始化战斗血量
  useEffect(() => {
    setBattleHP({
      player: maxHP.player,
      enemy: maxHP.enemy
    });
    setBattleEnded(false);
    battleEndedRef.current = false;
    
    // 战斗开始音效和视觉效果
    soundEffects.playBattleStart?.();
    
    // 战斗开始提示
    setTimeout(() => {
      dispatch(showToast({ 
        message: `⚔️ 战斗开始！vs ${enemy?.name || '雷震子'}`, 
        type: 'info' 
      }));
    }, 500);
  }, [player, enemy, maxHP.player, maxHP.enemy]);

  // 创建震撼的普通攻击效果
  const createPhysicalAttackEffect = (casterType, targetType) => {
    const isPlayerAttack = casterType === 'player';
    const attackerPos = isPlayerAttack ? { top: '65%', left: '75%' } : { top: '25%', left: '25%' };
    const targetPos = isPlayerAttack ? { top: '25%', left: '25%' } : { top: '65%', left: '75%' };
    
    // 1. 攻击者前冲动画
    const attackerEffect = document.createElement('div');
    attackerEffect.style.cssText = `
      position: fixed;
      top: ${attackerPos.top};
      left: ${attackerPos.left};
      width: 60px;
      height: 60px;
      background: radial-gradient(circle, #FFD700, #FFA500, transparent);
      border-radius: 50%;
      z-index: 1600;
      pointer-events: none;
      box-shadow: 0 0 30px #FFD700;
      animation: physicalCharge 0.6s ease-out forwards;
    `;
    document.body.appendChild(attackerEffect);
    
    // 2. 冲击波动画
    setTimeout(() => {
      const shockWave = document.createElement('div');
      shockWave.style.cssText = `
        position: fixed;
        top: ${targetPos.top};
        left: ${targetPos.left};
        width: 20px;
        height: 20px;
        background: radial-gradient(circle, #FF6B6B, #FF4500, transparent);
        border-radius: 50%;
        z-index: 1700;
        pointer-events: none;
        transform: translate(-50%, -50%);
        animation: shockWaveExplosion 0.8s ease-out forwards;
      `;
      document.body.appendChild(shockWave);
      
      // 3. 多层冲击圈效果
      for (let i = 0; i < 3; i++) {
        setTimeout(() => {
          const ring = document.createElement('div');
          ring.style.cssText = `
            position: fixed;
            top: ${targetPos.top};
            left: ${targetPos.left};
            width: ${40 + i * 20}px;
            height: ${40 + i * 20}px;
            border: 3px solid #FF6B6B;
            border-radius: 50%;
            z-index: 1650;
            pointer-events: none;
            transform: translate(-50%, -50%);
            animation: ringExpansion ${0.6 + i * 0.2}s ease-out forwards;
            opacity: ${0.8 - i * 0.2};
          `;
          document.body.appendChild(ring);
          
          setTimeout(() => {
            if (ring.parentNode) ring.parentNode.removeChild(ring);
          }, (0.6 + i * 0.2) * 1000);
        }, i * 100);
      }
      
      setTimeout(() => {
        if (shockWave.parentNode) shockWave.parentNode.removeChild(shockWave);
      }, 800);
    }, 400);
    
    setTimeout(() => {
      if (attackerEffect.parentNode) attackerEffect.parentNode.removeChild(attackerEffect);
    }, 600);
  };

  // 创建绚丽的魔法攻击效果
  const createMagicAttackEffect = (casterType, targetType, spellName) => {
    const isPlayerCast = casterType === 'player';
    const casterPos = isPlayerCast ? { top: '65%', left: '75%' } : { top: '25%', left: '25%' };
    const targetPos = isPlayerCast ? { top: '25%', left: '25%' } : { top: '65%', left: '75%' };
    
    // 魔法颜色配置
    const getSpellColor = (spell) => {
      if (spell.includes('火') || spell.includes('烈')) return { primary: '#FF4500', secondary: '#FF6B6B' };
      if (spell.includes('冰') || spell.includes('寒')) return { primary: '#00BFFF', secondary: '#87CEEB' };
      if (spell.includes('雷') || spell.includes('电')) return { primary: '#9370DB', secondary: '#DDA0DD' };
      if (spell.includes('风') || spell.includes('刃')) return { primary: '#90EE90', secondary: '#98FB98' };
      if (spell.includes('土') || spell.includes('石')) return { primary: '#DEB887', secondary: '#F4A460' };
      return { primary: '#FFD700', secondary: '#FFA500' };
    };
    
    const colors = getSpellColor(spellName);
    
    // 1. 施法者魔法光环
    const casterAura = document.createElement('div');
    casterAura.style.cssText = `
      position: fixed;
      top: ${casterPos.top};
      left: ${casterPos.left};
      width: 80px;
      height: 80px;
      background: radial-gradient(circle, ${colors.primary}40, ${colors.secondary}20, transparent);
      border-radius: 50%;
      z-index: 1600;
      pointer-events: none;
      transform: translate(-50%, -50%);
      animation: magicAura 1.5s ease-in-out infinite;
      border: 2px solid ${colors.primary};
    `;
    document.body.appendChild(casterAura);
    
    // 2. 魔法弹道轨迹
    setTimeout(() => {
      const magicProjectile = document.createElement('div');
      magicProjectile.style.cssText = `
        position: fixed;
        top: ${casterPos.top};
        left: ${casterPos.left};
        width: 25px;
        height: 25px;
        background: radial-gradient(circle, ${colors.primary}, ${colors.secondary});
        border-radius: 50%;
        z-index: 1700;
        pointer-events: none;
        transform: translate(-50%, -50%);
        box-shadow: 0 0 20px ${colors.primary}, 0 0 40px ${colors.secondary};
        animation: magicProjectileFly 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards;
      `;
      
      // 动态设置终点位置
      const style = document.createElement('style');
      style.textContent = `
        @keyframes magicProjectileFly {
          0% {
            top: ${casterPos.top};
            left: ${casterPos.left};
            transform: translate(-50%, -50%) scale(1);
          }
          100% {
            top: ${targetPos.top};
            left: ${targetPos.left};
            transform: translate(-50%, -50%) scale(1.5);
          }
        }
      `;
      document.head.appendChild(style);
      document.body.appendChild(magicProjectile);
      
      // 3. 轨迹粒子效果
      const particleTrail = setInterval(() => {
        const particle = document.createElement('div');
        const rect = magicProjectile.getBoundingClientRect();
        particle.style.cssText = `
          position: fixed;
          top: ${rect.top + rect.height/2}px;
          left: ${rect.left + rect.width/2}px;
          width: 8px;
          height: 8px;
          background: ${colors.secondary};
          border-radius: 50%;
          z-index: 1650;
          pointer-events: none;
          animation: trailParticle 0.8s ease-out forwards;
        `;
        document.body.appendChild(particle);
        
        setTimeout(() => {
          if (particle.parentNode) particle.parentNode.removeChild(particle);
        }, 800);
      }, 50);
      
      // 4. 目标爆炸效果
      setTimeout(() => {
        clearInterval(particleTrail);
        
        // 主爆炸效果
        const explosion = document.createElement('div');
        explosion.style.cssText = `
          position: fixed;
          top: ${targetPos.top};
          left: ${targetPos.left};
          width: 30px;
          height: 30px;
          background: radial-gradient(circle, ${colors.primary}, ${colors.secondary}, transparent);
          border-radius: 50%;
          z-index: 1800;
          pointer-events: none;
          transform: translate(-50%, -50%);
          animation: magicExplosion 1.0s ease-out forwards;
        `;
        document.body.appendChild(explosion);
        
        // 爆炸粒子群
        for (let i = 0; i < 16; i++) {
          setTimeout(() => {
            const explosionParticle = document.createElement('div');
            const angle = (i / 16) * 360;
            explosionParticle.style.cssText = `
              position: fixed;
              top: ${targetPos.top};
              left: ${targetPos.left};
              width: 12px;
              height: 12px;
              background: radial-gradient(circle, ${colors.primary}, transparent);
              border-radius: 50%;
              z-index: 1750;
              pointer-events: none;
              transform: translate(-50%, -50%) rotate(${angle}deg);
              animation: explosionParticle 1.2s ease-out forwards;
            `;
            document.body.appendChild(explosionParticle);
            
            setTimeout(() => {
              if (explosionParticle.parentNode) explosionParticle.parentNode.removeChild(explosionParticle);
            }, 1200);
          }, i * 30);
        }
        
        setTimeout(() => {
          if (explosion.parentNode) explosion.parentNode.removeChild(explosion);
        }, 1000);
      }, 800);
      
      setTimeout(() => {
        if (magicProjectile.parentNode) magicProjectile.parentNode.removeChild(magicProjectile);
        if (style.parentNode) style.parentNode.removeChild(style);
      }, 800);
    }, 500);
    
    setTimeout(() => {
      if (casterAura.parentNode) casterAura.parentNode.removeChild(casterAura);
    }, 2000);
  };

  // 创建角色受击反馈
  const createHitFeedback = (targetType, damage, isCritical) => {
    const isPlayer = targetType === 'player';
    const targetPos = isPlayer ? { top: '65%', left: '75%' } : { top: '25%', left: '25%' };
    
    // 受击闪光效果
    const hitFlash = document.createElement('div');
    hitFlash.style.cssText = `
      position: fixed;
      top: ${targetPos.top};
      left: ${targetPos.left};
      width: 90px;
      height: 90px;
      background: radial-gradient(circle, ${isCritical ? '#FF0000' : '#FFFF00'}40, transparent);
      border-radius: 50%;
      z-index: 1900;
      pointer-events: none;
      transform: translate(-50%, -50%);
      animation: hitFlash 0.4s ease-out forwards;
    `;
    document.body.appendChild(hitFlash);
    
    // 受击震动效果（角色图片）
    const characterElement = document.querySelector(`[data-character="${targetType}"]`);
    if (characterElement) {
      characterElement.style.animation = isCritical ? 'characterCriticalHit 0.6s ease-out' : 'characterHit 0.3s ease-out';
      setTimeout(() => {
        characterElement.style.animation = '';
      }, isCritical ? 600 : 300);
    }
    
    setTimeout(() => {
      if (hitFlash.parentNode) hitFlash.parentNode.removeChild(hitFlash);
    }, 400);
  };

  // 执行战斗动作
  const executeBattleAction = async (attacker, target, skill) => {
    if (battleEndedRef.current) return;
    
    const casterType = attacker === player ? 'player' : 'enemy';
    const targetId = target === player ? 'player' : 'enemy';
    let spellName = skill?.name || getRandomSpellName(skill?.type === ACTION_TYPES.MAGIC ? 'magic' : 'physical');
    
    // 显示法术名称
    showSpellName(spellName, casterType);
    
    if (skill.type === ACTION_TYPES.PHYSICAL) {
      soundEffects.playPhysicalAttack();
      
      // 播放震撼的物理攻击动画
      createPhysicalAttackEffect(casterType, targetId);
      
      if (casterType === 'player') {
        setBattleAnimations(prev => ({ ...prev, playerAttacking: true }));
      } else {
        setBattleAnimations(prev => ({ ...prev, enemyAttacking: true }));
      }
      
      await new Promise(resolve => setTimeout(resolve, 1000));
      
      const damage = Math.floor(Math.random() * 100) + 50;
      const isCritical = Math.random() < 0.2;
      
      if (isCritical) {
        const criticalDamage = Math.floor(damage * 1.5);
        soundEffects.playCriticalHit();
        createHitFeedback(targetId, criticalDamage, true);
        reduceHP(targetId, criticalDamage);
        showDamage(criticalDamage, targetId, true);
        // 暴击震屏效果
        setScreenShake(true);
        setTimeout(() => setScreenShake(false), 300);
      } else {
        soundEffects.playTakeDamage();
        createHitFeedback(targetId, damage, false);
        reduceHP(targetId, damage);
        showDamage(damage, targetId, false);
      }
      
      setBattleAnimations(prev => ({ 
        ...prev, 
        playerAttacking: false, 
        enemyAttacking: false 
      }));
      
    } else if (skill.type === ACTION_TYPES.MAGIC) {
      soundEffects.playMagicAttack();
      
      // 播放绚丽的魔法攻击动画
      createMagicAttackEffect(casterType, targetId, spellName);
      
      if (casterType === 'player') {
        setBattleAnimations(prev => ({ ...prev, playerCastingMagic: true }));
      } else {
        setBattleAnimations(prev => ({ ...prev, enemyCastingMagic: true }));
      }
      
      await new Promise(resolve => setTimeout(resolve, 1800));
      
      const damage = Math.floor(Math.random() * 150) + 80;
      const isCritical = Math.random() < 0.15;
      
      if (isCritical) {
        const criticalDamage = Math.floor(damage * 1.8);
        soundEffects.playCriticalHit();
        createHitFeedback(targetId, criticalDamage, true);
        reduceHP(targetId, criticalDamage);
        showDamage(criticalDamage, targetId, true);
        // 法术暴击震屏效果
        setScreenShake(true);
        setTimeout(() => setScreenShake(false), 500);
      } else {
        soundEffects.playTakeDamage();
        createHitFeedback(targetId, damage, false);
        reduceHP(targetId, damage);
        showDamage(damage, targetId, false);
      }
      
      setBattleAnimations(prev => ({ 
        ...prev, 
        playerCastingMagic: false, 
        enemyCastingMagic: false 
      }));
    }
  };

  // 自动战斗逻辑
  useEffect(() => {
    if (battleEnded || battleEndedRef.current || !player || !enemy) return;

    const battleInterval = setInterval(() => {
      if (battleEndedRef.current) {
        clearInterval(battleInterval);
        return;
      }

      // 自动战斗：玩家和敌人轮流攻击
      const attacker = isPlayerTurn ? player : enemy;
      const defender = isPlayerTurn ? enemy : player;
      const skill = skillButtons[Math.floor(Math.random() * skillButtons.length)];

      executeBattleAction(attacker, defender, skill.skill, isPlayerTurn ? 'player' : 'enemy');
      
      // 切换回合
      setIsPlayerTurn(prev => !prev);
      setTurnCount(prev => prev + 1);
    }, Math.floor(2000 / battleSpeedRef.current));

    return () => clearInterval(battleInterval);
  }, [battleEnded, player, enemy, skillButtons, executeBattleAction, isPlayerTurn]);

  // 显示伤害数值
  const showDamage = (damage, targetType, isCritical = false) => {
    const damageDiv = document.createElement('div');
    damageDiv.textContent = isCritical ? `暴击! -${damage}` : `-${damage}`;
    
    // 根据目标位置确定显示位置
    const isPlayer = targetType === 'player';
    const topPosition = isPlayer ? '65%' : '25%'; // 在目标上方显示
    const leftPosition = isPlayer ? '75%' : '25%';
    
    damageDiv.style.cssText = `
      position: fixed;
      top: ${topPosition};
      left: ${leftPosition};
      transform: translate(-50%, -50%);
      color: ${isCritical ? '#FF0000' : '#FFD700'};
      font-size: ${isCritical ? '20px' : '16px'};
      font-weight: bold;
      text-shadow: 2px 2px 4px rgba(0,0,0,0.8);
      z-index: 2001;
      pointer-events: none;
      animation: damageFloat 1.5s ease-out forwards;
    `;
    
    document.body.appendChild(damageDiv);
    
    setTimeout(() => {
      if (damageDiv.parentNode) {
        damageDiv.parentNode.removeChild(damageDiv);
      }
    }, 1500);
  };

  // 显示法术名称
  const showSpellName = (spellName, casterType) => {
    const spellDiv = document.createElement('div');
    spellDiv.textContent = spellName;
    
    // 根据施法者位置确定显示位置
    const isPlayer = casterType === 'player';
    const topPosition = isPlayer ? '70%' : '20%'; // 玩家在下，敌人在上
    const leftPosition = isPlayer ? '80%' : '20%'; // 玩家在右，敌人在左
    
    spellDiv.style.cssText = `
      position: fixed;
      top: ${topPosition};
      left: ${leftPosition};
      transform: translate(-50%, -50%);
      color: ${isPlayer ? '#FFD700' : '#FF6B6B'};
      font-size: 24px;
      font-weight: bold;
      text-shadow: 2px 2px 4px rgba(0,0,0,0.8);
      z-index: 2000;
      pointer-events: none;
      animation: spellNameAppear 2s ease-out forwards;
      font-family: serif;
    `;
    
    document.body.appendChild(spellDiv);
    
    setTimeout(() => {
      if (spellDiv.parentNode) {
        spellDiv.parentNode.removeChild(spellDiv);
      }
    }, 2000);
  };

  // 创建法术特效
  const createMagicEffect = (casterType, spellName) => {
    const getEffectColor = (spell) => {
      if (spell.includes('雷') || spell.includes('电')) return '#FFD700';
      if (spell.includes('火') || spell.includes('烈')) return '#FF4500';
      if (spell.includes('冰') || spell.includes('寒')) return '#00BFFF';
      if (spell.includes('风') || spell.includes('刃')) return '#90EE90';
      if (spell.includes('土') || spell.includes('石')) return '#DEB887';
      return '#9370DB';
    };
    
    const effectColor = getEffectColor(spellName);
    
    // 创建粒子特效
    for (let layer = 0; layer < 3; layer++) {
      for (let i = 0; i < 12; i++) {
        const particle = document.createElement('div');
        const angle = (i / 12) * 360 + layer * 30;
        const distance = 60 + layer * 25;
        
        particle.style.cssText = `
          position: fixed;
          top: 50%;
          left: 50%;
          width: ${6 + layer * 2}px;
          height: ${6 + layer * 2}px;
          background: radial-gradient(circle, ${effectColor}, transparent);
          border-radius: 50%;
          pointer-events: none;
          z-index: 1500;
          box-shadow: 0 0 15px ${effectColor};
          animation: magicParticle${layer} ${1.2 + layer * 0.2}s ease-out forwards;
          transform: translate(-50%, -50%) rotate(${angle}deg) translateX(${distance}px);
        `;
        
        document.body.appendChild(particle);
        
        setTimeout(() => {
          if (particle.parentNode) {
            particle.parentNode.removeChild(particle);
          }
        }, (1.2 + layer * 0.2) * 1000);
      }
    }
  };

  // 减少HP
  const reduceHP = (targetId, damage) => {
    setBattleHP(prev => {
      const newHP = { ...prev };
      
      if (targetId === 'player') {
        newHP.player = Math.max(0, prev.player - damage);
        
        if (newHP.player <= 0 && prev.player > 0 && !battleEndedRef.current) {
          soundEffects.playBattleDefeat();
          soundEffects.playDeath();
          setBattleEnded(true);
          battleEndedRef.current = true;
          setDeathAnimations(prevAnim => ({ ...prevAnim, player: true }));
          setTimeout(() => {
            dispatch(showToast({ message: '战斗失败！你被敌人击败了！', type: 'error' }));
            setTimeout(() => {
              dispatch(endBattle());
            }, 1000);
          }, 1000);
        }
      } else if (targetId === 'enemy') {
        newHP.enemy = Math.max(0, prev.enemy - damage);
        
        if (newHP.enemy <= 0 && prev.enemy > 0 && !battleEndedRef.current) {
          soundEffects.playBattleVictory();
          setBattleEnded(true);
          battleEndedRef.current = true;
          setDeathAnimations(prevAnim => ({ ...prevAnim, enemy: true }));
          setTimeout(() => {
            const exp = 100 + Math.floor(Math.random() * 50);
            const gold = 50 + Math.floor(Math.random() * 30);
            const daoXingExp = 20 + Math.floor(Math.random() * 15);
            
            dispatch(addExperience(exp));
            dispatch(addGold(gold));
            dispatch(addDaoXingExp(daoXingExp));
            dispatch(showToast({ 
              message: `战斗胜利！获得经验${exp}，金币${gold}，道行经验${daoXingExp}`, 
              type: 'success' 
            }));
            setTimeout(() => {
              dispatch(endBattle());
            }, 1000);
          }, 1000);
        }
      }
      
      return newHP;
    });
  };

  // 技能选择处理
  const handleSkillSelect = (skill) => {
    soundEffects.playButtonClick();
    setSelectedSkill(skill);
  };

  // 目标选择处理
  const handleTargetSelect = async (target) => {
    if (!selectedSkill) return;
    
    soundEffects.playButtonClick();
    
    await executeBattleAction(player, target, selectedSkill.skill);
    setSelectedSkill(null);
    
    // AI反击
    setTimeout(async () => {
      if (!battleEndedRef.current) {
        const aiSkill = Math.random() > 0.5 
          ? skillButtons[0].skill 
          : skillButtons[1].skill;
        await executeBattleAction(enemy, player, aiSkill);
        setTurnCount(prev => prev + 1);
      }
    }, 500);
  };

  // 退出战斗
  const handleEndBattle = () => {
    soundEffects.playButtonClick();
    dispatch(endBattle());
  };

  if (!wendaoBattle.showBattleUI || !player || !enemy) return null;

  return (
    <div style={{
      position: 'fixed',
      top: 0,
      left: '50%',
      transform: `translateX(-50%) ${screenShake ? 'translateY(-2px)' : 'translateY(0)'}`,
      width: '100vw',
      maxWidth: '432px',
      height: '100vh',
      background: 'linear-gradient(135deg, #1a0f0a 0%, #2d1b0f 50%, #3d2817 100%)',
      zIndex: 1000,
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", "Roboto", sans-serif',
      color: '#ffffff',
      transition: screenShake ? 'none' : 'transform 0.3s ease',
      animation: screenShake ? 'battleShake 0.3s ease-in-out' : 'none'
    }}>
      {/* 顶部状态栏 */}
      <div style={{
        background: 'linear-gradient(135deg, #342016 0%, #4a2c1a 100%)',
        border: '1px solid rgba(212, 175, 55, 0.4)',
        borderRadius: '0 0 15px 15px',
        padding: window.innerWidth <= 768 ? '8px 12px' : '10px 15px',
        boxShadow: '0 2px 8px rgba(0, 0, 0, 0.3)',
        fontSize: window.innerWidth <= 768 ? '12px' : '14px',
        fontWeight: 'bold',
        minHeight: window.innerWidth <= 768 ? '44px' : '52px',
        borderBottom: '1px solid rgba(212, 175, 55, 0.3)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center'
      }}>
        <span>⚔️ 战斗中 - 第 {turnCount} 回合</span>
      </div>

      {/* 主战斗区域 - 专业斜对角布局 */}
      <div 
        style={{
          flex: 1,
          height: 'calc(100vh - 200px)',
          position: 'relative',
          padding: '20px'
        }}
      >
        {/* 敌人 - 左上角 */}
        <div 
          style={{
            position: 'absolute',
            top: '20px',
            left: '20px',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            cursor: 'default',
            transform: deathAnimations.enemy 
              ? 'scale(1) translateY(30px) rotateZ(-90deg)' 
              : 'scale(1)',
            transition: 'all 0.3s ease',
            opacity: deathAnimations.enemy ? 0.7 : 1,
            borderRadius: '10px',
            padding: '5px'
          }}
        >
          {/* 敌人头像 */}
          <div data-character="enemy" style={{
            width: '60px',
            height: '60px',
            borderRadius: '50%',
            background: 'linear-gradient(135deg, #6c757d, #495057)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontSize: '24px',
            marginBottom: '8px',
            border: '3px solid #DC143C',
            boxShadow: '0 4px 15px rgba(108, 117, 125, 0.5)',
            position: 'relative'
          }}>
            👹
            <div style={{
              position: 'absolute',
              bottom: '-5px',
              left: '-5px',
              background: '#8B0000',
              borderRadius: '50%',
              width: '20px',
              height: '20px',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              fontSize: '8px',
              fontWeight: 'bold',
              color: 'white'
            }}>
              {enemy?.level || 20}
            </div>
          </div>
          
          {/* 敌人信息 */}
          <div style={{
            background: 'rgba(139, 0, 0, 0.8)',
            borderRadius: '6px',
            padding: '6px 10px',
            minWidth: '100px',
            textAlign: 'center'
          }}>
            <div style={{ color: '#FFD700', fontSize: '10px', fontWeight: 'bold', marginBottom: '8px' }}>
              {enemy?.name || '雷震子'}
            </div>
            <div style={{
              background: 'rgba(255, 68, 68, 0.2)',
              borderRadius: '8px',
              height: '8px',
              position: 'relative',
              marginTop: '4px'
            }}>
              <div style={{
                background: 'linear-gradient(90deg, #FF4444, #FF6B6B)',
                height: '100%',
                width: `${Math.max(0, (battleHP.enemy || 0) / maxHP.enemy * 100)}%`,
                borderRadius: '8px',
                transition: 'width 1s ease-out'
              }} />
              <div style={{
                position: 'absolute',
                bottom: '-16px',
                left: '0',
                right: '0',
                fontSize: '8px',
                color: 'white',
                textAlign: 'center'
              }}>
                {battleHP.enemy || 0}/{maxHP.enemy}
              </div>
            </div>
          </div>
        </div>

        {/* VS标识 - 中央 */}
        <div style={{
          position: 'absolute',
          left: '50%',
          top: '45%',
          transform: 'translate(-50%, -50%)',
          background: selectedSkill 
            ? 'linear-gradient(135deg, #FFD700, #FFA500)' 
            : 'linear-gradient(135deg, #D4AF37, #B8860B)',
          borderRadius: '50%',
          width: '50px',
          height: '50px',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          fontSize: '14px',
          fontWeight: 'bold',
          color: '#000',
          boxShadow: selectedSkill 
            ? '0 5px 20px rgba(255, 215, 0, 0.8)' 
            : '0 5px 20px rgba(212, 175, 55, 0.5)',
          border: '3px solid #FFD700',
          transition: 'all 0.3s ease',
          zIndex: 10
        }}>
          VS
        </div>

        {/* 玩家 - 右下角 */}
        <div 
          style={{
            position: 'absolute',
            bottom: '20px',
            right: '20px',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            cursor: 'default',
            transform: deathAnimations.player 
              ? 'scale(1) translateY(30px) rotateZ(90deg)' 
              : 'scale(1)',
            transition: 'all 0.3s ease',
            opacity: deathAnimations.player ? 0.7 : 1,
            borderRadius: '10px',
            padding: '5px'
          }}
        >
          {/* 玩家头像 */}
          <div data-character="player" style={{
            width: '60px',
            height: '60px',
            borderRadius: '50%',
            background: 'linear-gradient(135deg, #4169E1, #32CD32)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontSize: '24px',
            marginBottom: '8px',
            border: '3px solid #32CD32',
            boxShadow: '0 4px 15px rgba(50, 205, 50, 0.5)',
            position: 'relative'
          }}>
            🧙‍♂️
            <div style={{
              position: 'absolute',
              bottom: '-5px',
              right: '-5px',
              background: '#FFD700',
              borderRadius: '50%',
              width: '20px',
              height: '20px',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              fontSize: '8px',
              fontWeight: 'bold',
              color: '#000'
            }}>
              {character.level || 1}
            </div>
          </div>
          
          {/* 玩家信息 */}
          <div style={{
            background: 'rgba(50, 205, 50, 0.8)',
            borderRadius: '6px',
            padding: '6px 10px',
            minWidth: '100px',
            textAlign: 'center'
          }}>
            <div style={{ color: '#FFD700', fontSize: '10px', fontWeight: 'bold', marginBottom: '8px' }}>
              玩家
            </div>
            <div style={{
              background: 'rgba(50, 205, 50, 0.2)',
              borderRadius: '8px',
              height: '8px',
              position: 'relative',
              marginTop: '4px'
            }}>
              <div style={{
                background: 'linear-gradient(90deg, #32CD32, #90EE90)',
                height: '100%',
                width: `${Math.max(0, (battleHP.player || 0) / maxHP.player * 100)}%`,
                borderRadius: '8px',
                transition: 'width 1s ease-out'
              }} />
              <div style={{
                position: 'absolute',
                bottom: '-16px',
                left: '0',
                right: '0',
                fontSize: '8px',
                color: 'white',
                textAlign: 'center'
              }}>
                {battleHP.player || 0}/{maxHP.player}
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* 底部操作区域 */}
      <div style={{
        position: 'absolute',
        bottom: '0',
        left: '0',
        right: '0',
        background: 'linear-gradient(135deg, #342016 0%, #4a2c1a 100%)',
        border: '1px solid rgba(212, 175, 55, 0.4)',
        borderRadius: '15px 15px 0 0',
        padding: '8px 10px',
        display: 'flex',
        flexDirection: 'column',
        gap: '8px',
        boxShadow: '0 -2px 15px rgba(0, 0, 0, 0.5)',
        zIndex: 1001,
        minHeight: '100px'
      }}>
        
        {/* 自动战斗状态显示 */}
        <div style={{
          textAlign: 'center',
          color: '#FFD700',
          fontSize: '14px',
          fontWeight: 'bold'
        }}>
          ⚡ 自动战斗中...
        </div>
        
        {/* 控制按钮区 */}
        <div style={{
          display: 'flex',
          gap: '8px',
          justifyContent: 'center'
        }}>
          <button
            onClick={() => {
              const newSpeed = battleSpeed >= 3 ? 1 : battleSpeed + 1;
              setBattleSpeed(newSpeed);
              battleSpeedRef.current = newSpeed;
              soundEffects.playButtonClick();
            }}
            style={{
              background: battleSpeed === 3 ? '#FFD700' : battleSpeed === 2 ? '#4169E1' : '#696969',
              border: '2px solid rgba(255, 255, 255, 0.2)',
              borderRadius: '20px',
              padding: '6px 12px',
              color: 'white',
              fontSize: '11px',
              fontWeight: 'bold',
              cursor: 'pointer',
              boxShadow: '0 4px 15px rgba(0,0,0,0.4)',
              minWidth: '60px',
              transition: 'all 0.3s ease'
            }}
          >
            ⚡ {battleSpeed}x
          </button>
          
          <button
            onClick={handleEndBattle}
            style={{
              background: 'linear-gradient(135deg, #DC143C 0%, #B22222 100%)',
              border: '2px solid rgba(255, 255, 255, 0.2)',
              borderRadius: '20px',
              padding: '6px 12px',
              color: 'white',
              fontSize: '11px',
              fontWeight: 'bold',
              cursor: 'pointer',
              boxShadow: '0 4px 15px rgba(0,0,0,0.4)',
              minWidth: '60px',
              transition: 'all 0.3s ease'
            }}
          >
            🚪 退出
          </button>
        </div>
      </div>

      {/* CSS动画 */}
      <style>{`
        @keyframes spellNameAppear {
          0% { 
            opacity: 0;
            transform: translate(-50%, -50%) scale(0.5) rotateY(90deg);
            filter: blur(10px);
          }
          20% { 
            opacity: 1;
            transform: translate(-50%, -50%) scale(1.3) rotateY(0deg);
            filter: blur(0px);
          }
          80% { 
            opacity: 1;
            transform: translate(-50%, -50%) scale(1.1) rotateY(0deg);
            filter: blur(0px);
          }
          100% { 
            opacity: 0;
            transform: translate(-50%, -50%) scale(0.8) rotateY(-90deg);
            filter: blur(5px);
          }
        }
        
        @keyframes magicParticle0 {
          0% { 
            opacity: 0;
            transform: translate(-50%, -50%) scale(0) rotate(0deg) translateX(0px);
          }
          50% { 
            opacity: 1;
            transform: translate(-50%, -50%) scale(1.5) rotate(180deg) translateX(60px);
          }
          100% { 
            opacity: 0;
            transform: translate(-50%, -50%) scale(0.5) rotate(360deg) translateX(120px);
          }
        }
        
        @keyframes magicParticle1 {
          0% { 
            opacity: 0;
            transform: translate(-50%, -50%) scale(0) rotate(30deg) translateX(0px);
          }
          60% { 
            opacity: 1;
            transform: translate(-50%, -50%) scale(1.8) rotate(210deg) translateX(85px);
          }
          100% { 
            opacity: 0;
            transform: translate(-50%, -50%) scale(0.3) rotate(390deg) translateX(150px);
          }
        }
        
        @keyframes magicParticle2 {
          0% { 
            opacity: 0;
            transform: translate(-50%, -50%) scale(0) rotate(60deg) translateX(0px);
          }
          70% { 
            opacity: 1;
            transform: translate(-50%, -50%) scale(2) rotate(240deg) translateX(110px);
          }
          100% { 
            opacity: 0;
            transform: translate(-50%, -50%) scale(0.2) rotate(420deg) translateX(180px);
          }
        }
        
        @keyframes battleShake {
          0%, 100% { transform: translateX(-50%) translateY(0); }
          25% { transform: translateX(-50%) translateY(-3px); }
          75% { transform: translateX(-50%) translateY(3px); }
        }
        
        @keyframes damageFloat {
          0% { 
            opacity: 1; 
            transform: translate(-50%, -50%) scale(1.2); 
          }
          50% { 
            opacity: 1; 
            transform: translate(-50%, -70px) scale(1); 
          }
          100% { 
            opacity: 0; 
            transform: translate(-50%, -100px) scale(0.8); 
          }
        }
        
        /* 商业级战斗动画效果 */
        @keyframes physicalCharge {
          0% { 
            transform: translate(-50%, -50%) scale(1);
            opacity: 0.8;
          }
          50% { 
            transform: translate(-50%, -50%) scale(1.5);
            opacity: 1;
            box-shadow: 0 0 50px #FFD700;
          }
          100% { 
            transform: translate(-50%, -50%) scale(2);
            opacity: 0;
            box-shadow: 0 0 80px #FFA500;
          }
        }
        
        @keyframes shockWaveExplosion {
          0% { 
            transform: translate(-50%, -50%) scale(0);
            opacity: 1;
          }
          50% { 
            transform: translate(-50%, -50%) scale(3);
            opacity: 0.8;
            box-shadow: 0 0 60px #FF6B6B;
          }
          100% { 
            transform: translate(-50%, -50%) scale(6);
            opacity: 0;
            box-shadow: 0 0 100px #FF4500;
          }
        }
        
        @keyframes ringExpansion {
          0% { 
            transform: translate(-50%, -50%) scale(0);
            opacity: 1;
          }
          100% { 
            transform: translate(-50%, -50%) scale(4);
            opacity: 0;
          }
        }
        
        @keyframes magicAura {
          0%, 100% { 
            transform: translate(-50%, -50%) scale(1) rotate(0deg);
            opacity: 0.8;
          }
          50% { 
            transform: translate(-50%, -50%) scale(1.3) rotate(180deg);
            opacity: 1;
          }
        }
        
        @keyframes magicExplosion {
          0% { 
            transform: translate(-50%, -50%) scale(1);
            opacity: 1;
          }
          30% { 
            transform: translate(-50%, -50%) scale(2.5);
            opacity: 0.9;
          }
          100% { 
            transform: translate(-50%, -50%) scale(5);
            opacity: 0;
          }
        }
        
        @keyframes explosionParticle {
          0% { 
            transform: translate(-50%, -50%) rotate(0deg) translateX(0) scale(1);
            opacity: 1;
          }
          100% { 
            transform: translate(-50%, -50%) rotate(360deg) translateX(100px) scale(0);
            opacity: 0;
          }
        }
        
        @keyframes trailParticle {
          0% { 
            opacity: 1;
            transform: scale(1);
          }
          100% { 
            opacity: 0;
            transform: scale(0.3) translateY(-20px);
          }
        }
        
        @keyframes hitFlash {
          0% { 
            transform: translate(-50%, -50%) scale(0);
            opacity: 1;
          }
          30% { 
            transform: translate(-50%, -50%) scale(1.2);
            opacity: 0.9;
          }
          100% { 
            transform: translate(-50%, -50%) scale(0.5);
            opacity: 0;
          }
        }
        
        @keyframes characterHit {
          0%, 100% { transform: translateX(0); }
          25% { transform: translateX(-8px) scale(0.95); }
          75% { transform: translateX(8px) scale(0.95); }
        }
        
        @keyframes characterCriticalHit {
          0%, 100% { 
            transform: translateX(0) scale(1);
            filter: brightness(1);
          }
          10% { 
            transform: translateX(-12px) scale(0.9);
            filter: brightness(1.5) hue-rotate(0deg);
          }
          30% { 
            transform: translateX(12px) scale(0.9);
            filter: brightness(2) hue-rotate(30deg);
          }
          50% { 
            transform: translateX(-8px) scale(0.95);
            filter: brightness(1.8) hue-rotate(60deg);
          }
          70% { 
            transform: translateX(8px) scale(0.95);
            filter: brightness(1.3) hue-rotate(30deg);
          }
        }
      `}</style>
    </div>
  );
}

export default WendaoClassicBattleUI;