import React from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { removeFromSynthesis, fixDataCorruption, clearSynthesisSlots } from '../../store/jewelrySlice';
import { openModal, showToast } from '../../store/uiSlice';
import JewelryIcon from './JewelryIcon';
import SuperStoneIcon from './SuperStoneIcon';
import { useLongPress } from '../../hooks/useMobile';
import './SuperStoneIcon.css';

function SynthesisSlots() {
  const dispatch = useDispatch();
  const synthesisSlots = useSelector(state => state.jewelry.synthesisSlots);
  const jewelry = useSelector(state => state.jewelry.items);

  const handleRemoveFromSlot = (slotIndex) => {
    dispatch(removeFromSynthesis({ slotIndex }));
  };

  const handleViewJewelryDetail = (jewelryItem, jewelryIndex) => {
    dispatch(openModal({
      modalName: 'jewelryDetail',
      data: { jewelry: jewelryItem, index: jewelryIndex }
    }));
  };

  // 检查是否有数据异常
  const hasCorruptedSlots = synthesisSlots.some(slot => {
    if (!slot || slot.type !== 'jewelry') return false;
    const jewelryItem = jewelry[slot.index];
    return !jewelryItem; // 首饰不存在说明数据异常
  });

  // 应急修复函数
  const handleEmergencyFix = () => {
    dispatch(fixDataCorruption());
    dispatch(showToast({ message: '已清理异常槽位！', type: 'success' }));
  };

  // 清空所有槽位
  const handleClearAll = () => {
    dispatch(clearSynthesisSlots());
    dispatch(showToast({ message: '已清空所有合成槽！', type: 'success' }));
  };

  return (
    <div>
      <div className="synthesis-slots" style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(3, minmax(80px, 1fr))',
        gap: '0.75rem',
        marginBottom: '1.25rem',
        padding: '0.9375rem',
        background: 'rgba(0, 0, 0, 0.3)',
        border: '1px solid #D4AF37',
        borderRadius: '8px'
      }}>
      {synthesisSlots.map((slot, index) => (
        <div
          key={index}
          className="synthesis-slot"
          style={{
            aspectRatio: '1 / 1',
            width: '100%',
            minHeight: '80px',
            background: slot ? 
              'linear-gradient(135deg, #4a4a4a 0%, #2a2a2a 100%)' : 
              'linear-gradient(135deg, #333 0%, #222 100%)',
            border: slot ? '2px solid #6B5B47' : '2px dashed #666',
            borderRadius: '8px',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            cursor: slot ? 'pointer' : 'default',
            transition: 'all 0.3s ease',
            padding: '0.5rem',
            textAlign: 'center'
          }}
        >
          {slot ? (
            <SynthesisSlotContent 
              slot={slot} 
              jewelry={jewelry} 
              onViewDetail={handleViewJewelryDetail}
              onRemove={() => handleRemoveFromSlot(index)}
            />
          ) : (
            <div style={{ color: '#999', fontSize: '9px' }}>
              放入首饰
            </div>
          )}
        </div>
      ))}
      </div>
      
      {/* 数据异常时显示修复按钮 */}
      {hasCorruptedSlots && (
        <div style={{
          marginTop: '8px',
          padding: '8px',
          background: 'rgba(255, 107, 107, 0.1)',
          border: '1px solid #FF6B6B',
          borderRadius: '4px',
          textAlign: 'center'
        }}>
          <div style={{ color: '#FF6B6B', fontSize: '11px', marginBottom: '6px' }}>
            ⚠️ 检测到异常数据，部分槽位包含无效引用
          </div>
          <div style={{ display: 'flex', gap: '8px', justifyContent: 'center' }}>
            <button
              onClick={handleEmergencyFix}
              style={{
                padding: '4px 8px',
                fontSize: '10px',
                background: 'linear-gradient(135deg, #FF6B6B 0%, #FF5252 100%)',
                color: 'white',
                border: 'none',
                borderRadius: '3px',
                cursor: 'pointer',
                fontWeight: 'bold'
              }}
            >
              🔧 修复异常
            </button>
            <button
              onClick={handleClearAll}
              style={{
                padding: '4px 8px',
                fontSize: '10px',
                background: 'linear-gradient(135deg, #666 0%, #555 100%)',
                color: 'white',
                border: 'none',
                borderRadius: '3px',
                cursor: 'pointer',
                fontWeight: 'bold'
              }}
            >
              🗑️ 清空槽位
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

function SynthesisSlotContent({ slot, jewelry, onViewDetail, onRemove }) {
  // Move hook to top level to avoid conditional calls
  const longPressHandlers = useLongPress(
    () => {
      if (slot.type === 'jewelry') {
        const jewelryItem = jewelry[slot.index];
        if (jewelryItem) {
          onViewDetail(jewelryItem, slot.index);
        }
      }
    }
  );

  const handleClick = (e) => {
    e.preventDefault();
    onRemove && onRemove();
  };

  if (slot.type === 'jewelry') {
    const jewelryItem = jewelry[slot.index];
    if (!jewelryItem) return <div style={{ color: '#ff0000' }}>错误</div>;
    
    return (
      <div 
        {...longPressHandlers}
        onClick={handleClick}
        style={{ 
          width: '100%', 
          height: '100%', 
          display: 'flex', 
          flexDirection: 'column', 
          alignItems: 'center', 
          justifyContent: 'center',
          transition: 'transform 0.3s ease',
          cursor: 'pointer'
        }}
        onMouseEnter={(e) => {
          e.currentTarget.style.transform = 'translateY(-2px)';
          e.currentTarget.style.boxShadow = '0 4px 12px rgba(107, 91, 71, 0.4)';
        }}
        onMouseLeave={(e) => {
          e.currentTarget.style.transform = 'translateY(0)';
          e.currentTarget.style.boxShadow = 'none';
        }}
        title={`${jewelryItem.name} Lv.${jewelryItem.level}`}
      >
        <div style={{ marginBottom: '0.25rem' }}>
          <JewelryIcon type={jewelryItem.type} level={jewelryItem.level} />
        </div>
        <div style={{ color: '#FFD700', fontSize: '0.625rem', fontWeight: 'bold' }}>
          {jewelryItem.name}
        </div>
        <div style={{ color: '#87CEEB', fontSize: '0.5625rem' }}>
          Lv.{jewelryItem.level}
        </div>
      </div>
    );
  } else if (slot.type === 'superStone') {
    return (
      <div 
        onClick={handleClick}
        style={{ 
          width: '100%', 
          height: '100%', 
          display: 'flex', 
          flexDirection: 'column', 
          alignItems: 'center', 
          justifyContent: 'center',
          transition: 'transform 0.3s ease',
          cursor: 'pointer',
          position: 'relative'
        }}
        onMouseEnter={(e) => {
          e.currentTarget.style.transform = 'translateY(-2px)';
          e.currentTarget.style.boxShadow = '0 4px 12px rgba(107, 91, 71, 0.4)';
        }}
        onMouseLeave={(e) => {
          e.currentTarget.style.transform = 'translateY(0)';
          e.currentTarget.style.boxShadow = 'none';
        }}
        title="女娲石 - 点击移除"
      >
        <div style={{ marginBottom: '0.25rem' }}>
          <SuperStoneIcon size="large" className="sparkle" />
        </div>
        <div style={{ color: '#9370db', fontSize: '0.625rem', fontWeight: 'bold' }}>
          女娲石
        </div>
        
        {/* 数量显示在右上角 */}
        <div style={{
          position: 'absolute',
          top: '2px',
          right: '2px',
          background: '#9370DB',
          color: '#fff',
          borderRadius: '50%',
          width: '16px',
          height: '16px',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          fontSize: '8px',
          fontWeight: 'bold'
        }}>
          {slot.count}
        </div>
      </div>
    );
  }
  
  return null;
}

export default SynthesisSlots;