import React, { useEffect } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import {
  initializeDefaultPets,
  setActivePet,
  clearActivePet,
  removePet,
  feedPet,
  addPet
} from '../../store/petSlice';
import { addSystemLog, showToast } from '../../store/uiSlice';

function PetManagementPanel() {
  const dispatch = useDispatch();
  const pets = useSelector(state => state.pets);

  // 初始化默认宠物
  useEffect(() => {
    dispatch(initializeDefaultPets());
  }, [dispatch]);

  // 获取宠物类型配置
  const getPetTypeConfig = (petTypeId) => {
    return pets.petTypes.find(type => type.id === petTypeId);
  };

  // 设置出战宠物
  const handleSetActivePet = (petId) => {
    const pet = pets.pets.find(p => p.id === petId);
    if (pet) {
      dispatch(setActivePet(petId));
      dispatch(addSystemLog({ message: `${pet.name} 开始出战` }));
      dispatch(showToast({ message: `${pet.name} 开始出战`, type: 'success' }));
    }
  };

  // 取消出战
  const handleClearActivePet = () => {
    dispatch(clearActivePet());
    dispatch(addSystemLog({ message: '宠物回到休息状态' }));
    dispatch(showToast({ message: '宠物回到休息状态', type: 'normal' }));
  };

  // 喂食宠物
  const handleFeedPet = (petId) => {
    const pet = pets.pets.find(p => p.id === petId);
    if (pet) {
      dispatch(feedPet(petId));
      dispatch(addSystemLog({ message: `给 ${pet.name} 喂食，忠诚度和经验增加` }));
      dispatch(showToast({ message: `${pet.name} 忠诚度+5, 经验+20`, type: 'success' }));
    }
  };

  // 放生宠物
  const handleReleasePet = (petId) => {
    const pet = pets.pets.find(p => p.id === petId);
    if (pet && window.confirm(`确定要放生 ${pet.name} 吗？`)) {
      dispatch(removePet(petId));
      dispatch(addSystemLog({ message: `放生了 ${pet.name}` }));
      dispatch(showToast({ message: `已放生 ${pet.name}`, type: 'normal' }));
    }
  };

  // 捕获新宠物（演示功能）
  const handleCapturePet = () => {
    const availableTypes = pets.petTypes;
    const randomType = availableTypes[Math.floor(Math.random() * availableTypes.length)];
    
    const newPetData = {
      ...randomType,
      level: Math.floor(Math.random() * 10) + 1,
      baseStats: { ...randomType.baseStats }
    };
    
    dispatch(addPet(newPetData));
    dispatch(addSystemLog({ message: `捕获了新宠物：${randomType.name}` }));
    dispatch(showToast({ message: `捕获成功！获得 ${randomType.name}`, type: 'success' }));
  };

  // 获取元素颜色
  const getElementColor = (element) => {
    const colors = {
      金: '#FFD700',
      木: '#90EE90',
      水: '#87CEEB',
      火: '#FF6347',
      土: '#DEB887'
    };
    return colors[element] || '#F4E4BC';
  };

  // 获取稀有度颜色
  const getRarityColor = (rarity) => {
    const colors = {
      common: '#F4E4BC',
      uncommon: '#90EE90',
      rare: '#87CEEB',
      epic: '#DA70D6',
      legendary: '#FFD700'
    };
    return colors[rarity] || '#F4E4BC';
  };

  // 获取稀有度文本
  const getRarityText = (rarity) => {
    const texts = {
      common: '普通',
      uncommon: '优秀',
      rare: '精良',
      epic: '史诗',
      legendary: '传说'
    };
    return texts[rarity] || '普通';
  };

  return (
    <div className="pet-management-panel" style={{
      background: 'rgba(0,0,0,0.3)',
      border: '1px solid #D4AF37',
      borderRadius: '8px',
      padding: '15px',
      margin: '10px 0'
    }}>
      <div style={{
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        marginBottom: '15px'
      }}>
        <h4 style={{
          color: '#D4AF37',
          margin: 0,
          fontSize: '16px',
          fontWeight: 'bold'
        }}>
          🐾 宠物管理 ({pets.pets.length}/10)
        </h4>
        
        <button
          onClick={handleCapturePet}
          style={{
            background: 'linear-gradient(135deg, #32CD32, #228B22)',
            border: 'none',
            borderRadius: '6px',
            padding: '8px 16px',
            color: '#fff',
            fontSize: '12px',
            fontWeight: 'bold',
            cursor: 'pointer'
          }}
        >
          🎣 捕获宠物
        </button>
      </div>

      {/* 出战宠物状态 */}
      {pets.activePetId && (
        <div style={{
          background: 'linear-gradient(135deg, rgba(144, 238, 144, 0.2), rgba(60, 179, 113, 0.2))',
          border: '1px solid #90EE90',
          borderRadius: '6px',
          padding: '10px',
          marginBottom: '15px'
        }}>
          <div style={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center'
          }}>
            <span style={{ color: '#90EE90', fontSize: '12px', fontWeight: 'bold' }}>
              ⚔️ 当前出战宠物
            </span>
            <button
              onClick={handleClearActivePet}
              style={{
                background: 'rgba(220, 20, 60, 0.6)',
                border: 'none',
                borderRadius: '4px',
                padding: '4px 8px',
                color: '#fff',
                fontSize: '10px',
                cursor: 'pointer'
              }}
            >
              休息
            </button>
          </div>
          {(() => {
            const activePet = pets.pets.find(p => p.id === pets.activePetId);
            return activePet && (
              <div style={{ color: '#F4E4BC', fontSize: '11px', marginTop: '5px' }}>
                {activePet.name} (等级{activePet.level}) - 忠诚度: {activePet.loyalty}
              </div>
            );
          })()}
        </div>
      )}

      {/* 宠物列表 */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
        gap: '10px',
        maxHeight: '400px',
        overflowY: 'auto'
      }}>
        {pets.pets.length === 0 ? (
          <div style={{
            textAlign: 'center',
            color: '#F4E4BC',
            fontSize: '14px',
            padding: '20px',
            gridColumn: '1 / -1'
          }}>
            还没有宠物，点击"捕获宠物"获得第一只宠物吧！
          </div>
        ) : (
          pets.pets.map(pet => (
            <div
              key={pet.id}
              style={{
                background: pet.isActive 
                  ? 'linear-gradient(135deg, rgba(144, 238, 144, 0.3), rgba(60, 179, 113, 0.3))'
                  : 'linear-gradient(135deg, rgba(60, 60, 60, 0.3), rgba(40, 40, 40, 0.3))',
                border: pet.isActive ? '2px solid #90EE90' : '1px solid #666',
                borderRadius: '8px',
                padding: '10px'
              }}
            >
              {/* 宠物头部信息 */}
              <div style={{
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
                marginBottom: '8px'
              }}>
                <div>
                  <div style={{ 
                    color: getRarityColor(pet.rarity), 
                    fontSize: '12px', 
                    fontWeight: 'bold' 
                  }}>
                    {pet.name}
                  </div>
                  <div style={{
                    color: getElementColor(pet.element),
                    fontSize: '10px',
                    marginTop: '2px'
                  }}>
                    [{pet.element}系] {getRarityText(pet.rarity)}
                  </div>
                </div>
                <div style={{
                  textAlign: 'right',
                  color: '#F4E4BC',
                  fontSize: '10px'
                }}>
                  等级 {pet.level}
                  <br />
                  经验 {pet.experience}/{ pet.level * 100}
                </div>
              </div>

              {/* 宠物属性 */}
              <div style={{
                display: 'grid',
                gridTemplateColumns: 'repeat(2, 1fr)',
                gap: '4px',
                fontSize: '9px',
                color: '#F4E4BC',
                marginBottom: '8px'
              }}>
                <div>攻击: {pet.currentStats.attack}</div>
                <div>防御: {pet.currentStats.defense}</div>
                <div>气血: {pet.currentStats.hp}</div>
                <div>法力: {pet.currentStats.mp}</div>
                <div>速度: {pet.currentStats.speed}</div>
                <div style={{ color: pet.loyalty > 70 ? '#90EE90' : pet.loyalty > 40 ? '#FFD700' : '#FF6347' }}>
                  忠诚: {pet.loyalty}
                </div>
              </div>

              {/* 宠物技能 */}
              <div style={{ marginBottom: '8px' }}>
                <div style={{ fontSize: '9px', color: '#87CEEB', marginBottom: '4px' }}>技能:</div>
                <div style={{
                  display: 'flex',
                  flexWrap: 'wrap',
                  gap: '2px'
                }}>
                  {pet.skills && pet.skills.map(skillId => {
                    const skill = pets.petSkills[skillId];
                    return skill && (
                      <span
                        key={skillId}
                        style={{
                          background: 'rgba(135, 206, 235, 0.2)',
                          border: '1px solid #87CEEB',
                          borderRadius: '3px',
                          padding: '2px 4px',
                          fontSize: '8px',
                          color: '#87CEEB'
                        }}
                      >
                        {skill.name}
                      </span>
                    );
                  })}
                </div>
              </div>

              {/* 操作按钮 */}
              <div style={{
                display: 'flex',
                gap: '4px'
              }}>
                {!pet.isActive ? (
                  <button
                    onClick={() => handleSetActivePet(pet.id)}
                    style={{
                      background: 'linear-gradient(135deg, #4169E1, #1E90FF)',
                      border: 'none',
                      borderRadius: '4px',
                      padding: '6px 10px',
                      color: '#fff',
                      fontSize: '10px',
                      fontWeight: 'bold',
                      cursor: 'pointer',
                      flex: 1
                    }}
                  >
                    出战
                  </button>
                ) : (
                  <div style={{
                    background: 'rgba(144, 238, 144, 0.3)',
                    border: '1px solid #90EE90',
                    borderRadius: '4px',
                    padding: '6px 10px',
                    color: '#90EE90',
                    fontSize: '10px',
                    textAlign: 'center',
                    flex: 1
                  }}>
                    出战中
                  </div>
                )}
                
                <button
                  onClick={() => handleFeedPet(pet.id)}
                  style={{
                    background: 'linear-gradient(135deg, #FFD700, #FFA500)',
                    border: 'none',
                    borderRadius: '4px',
                    padding: '6px 8px',
                    color: '#2F4F4F',
                    fontSize: '10px',
                    fontWeight: 'bold',
                    cursor: 'pointer'
                  }}
                >
                  🍖
                </button>
                
                <button
                  onClick={() => handleReleasePet(pet.id)}
                  disabled={pet.isActive}
                  style={{
                    background: pet.isActive 
                      ? 'rgba(60, 60, 60, 0.5)' 
                      : 'linear-gradient(135deg, #DC143C, #B22222)',
                    border: 'none',
                    borderRadius: '4px',
                    padding: '6px 8px',
                    color: pet.isActive ? '#888' : '#fff',
                    fontSize: '10px',
                    cursor: pet.isActive ? 'not-allowed' : 'pointer'
                  }}
                >
                  🚪
                </button>
              </div>
            </div>
          ))
        )}
      </div>

      {/* 宠物系统说明 */}
      <div style={{
        marginTop: '15px',
        fontSize: '10px',
        color: '#F4E4BC',
        opacity: 0.7,
        textAlign: 'center',
        borderTop: '1px solid #666',
        paddingTop: '10px'
      }}>
        💡 提示：宠物可参与战斗，忠诚度影响执行指令成功率，喂食可提升忠诚度和经验
      </div>
    </div>
  );
}

export default PetManagementPanel;