import { configureStore } from '@reduxjs/toolkit';
import characterSlice from './characterSlice';
import jewelrySlice from './jewelrySlice';
import equipmentSlice from './equipmentSlice';
import uiSlice from './uiSlice';
import battleSlice from './battleSlice';
import wendaoBattleSlice from './wendaoBattleSlice';
import petSlice from './petSlice';

export const store = configureStore({
  reducer: {
    character: characterSlice,
    jewelry: jewelrySlice,
    equipment: equipmentSlice,
    ui: uiSlice,
    battle: battleSlice,
    wendaoBattle: wendaoBattleSlice,
    pets: petSlice,
  },
  middleware: (getDefaultMiddleware) =>
    getDefaultMiddleware({
      serializableCheck: {
        ignoredActions: ['persist/PERSIST'],
      },
    }),
});

