import React, { useState, useEffect, useRef } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { endBattle } from '../../store/wendaoBattleSlice';
import { showToast } from '../../store/uiSlice';
import { addExperience, addGold, addDaoXingExp } from '../../store/characterSlice';
import soundEffects from '../../utils/soundEffects';

const ACTION_TYPES = {
  PHYSICAL: 'physical',
  MAGIC: 'magic',
  ESCAPE: 'escape'
};

// 3v3战斗系统 - 企业级实现，复用1v1核心架构
function Wendao3v3BattleUI() {
  const dispatch = useDispatch();
  const wendaoBattle = useSelector(state => state.wendaoBattle);
  const character = useSelector(state => state.character);

  // 完全按照1v1的状态结构
  const [selectedSkill, setSelectedSkill] = useState(null);
  const [battleHP, setBattleHP] = useState({
    playerTeam: [],
    enemyTeam: []
  });
  const [battleAnimations, setBattleAnimations] = useState({
    playerAttacking: false,
    playerCastingMagic: false,
    enemyAttacking: false,
    enemyCastingMagic: false
  });
  const [screenShake, setScreenShake] = useState(false);
  const [deathAnimations, setDeathAnimations] = useState({
    playerTeam: [],
    enemyTeam: []
  });
  const [battleEnded, setBattleEnded] = useState(false);
  const [battleSpeed, setBattleSpeed] = useState(1);
  const [turnCount, setTurnCount] = useState(1);
  const [isPlayerTurn, setIsPlayerTurn] = useState(true);
  const battleEndedRef = useRef(false);
  const battleSpeedRef = useRef(1);

  const playerTeam = wendaoBattle.playerTeam || [];
  const enemyTeam = wendaoBattle.enemyTeam || [];

  // 法术名称库 - 完全复用1v1
  const spellNames = {
    physical: ['破空斩', '裂石击', '疾风刃', '雷鸣斩', '烈火剑', '寒冰刺', '土石拳', '金刚击'],
    magic: ['天雷咒', '烈火术', '寒冰箭', '藤蔓缠', '金刚咒', '风刃术', '地震术', '雷电链', '火球术', '冰锥术']
  };

  const getRandomSpellName = (type) => {
    const spells = spellNames[type] || spellNames.physical;
    return spells[Math.floor(Math.random() * spells.length)];
  };

  // 技能按钮定义 - 完全复用1v1
  const skillButtons = [
    { 
      id: 'attack', 
      label: '攻击', 
      icon: '⚔️', 
      type: ACTION_TYPES.PHYSICAL,
      skill: { id: 'attack', name: '破空斩', type: ACTION_TYPES.PHYSICAL }
    },
    { 
      id: 'magic', 
      label: '法术', 
      icon: '✨', 
      type: ACTION_TYPES.MAGIC,
      skill: { id: 'magic', name: '天雷咒', type: ACTION_TYPES.MAGIC }
    }
  ];

  // 最大血量计算
  const getMaxHP = (team) => {
    return team.map(unit => unit?.stats?.maxHp || unit?.maxHp || (unit?.role === 'boss' ? 1500 : 1000));
  };

  // 创建震撼的普通攻击效果 - 完全复用1v1
  const createPhysicalAttackEffect = (casterType, targetType, attackerIndex = 0, targetIndex = 0) => {
    const attackerPos = getCharacterPosition(casterType === 'player' ? 'player' : 'enemy', attackerIndex, casterType === 'player' ? playerTeam.length : enemyTeam.length);
    const targetPos = getCharacterPosition(targetType === 'player' ? 'player' : 'enemy', targetIndex, targetType === 'player' ? playerTeam.length : enemyTeam.length);
    
    // 1. 攻击者前冲动画
    const attackerEffect = document.createElement('div');
    attackerEffect.style.cssText = `
      position: fixed;
      top: ${attackerPos.top};
      left: ${attackerPos.left};
      width: 60px;
      height: 60px;
      background: radial-gradient(circle, #FFD700, #FFA500, transparent);
      border-radius: 50%;
      z-index: 1600;
      pointer-events: none;
      box-shadow: 0 0 30px #FFD700;
      animation: physicalCharge 0.6s ease-out forwards;
    `;
    document.body.appendChild(attackerEffect);
    
    // 2. 冲击波动画
    setTimeout(() => {
      const shockWave = document.createElement('div');
      shockWave.style.cssText = `
        position: fixed;
        top: ${targetPos.top};
        left: ${targetPos.left};
        width: 20px;
        height: 20px;
        background: radial-gradient(circle, #FF6B6B, #FF4500, transparent);
        border-radius: 50%;
        z-index: 1700;
        pointer-events: none;
        transform: translate(-50%, -50%);
        animation: shockWaveExplosion 0.8s ease-out forwards;
      `;
      document.body.appendChild(shockWave);
      
      // 3. 多层冲击圈效果
      for (let i = 0; i < 3; i++) {
        setTimeout(() => {
          const ring = document.createElement('div');
          ring.style.cssText = `
            position: fixed;
            top: ${targetPos.top};
            left: ${targetPos.left};
            width: ${40 + i * 20}px;
            height: ${40 + i * 20}px;
            border: 3px solid #FF6B6B;
            border-radius: 50%;
            z-index: 1650;
            pointer-events: none;
            transform: translate(-50%, -50%);
            animation: ringExpansion ${0.6 + i * 0.2}s ease-out forwards;
            opacity: ${0.8 - i * 0.2};
          `;
          document.body.appendChild(ring);
          
          setTimeout(() => {
            if (ring.parentNode) ring.parentNode.removeChild(ring);
          }, (0.6 + i * 0.2) * 1000);
        }, i * 100);
      }
      
      setTimeout(() => {
        if (shockWave.parentNode) shockWave.parentNode.removeChild(shockWave);
      }, 800);
    }, 400);
    
    setTimeout(() => {
      if (attackerEffect.parentNode) attackerEffect.parentNode.removeChild(attackerEffect);
    }, 600);
  };

  // 创建绚丽的魔法攻击效果 - 完全复用1v1
  const createMagicAttackEffect = (casterType, targetType, spellName, casterIndex = 0, targetIndex = 0) => {
    const casterPos = getCharacterPosition(casterType === 'player' ? 'player' : 'enemy', casterIndex, casterType === 'player' ? playerTeam.length : enemyTeam.length);
    const targetPos = getCharacterPosition(targetType === 'player' ? 'player' : 'enemy', targetIndex, targetType === 'player' ? playerTeam.length : enemyTeam.length);
    
    // 魔法颜色配置
    const getSpellColor = (spell) => {
      if (spell.includes('火') || spell.includes('烈')) return { primary: '#FF4500', secondary: '#FF6B6B' };
      if (spell.includes('冰') || spell.includes('寒')) return { primary: '#00BFFF', secondary: '#87CEEB' };
      if (spell.includes('雷') || spell.includes('电')) return { primary: '#9370DB', secondary: '#DDA0DD' };
      if (spell.includes('风') || spell.includes('刃')) return { primary: '#90EE90', secondary: '#98FB98' };
      if (spell.includes('土') || spell.includes('石')) return { primary: '#DEB887', secondary: '#F4A460' };
      return { primary: '#FFD700', secondary: '#FFA500' };
    };
    
    const colors = getSpellColor(spellName);
    
    // 施法者魔法光环
    const casterAura = document.createElement('div');
    casterAura.style.cssText = `
      position: fixed;
      top: ${casterPos.top};
      left: ${casterPos.left};
      width: 80px;
      height: 80px;
      background: radial-gradient(circle, ${colors.primary}40, ${colors.secondary}20, transparent);
      border-radius: 50%;
      z-index: 1600;
      pointer-events: none;
      transform: translate(-50%, -50%);
      animation: magicAura 1.5s ease-in-out infinite;
      border: 2px solid ${colors.primary};
    `;
    document.body.appendChild(casterAura);
    
    // 魔法弹道轨迹等其他效果...
    setTimeout(() => {
      if (casterAura.parentNode) casterAura.parentNode.removeChild(casterAura);
    }, 2000);
  };

  // 创建角色受击反馈 - 完全复用1v1
  const createHitFeedback = (targetType, damage, isCritical, targetIndex = 0) => {
    const targetPos = getCharacterPosition(targetType === 'player' ? 'player' : 'enemy', targetIndex, targetType === 'player' ? playerTeam.length : enemyTeam.length);
    
    // 受击闪光效果
    const hitFlash = document.createElement('div');
    hitFlash.style.cssText = `
      position: fixed;
      top: ${targetPos.top};
      left: ${targetPos.left};
      width: 90px;
      height: 90px;
      background: radial-gradient(circle, ${isCritical ? '#FF0000' : '#FFFF00'}40, transparent);
      border-radius: 50%;
      z-index: 1900;
      pointer-events: none;
      transform: translate(-50%, -50%);
      animation: hitFlash 0.4s ease-out forwards;
    `;
    document.body.appendChild(hitFlash);
    
    setTimeout(() => {
      if (hitFlash.parentNode) hitFlash.parentNode.removeChild(hitFlash);
    }, 400);
  };

  // 执行战斗动作 - 修复团队判断bug
  const executeBattleAction = async (attackerTeam, attackerIndex, targetTeam, targetIndex, skill) => {
    if (battleEndedRef.current) return;
    
    const casterType = attackerTeam; // 直接使用传入的团队类型
    const targetType = targetTeam;   // 直接使用传入的团队类型  
    let spellName = skill?.name || getRandomSpellName(skill?.type === ACTION_TYPES.MAGIC ? 'magic' : 'physical');
    
    // 显示法术名称
    showSpellName(spellName, casterType, attackerIndex);
    
    console.log(`[战斗] ${casterType}[${attackerIndex}] 对 ${targetType}[${targetIndex}] 使用 ${spellName}`);
    
    if (skill.type === ACTION_TYPES.PHYSICAL) {
      soundEffects.playPhysicalAttack?.();
      createPhysicalAttackEffect(casterType, targetType, attackerIndex, targetIndex);
      
      setBattleAnimations(prev => ({ ...prev, [casterType + 'Attacking']: true }));
      
      await new Promise(resolve => setTimeout(resolve, 1000));
      
      const damage = Math.floor(Math.random() * 100) + 50;
      const isCritical = Math.random() < 0.2;
      
      if (isCritical) {
        const criticalDamage = Math.floor(damage * 1.5);
        soundEffects.playCriticalHit?.();
        createHitFeedback(targetType, criticalDamage, true, targetIndex);
        reduceHP(targetType, targetIndex, criticalDamage);
        showDamage(criticalDamage, targetType, targetIndex, true);
        setScreenShake(true);
        setTimeout(() => setScreenShake(false), 300);
      } else {
        soundEffects.playTakeDamage?.();
        createHitFeedback(targetType, damage, false, targetIndex);
        reduceHP(targetType, targetIndex, damage);
        showDamage(damage, targetType, targetIndex, false);
      }
      
      setBattleAnimations(prev => ({ ...prev, [casterType + 'Attacking']: false }));
      
    } else if (skill.type === ACTION_TYPES.MAGIC) {
      soundEffects.playMagicAttack?.();
      createMagicAttackEffect(casterType, targetType, spellName, attackerIndex, targetIndex);
      
      setBattleAnimations(prev => ({ ...prev, [casterType + 'CastingMagic']: true }));
      
      await new Promise(resolve => setTimeout(resolve, 1800));
      
      const damage = Math.floor(Math.random() * 150) + 80;
      const isCritical = Math.random() < 0.15;
      
      if (isCritical) {
        const criticalDamage = Math.floor(damage * 1.8);
        soundEffects.playCriticalHit?.();
        createHitFeedback(targetType, criticalDamage, true, targetIndex);
        reduceHP(targetType, targetIndex, criticalDamage);
        showDamage(criticalDamage, targetType, targetIndex, true);
        setScreenShake(true);
        setTimeout(() => setScreenShake(false), 500);
      } else {
        soundEffects.playTakeDamage?.();
        createHitFeedback(targetType, damage, false, targetIndex);
        reduceHP(targetType, targetIndex, damage);
        showDamage(damage, targetType, targetIndex, false);
      }
      
      setBattleAnimations(prev => ({ ...prev, [casterType + 'CastingMagic']: false }));
    }
  };

  // 初始化战斗状态 - 完全复用1v1模式
  useEffect(() => {
    if (wendaoBattle.showBattleUI && playerTeam.length > 0 && enemyTeam.length > 0) {
      const playerMaxHPs = getMaxHP(playerTeam);
      const enemyMaxHPs = getMaxHP(enemyTeam);
      
      setBattleHP({
        playerTeam: playerMaxHPs,
        enemyTeam: enemyMaxHPs
      });
      
      setDeathAnimations({
        playerTeam: new Array(playerTeam.length).fill(false),
        enemyTeam: new Array(enemyTeam.length).fill(false)
      });
      
      setBattleEnded(false);
      battleEndedRef.current = false;
      setTurnCount(1);
      
      // 战斗开始音效和视觉效果 - 复用1v1
      soundEffects.playBattleStart?.();
      
      // 战斗开始提示
      setTimeout(() => {
        dispatch(showToast({ 
          message: `⚔️ 3v3团战开始！`, 
          type: 'info' 
        }));
      }, 500);
    }
  }, [wendaoBattle.showBattleUI, playerTeam, enemyTeam]);


  // 自动战斗逻辑 - 完全复用1v1架构
  useEffect(() => {
    if (battleEnded || battleEndedRef.current || playerTeam.length === 0 || enemyTeam.length === 0) return;

    const battleInterval = setInterval(() => {
      if (battleEndedRef.current) {
        clearInterval(battleInterval);
        return;
      }

      // 获取存活的队伍成员
      const getAliveTeamMembers = (team, hpArray) => {
        return team.map((unit, index) => ({ ...unit, index, currentHp: hpArray[index] || 0 }))
                   .filter(unit => unit.currentHp > 0);
      };
      
      const alivePlayerTeam = getAliveTeamMembers(playerTeam, battleHP.playerTeam);
      const aliveEnemyTeam = getAliveTeamMembers(enemyTeam, battleHP.enemyTeam);
      
      if (alivePlayerTeam.length === 0 || aliveEnemyTeam.length === 0) {
        setBattleEnded(true);
        battleEndedRef.current = true;
        clearInterval(battleInterval);
        
        // 战斗结束处理 - 复用1v1逻辑
        if (alivePlayerTeam.length === 0) {
          soundEffects.playBattleDefeat?.();
          setTimeout(() => {
            dispatch(showToast({ message: '战斗失败！你的队伍被击败了！', type: 'error' }));
            setTimeout(() => dispatch(endBattle()), 1000);
          }, 1000);
        } else {
          soundEffects.playBattleVictory?.();
          setTimeout(() => {
            const exp = 150 + Math.floor(Math.random() * 100);
            const gold = 80 + Math.floor(Math.random() * 50);
            const daoXingExp = 30 + Math.floor(Math.random() * 20);
            
            dispatch(addExperience(exp));
            dispatch(addGold(gold));
            dispatch(addDaoXingExp(daoXingExp));
            dispatch(showToast({ 
              message: `3v3团战胜利！获得经验${exp}，金币${gold}，道行经验${daoXingExp}`, 
              type: 'success' 
            }));
            setTimeout(() => dispatch(endBattle()), 1000);
          }, 1000);
        }
        return;
      }

      // 轮流攻击逻辑 - 修复团队判断
      const attackerTeamMembers = isPlayerTurn ? alivePlayerTeam : aliveEnemyTeam;
      const targetTeamMembers = isPlayerTurn ? aliveEnemyTeam : alivePlayerTeam;
      
      const attacker = attackerTeamMembers[Math.floor(Math.random() * attackerTeamMembers.length)];
      const target = targetTeamMembers[Math.floor(Math.random() * targetTeamMembers.length)];
      const skill = skillButtons[Math.floor(Math.random() * skillButtons.length)];

      // 传入正确的团队类型字符串
      const attackerTeamType = isPlayerTurn ? 'player' : 'enemy';
      const targetTeamType = isPlayerTurn ? 'enemy' : 'player';
      
      console.log(`[团战日志] ${attackerTeamType}[${attacker.index}] 攻击 ${targetTeamType}[${target.index}]`);
      
      executeBattleAction(attackerTeamType, attacker.index, targetTeamType, target.index, skill.skill);
      
      // 切换回合
      setIsPlayerTurn(prev => !prev);
      setTurnCount(prev => prev + 1);
    }, Math.floor(2000 / battleSpeedRef.current));

    return () => clearInterval(battleInterval);
  }, [battleEnded, playerTeam, enemyTeam, battleHP, isPlayerTurn, skillButtons, executeBattleAction]);

  // 显示伤害数值 - 完全复用1v1
  const showDamage = (damage, targetType, targetIndex, isCritical = false) => {
    const damageDiv = document.createElement('div');
    damageDiv.textContent = isCritical ? `暴击! -${damage}` : `-${damage}`;
    
    const targetPos = getCharacterPosition(targetType === 'player' ? 'player' : 'enemy', targetIndex, targetType === 'player' ? playerTeam.length : enemyTeam.length);
    
    damageDiv.style.cssText = `
      position: fixed;
      top: ${targetPos.top};
      left: ${targetPos.left};
      transform: translate(-50%, -50%);
      color: ${isCritical ? '#FF0000' : '#FFD700'};
      font-size: ${isCritical ? '20px' : '16px'};
      font-weight: bold;
      text-shadow: 2px 2px 4px rgba(0,0,0,0.8);
      z-index: 2001;
      pointer-events: none;
      animation: damageFloat 1.5s ease-out forwards;
    `;
    
    document.body.appendChild(damageDiv);
    
    setTimeout(() => {
      if (damageDiv.parentNode) damageDiv.parentNode.removeChild(damageDiv);
    }, 1500);
  };

  // 显示法术名称 - 完全复用1v1
  const showSpellName = (spellName, casterType, casterIndex = 0) => {
    const spellDiv = document.createElement('div');
    spellDiv.textContent = spellName;
    
    const casterPos = getCharacterPosition(casterType === 'player' ? 'player' : 'enemy', casterIndex, casterType === 'player' ? playerTeam.length : enemyTeam.length);
    
    spellDiv.style.cssText = `
      position: fixed;
      top: calc(${casterPos.top} + 50px);
      left: ${casterPos.left};
      transform: translate(-50%, -50%);
      color: ${casterType === 'player' ? '#FFD700' : '#FF6B6B'};
      font-size: 20px;
      font-weight: bold;
      text-shadow: 2px 2px 4px rgba(0,0,0,0.8);
      z-index: 2000;
      pointer-events: none;
      animation: spellNameAppear 2s ease-out forwards;
      font-family: serif;
    `;
    
    document.body.appendChild(spellDiv);
    
    setTimeout(() => {
      if (spellDiv.parentNode) spellDiv.parentNode.removeChild(spellDiv);
    }, 2000);
  };

  // 减少HP - 企业级HP管理
  const reduceHP = (targetType, targetIndex, damage) => {
    setBattleHP(prev => {
      const newHP = { ...prev };
      
      if (targetType === 'player') {
        const newPlayerHP = [...newHP.playerTeam];
        newPlayerHP[targetIndex] = Math.max(0, newPlayerHP[targetIndex] - damage);
        newHP.playerTeam = newPlayerHP;
        
        if (newPlayerHP[targetIndex] <= 0) {
          setDeathAnimations(prevAnim => {
            const newAnims = { ...prevAnim };
            newAnims.playerTeam[targetIndex] = true;
            return newAnims;
          });
        }
      } else {
        const newEnemyHP = [...newHP.enemyTeam];
        newEnemyHP[targetIndex] = Math.max(0, newEnemyHP[targetIndex] - damage);
        newHP.enemyTeam = newEnemyHP;
        
        if (newEnemyHP[targetIndex] <= 0) {
          setDeathAnimations(prevAnim => {
            const newAnims = { ...prevAnim };
            newAnims.enemyTeam[targetIndex] = true;
            return newAnims;
          });
        }
      }
      
      return newHP;
    });
  };

  // 45度斜线布局 - 整体向左移动，更协调分布
  const getCharacterPosition = (team, position, totalCount = 3) => {
    if (team === 'player') {
      // 我方团队 - 下方，整体左移15%
      if (totalCount === 1) {
        return { top: '55%', left: '60%' };  // 参考单人玩家位置，左移
      } else if (totalCount === 2) {
        return position === 0 
          ? { top: '60%', left: '30%' }  // 主角左侧，左移
          : { top: '50%', left: '60%' }; // 队友右侧，左移
      } else {
        // 三人：更协调的分布
        return position === 0 
          ? { top: '55%', left: '40%' }  // 主角中心，左移
          : position === 1 
            ? { top: '65%', left: '15%' }  // 队友1左边，左移
            : { top: '45%', left: '65%' }; // 队友2右边，左移
      }
    } else {
      // 敌方团队 - 上方，整体左移15%
      if (totalCount === 1) {
        return { top: '20%', left: '15%' };  // 参考单人敌人位置，左移
      } else if (totalCount === 2) {
        return position === 0 
          ? { top: '20%', left: '40%' }  // Boss居中，左移
          : { top: '30%', left: '15%' }; // 小弟左边，左移
      } else {
        // 三人：更协调的分布
        return position === 0 
          ? { top: '20%', left: '40%' }  // Boss居中，左移
          : position === 1 
            ? { top: '30%', left: '15%' }  // 小弟1左边，左移
            : { top: '10%', left: '65%' }; // 小弟2右边，左移
      }
    }
  };

  // 企业级角色渲染 - 完全按1v1标准
  const renderCharacterAvatar = (unit, team, index) => {
    const teamCount = team === 'player' ? playerTeam.length : enemyTeam.length;
    const position = getCharacterPosition(team, index, teamCount);
    const isPlayer = team === 'player';
    const currentHp = isPlayer ? battleHP.playerTeam[index] : battleHP.enemyTeam[index];
    const maxHp = isPlayer ? getMaxHP([unit])[0] : getMaxHP([unit])[0];
    const isDead = currentHp <= 0;
    const isDeathAnim = isPlayer ? deathAnimations.playerTeam[index] : deathAnimations.enemyTeam[index];

    return (
      <div 
        key={`${team}-${index}`}
        style={{
          position: 'absolute',
          top: position.top,
          left: position.left,
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          transform: isDeathAnim 
            ? 'scale(1) translateY(30px) rotateZ(90deg)' 
            : 'scale(1)',
          transition: 'all 0.3s ease',
          opacity: isDeathAnim ? 0.7 : 1,
          borderRadius: '10px',
          padding: '5px'
        }}
      >
        {/* 角色头像 */}
        <div data-character={`${team}-${index}`} style={{
          width: unit.role === 'boss' ? '65px' : '55px',
          height: unit.role === 'boss' ? '65px' : '55px',
          borderRadius: '50%',
          background: isPlayer 
            ? 'linear-gradient(135deg, #4169E1, #32CD32)'
            : unit.role === 'boss' 
              ? 'linear-gradient(135deg, #8B0000, #DC143C)'
              : 'linear-gradient(135deg, #6c757d, #495057)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          fontSize: unit.role === 'boss' ? '28px' : '24px',
          marginBottom: '8px',
          border: `3px solid ${isPlayer ? '#32CD32' : unit.role === 'boss' ? '#DC143C' : '#6c757d'}`,
          boxShadow: `0 4px 12px rgba(${isPlayer ? '50,205,50' : unit.role === 'boss' ? '220,20,60' : '108,117,125'}, 0.5)`,
          position: 'relative'
        }}>
          {unit.avatar || (isPlayer ? '🧙‍♂️' : '👹')}
          
          {/* 等级标识 */}
          <div style={{
            position: 'absolute',
            bottom: '-5px',
            right: '-5px',
            background: isPlayer ? '#FFD700' : '#8B0000',
            borderRadius: '50%',
            width: '20px',
            height: '20px',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontSize: '8px',
            fontWeight: 'bold',
            color: isPlayer ? '#000' : 'white'
          }}>
            {unit.level || (isPlayer ? character.level || 1 : 20)}
          </div>
        </div>
        
        {/* 角色信息 */}
        <div style={{
          background: isPlayer ? 'rgba(50, 205, 50, 0.8)' : unit.role === 'boss' ? 'rgba(139, 0, 0, 0.8)' : 'rgba(108, 117, 125, 0.8)',
          borderRadius: '6px',
          padding: '6px 10px',
          minWidth: '80px',
          textAlign: 'center'
        }}>
          <div style={{ color: '#FFD700', fontSize: '9px', fontWeight: 'bold', marginBottom: '8px' }}>
            {unit.name || (isPlayer ? '玩家' : '敌人')}  
            {isDead && ' 💀'}
          </div>
          <div style={{
            background: isPlayer ? 'rgba(50, 205, 50, 0.2)' : 'rgba(255, 68, 68, 0.2)',
            borderRadius: '8px',
            height: '6px',
            position: 'relative',
            marginTop: '4px'
          }}>
            <div style={{
              background: isPlayer ? 'linear-gradient(90deg, #32CD32, #90EE90)' : 'linear-gradient(90deg, #FF4444, #FF6B6B)',
              height: '100%',
              width: `${Math.max(0, (currentHp || 0) / maxHp * 100)}%`,
              borderRadius: '8px',
              transition: 'width 1s ease-out'
            }} />
            <div style={{
              position: 'absolute',
              bottom: '-12px',
              left: '0',
              right: '0',
              fontSize: '7px',
              color: 'white',
              textAlign: 'center'
            }}>
              {currentHp || 0}/{maxHp}
            </div>
          </div>
        </div>
      </div>
    );
  };

  // 退出战斗 - 完全复用1v1
  const handleEndBattle = () => {
    soundEffects.playButtonClick?.();
    dispatch(endBattle());
  };

  if (!wendaoBattle.showBattleUI || playerTeam.length === 0 || enemyTeam.length === 0) return null;

  return (
    <div style={{
      position: 'fixed',
      top: 0,
      left: '50%',
      transform: `translateX(-50%) ${screenShake ? 'translateY(-3px)' : 'translateY(0)'}`,
      width: '100vw',
      maxWidth: '432px',
      height: '100vh',
      background: 'linear-gradient(135deg, #1a0f0a 0%, #2d1b0f 50%, #3d2817 100%)',
      zIndex: 1000,
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", "Roboto", sans-serif',
      color: '#ffffff',
      transition: screenShake ? 'none' : 'transform 0.3s ease',
      animation: screenShake ? 'battleShake 0.3s ease-in-out' : 'none'
    }}>
      
      {/* 顶部标题栏 - 和单人一样简洁 */}
      <div style={{
        background: 'linear-gradient(135deg, #342016 0%, #4a2c1a 100%)',
        border: '1px solid rgba(212, 175, 55, 0.4)',
        borderRadius: '0 0 15px 15px',
        padding: '10px 15px',
        boxShadow: '0 2px 8px rgba(0, 0, 0, 0.3)',
        fontSize: '14px',
        fontWeight: 'bold',
        textAlign: 'center'
      }}>
        ⚔️ 3v3团战 - 第 {turnCount} 回合
      </div>

      {/* 主战斗区域 - 企业级3v3布局 */}
      <div 
        style={{
          flex: 1,
          height: 'calc(100vh - 200px)',
          position: 'relative',
          padding: '20px'
        }}
      >
        {/* 渲染敌方队伍 - 上方斜列 */}
        {enemyTeam.map((unit, index) => renderCharacterAvatar(unit, 'enemy', index))}

        {/* 渲染我方队伍 - 下方斜列 */}
        {playerTeam.map((unit, index) => renderCharacterAvatar(unit, 'player', index))}
      </div>

      {/* 底部控制面板 - 完全复用1v1设计 */}
      <div style={{
        position: 'absolute',
        bottom: '0',
        left: '0',
        right: '0',
        background: 'linear-gradient(135deg, #342016 0%, #4a2c1a 100%)',
        border: '1px solid rgba(212, 175, 55, 0.4)',
        borderRadius: '15px 15px 0 0',
        padding: '8px 10px',
        display: 'flex',
        flexDirection: 'column',
        gap: '8px',
        boxShadow: '0 -2px 15px rgba(0, 0, 0, 0.5)',
        zIndex: 1001,
        minHeight: '100px'
      }}>
        
        {/* 自动战斗状态显示 */}
        <div style={{
          textAlign: 'center',
          color: '#FFD700',
          fontSize: '14px',
          fontWeight: 'bold'
        }}>
          ⚡ 3v3自动战斗中...
        </div>
        
        {/* 控制按钮区 */}
        <div style={{
          display: 'flex',
          gap: '8px',
          justifyContent: 'center'
        }}>
          <button
            onClick={() => {
              const newSpeed = battleSpeed >= 3 ? 1 : battleSpeed + 1;
              setBattleSpeed(newSpeed);
              battleSpeedRef.current = newSpeed;
              soundEffects.playButtonClick?.();
            }}
            style={{
              background: battleSpeed === 3 ? '#FFD700' : battleSpeed === 2 ? '#4169E1' : '#696969',
              border: '2px solid rgba(255, 255, 255, 0.2)',
              borderRadius: '20px',
              padding: '6px 12px',
              color: 'white',
              fontSize: '11px',
              fontWeight: 'bold',
              cursor: 'pointer',
              boxShadow: '0 4px 15px rgba(0,0,0,0.4)',
              minWidth: '60px',
              transition: 'all 0.3s ease'
            }}
          >
            ⚡ {battleSpeed}x
          </button>
          
          <button
            onClick={handleEndBattle}
            style={{
              background: 'linear-gradient(135deg, #DC143C 0%, #B22222 100%)',
              border: '2px solid rgba(255, 255, 255, 0.2)',
              borderRadius: '20px',
              padding: '6px 12px',
              color: 'white',
              fontSize: '11px',
              fontWeight: 'bold',
              cursor: 'pointer',
              boxShadow: '0 4px 15px rgba(0,0,0,0.4)',
              minWidth: '60px',
              transition: 'all 0.3s ease'
            }}
          >
            🚺 退出
          </button>
        </div>
      </div>
      {/* 企业级CSS动画 - 完全复用1v1 */}
      <style>{`
        @keyframes spellNameAppear {
          0% { 
            opacity: 0;
            transform: translate(-50%, -50%) scale(0.5) rotateY(90deg);
            filter: blur(10px);
          }
          20% { 
            opacity: 1;
            transform: translate(-50%, -50%) scale(1.3) rotateY(0deg);
            filter: blur(0px);
          }
          80% { 
            opacity: 1;
            transform: translate(-50%, -50%) scale(1.1) rotateY(0deg);
            filter: blur(0px);
          }
          100% { 
            opacity: 0;
            transform: translate(-50%, -50%) scale(0.8) rotateY(-90deg);
            filter: blur(5px);
          }
        }
        
        @keyframes battleShake {
          0%, 100% { transform: translateX(-50%) translateY(0); }
          25% { transform: translateX(-50%) translateY(-3px); }
          75% { transform: translateX(-50%) translateY(3px); }
        }
        
        @keyframes damageFloat {
          0% { 
            opacity: 1; 
            transform: translate(-50%, -50%) scale(1.2); 
          }
          50% { 
            opacity: 1; 
            transform: translate(-50%, -70px) scale(1); 
          }
          100% { 
            opacity: 0; 
            transform: translate(-50%, -100px) scale(0.8); 
          }
        }
        
        @keyframes physicalCharge {
          0% { 
            transform: translate(-50%, -50%) scale(1);
            opacity: 0.8;
          }
          50% { 
            transform: translate(-50%, -50%) scale(1.5);
            opacity: 1;
            box-shadow: 0 0 50px #FFD700;
          }
          100% { 
            transform: translate(-50%, -50%) scale(2);
            opacity: 0;
            box-shadow: 0 0 80px #FFA500;
          }
        }
        
        @keyframes shockWaveExplosion {
          0% { 
            transform: translate(-50%, -50%) scale(0);
            opacity: 1;
          }
          50% { 
            transform: translate(-50%, -50%) scale(3);
            opacity: 0.8;
            box-shadow: 0 0 60px #FF6B6B;
          }
          100% { 
            transform: translate(-50%, -50%) scale(6);
            opacity: 0;
            box-shadow: 0 0 100px #FF4500;
          }
        }
        
        @keyframes ringExpansion {
          0% { 
            transform: translate(-50%, -50%) scale(0);
            opacity: 1;
          }
          100% { 
            transform: translate(-50%, -50%) scale(4);
            opacity: 0;
          }
        }
        
        @keyframes magicAura {
          0%, 100% { 
            transform: translate(-50%, -50%) scale(1) rotate(0deg);
            opacity: 0.8;
          }
          50% { 
            transform: translate(-50%, -50%) scale(1.3) rotate(180deg);
            opacity: 1;
          }
        }
        
        @keyframes hitFlash {
          0% { 
            transform: translate(-50%, -50%) scale(0);
            opacity: 1;
          }
          30% { 
            transform: translate(-50%, -50%) scale(1.2);
            opacity: 0.9;
          }
          100% { 
            transform: translate(-50%, -50%) scale(0.5);
            opacity: 0;
          }
        }
      `}</style>
    </div>
  );
}

export default Wendao3v3BattleUI;