/**
 * 音效反馈系统
 * 使用Web Audio API生成游戏音效
 */

class SoundEffects {
  constructor() {
    this.audioContext = null;
    this.enabled = true;
    this.volume = 0.3;
    this.init();
  }

  init() {
    try {
      this.audioContext = new (window.AudioContext || window.webkitAudioContext)();
    } catch (error) {
      console.warn('音效系统初始化失败:', error);
      this.enabled = false;
    }
  }

  // 创建音效
  playTone(frequency, duration, waveType = 'sine', volume = this.volume) {
    if (!this.enabled || !this.audioContext) return;

    try {
      const oscillator = this.audioContext.createOscillator();
      const gainNode = this.audioContext.createGain();

      oscillator.connect(gainNode);
      gainNode.connect(this.audioContext.destination);

      oscillator.frequency.value = frequency;
      oscillator.type = waveType;

      gainNode.gain.setValueAtTime(0, this.audioContext.currentTime);
      gainNode.gain.linearRampToValueAtTime(volume, this.audioContext.currentTime + 0.01);
      gainNode.gain.exponentialRampToValueAtTime(0.001, this.audioContext.currentTime + duration);

      oscillator.start(this.audioContext.currentTime);
      oscillator.stop(this.audioContext.currentTime + duration);
    } catch (error) {
      console.warn('音效播放失败:', error);
    }
  }

  // 按钮点击音效 - 柔和版本
  playButtonClick() {
    this.playTone(400, 0.15, 'sine', 0.1);
  }

  // 悬浮音效
  playButtonHover() {
    this.playTone(600, 0.05, 'sine', 0.1);
  }

  // 妖王选择音效
  playBossSelect() {
    this.playTone(400, 0.2, 'sawtooth', 0.3);
    setTimeout(() => this.playTone(600, 0.15, 'sine', 0.2), 100);
  }

  // 战斗准备音效
  playBattleReady() {
    // 战鼓音效模拟
    for (let i = 0; i < 3; i++) {
      setTimeout(() => {
        this.playTone(80, 0.1, 'square', 0.4);
      }, i * 200);
    }
    
    // 号角音效
    setTimeout(() => {
      this.playTone(220, 0.3, 'triangle', 0.3);
      setTimeout(() => this.playTone(330, 0.3, 'triangle', 0.3), 150);
      setTimeout(() => this.playTone(440, 0.4, 'triangle', 0.3), 300);
    }, 600);
  }

  // 警告音效
  playWarning() {
    this.playTone(1200, 0.1, 'sawtooth', 0.3);
    setTimeout(() => this.playTone(1200, 0.1, 'sawtooth', 0.3), 150);
  }

  // 错误音效
  playError() {
    this.playTone(200, 0.2, 'square', 0.3);
    setTimeout(() => this.playTone(150, 0.3, 'square', 0.3), 200);
  }

  // 成功音效
  playSuccess() {
    this.playTone(523, 0.1, 'sine', 0.3); // C
    setTimeout(() => this.playTone(659, 0.1, 'sine', 0.3), 100); // E
    setTimeout(() => this.playTone(784, 0.2, 'sine', 0.3), 200); // G
  }

  // 妖王出现音效
  playBossAppear() {
    // 低沉的妖王音效
    this.playTone(60, 0.5, 'sawtooth', 0.4);
    setTimeout(() => this.playTone(80, 0.4, 'square', 0.3), 200);
    setTimeout(() => this.playTone(100, 0.3, 'triangle', 0.2), 400);
  }

  // 五行音效
  playElementSound(element) {
    const elementSounds = {
      金: () => this.playTone(880, 0.15, 'sine', 0.25),      // 金属碰撞
      木: () => this.playTone(220, 0.2, 'triangle', 0.3),    // 木质低音
      水: () => this.playTone(440, 0.3, 'sine', 0.2),       // 流水声
      火: () => this.playTone(1320, 0.12, 'sawtooth', 0.35), // 火焰燃烧
      土: () => this.playTone(110, 0.25, 'square', 0.3)      // 大地沉重
    };

    if (elementSounds[element]) {
      elementSounds[element]();
    }
  }

  // 🗡️ 战斗音效系统
  
  // 普通攻击音效
  playPhysicalAttack() {
    // 剑击音效 - 快速高音到低音
    this.playTone(1200, 0.08, 'square', 0.4);
    setTimeout(() => this.playTone(600, 0.12, 'sawtooth', 0.3), 50);
  }

  // 法术攻击音效
  playMagicAttack() {
    // 魔法音效 - 上升音调
    this.playTone(300, 0.15, 'sine', 0.25);
    setTimeout(() => this.playTone(600, 0.15, 'triangle', 0.3), 80);
    setTimeout(() => this.playTone(900, 0.1, 'sine', 0.2), 150);
  }

  // 受伤音效
  playTakeDamage() {
    // 受击音效 - 低沉的撞击声
    this.playTone(150, 0.2, 'square', 0.35);
    setTimeout(() => this.playTone(80, 0.15, 'sawtooth', 0.25), 100);
  }

  // 暴击音效
  playCriticalHit() {
    // 暴击音效 - 强烈的冲击声
    this.playTone(1500, 0.05, 'square', 0.5);
    setTimeout(() => this.playTone(800, 0.1, 'sawtooth', 0.4), 30);
    setTimeout(() => this.playTone(400, 0.15, 'triangle', 0.3), 80);
  }

  // 治疗音效
  playHeal() {
    // 治疗音效 - 温和的上升音调
    for (let i = 0; i < 4; i++) {
      setTimeout(() => {
        this.playTone(440 + i * 110, 0.1, 'sine', 0.2);
      }, i * 60);
    }
  }

  // 闪避音效
  playDodge() {
    // 闪避音效 - 快速滑音
    this.playTone(800, 0.08, 'triangle', 0.15);
    setTimeout(() => this.playTone(1200, 0.06, 'sine', 0.1), 40);
  }

  // 死亡音效
  playDeath() {
    // 死亡音效 - 下降音调
    this.playTone(400, 0.3, 'sawtooth', 0.4);
    setTimeout(() => this.playTone(300, 0.4, 'triangle', 0.3), 150);
    setTimeout(() => this.playTone(200, 0.5, 'sine', 0.2), 300);
  }

  // 战斗胜利音效
  playBattleVictory() {
    // 胜利音效 - 凯旋进行曲风格
    const melody = [523, 659, 784, 1047]; // C, E, G, C
    melody.forEach((freq, i) => {
      setTimeout(() => {
        this.playTone(freq, 0.2, 'triangle', 0.3);
      }, i * 150);
    });
  }

  // 战斗失败音效
  playBattleDefeat() {
    // 失败音效 - 悲伤的下降音调
    const melody = [523, 440, 349, 294]; // C, A, F, D
    melody.forEach((freq, i) => {
      setTimeout(() => {
        this.playTone(freq, 0.25, 'sine', 0.25);
      }, i * 200);
    });
  }

  // 设置音量
  setVolume(volume) {
    this.volume = Math.max(0, Math.min(1, volume));
  }

  // 启用/禁用音效
  setEnabled(enabled) {
    this.enabled = enabled;
  }

  // 恢复音频上下文（用户交互后）
  resume() {
    if (this.audioContext && this.audioContext.state === 'suspended') {
      this.audioContext.resume();
    }
  }
}

// 创建单例
export const soundEffects = new SoundEffects();

// 自动恢复音频上下文
document.addEventListener('click', () => soundEffects.resume(), { once: true });
document.addEventListener('touchstart', () => soundEffects.resume(), { once: true });

export default soundEffects;